/* 10వ తరగతి – tel పూర్తి పాఠాలు (tools/split/split_class10.py) */
((window.RAAY_TBF=window.RAAY_TBF||{})[10]=window.RAAY_TBF[10]||{})["tel"]=[{"id":"te1","no":1,"t":"ప్రత్యక్ష దైవాలు","m":[6],"ty":"ఇతిహాసం (పద్యపాఠం)","th":"తల్లిదండ్రుల సేవ","by":"ఎఱ్ఱన – మహాభారతం, అరణ్యపర్వం (5వ ఆశ్వాసం)","sum":"అరణ్యవాసంలో ఉన్న ధర్మరాజుకు మార్కండేయ మహర్షి కౌశికుని కథ చెబుతాడు. కౌశికుడు తల్లిదండ్రుల అనుమతి లేకుండా వేదాధ్యయనానికి వెళ్ళిపోతాడు. ఒక పతివ్రత సూచనతో మిథిలా నగరంలోని ధర్మవ్యాధుని దగ్గరకు ధర్మసూక్ష్మాలు తెలుసుకోవడానికి వస్తాడు. ధర్మవ్యాధుడు అతనిని ఇంటిలోకి తీసుకువెళ్ళి, ఆనందంగా ఉన్న తన తల్లిదండ్రులను చూపిస్తాడు. \"వీరే నా ప్రత్యక్ష దైవాలు; వీరి సేవ వల్లే నాకు ఈ జ్ఞానం లభించింది. తల్లి, తండ్రి, గురువు, అగ్ని, ఆత్మ – ఈ ఐదుగురిని సంతోషపెట్టే గృహస్థుడే ధర్మాత్ముడు\" అని చెబుతాడు. నీవు వెళ్ళిపోయిన దుఃఖంతో నీ తల్లిదండ్రులు ఏడ్చి ఏడ్చి చూపు కోల్పోయారు, వెళ్ళి వారి దుఃఖాగ్నిని చల్లార్చు అని హితవు చెబుతాడు. కౌశికుడు తన తప్పు తెలుసుకుని తల్లిదండ్రులను సేవిస్తానని మాట ఇస్తాడు.","pts":["కవి: ఎఱ్ఱన (క్రీ.శ. 14వ శతాబ్దం) – కవిత్రయంలో మూడవ కవి; ప్రోలయ వేమారెడ్డి ఆస్థాన కవి; తల్లిదండ్రులు పోతమ్మ, సూరన; జన్మస్థలం గుడ్లూరు (పాకనాడు).","రచనలు: రామాయణం, హరివంశం, అరణ్యపర్వశేషం, నృసింహపురాణం. బిరుదులు: శంభుదాసుడు, ప్రబంధ పరమేశ్వరుడు. శైలి: సూక్తివైచిత్రి.","ప్రక్రియ: ఇతిహాసం – \"ఇలా జరిగింది\" అని అర్థం; రామాయణ, మహాభారతాలు ఇతిహాసాలు.","కథ చెప్పినది: మార్కండేయ మహర్షి → ధర్మరాజుకు.","ధర్మవ్యాధుడు తల్లిదండ్రులకు ఇష్టమైన పండ్లు, పూలు, గంధం, వస్త్రాలు, ఆభరణాలు, భక్ష్యభోజ్యాలు సమర్పించి ఆలుబిడ్డలతో సేవిస్తాడు.","తల్లి, తండ్రి, గురువు, అగ్ని, ఆత్మ – ఈ ఐదుగురిని ప్రసన్నం చేసేవాడే ధర్మాత్ముడు.","కౌశికుని తల్లిదండ్రులు పుత్రుని ఎడబాటుతో ఏడ్చి చూపు కోల్పోయారు.","తల్లిదండ్రుల సేవ లేకపోతే అధ్యయనం, శ్రమ నిష్ఫలం అని ధర్మవ్యాధుని హితవు."],"w":[["జనకుడు","తండ్రి"],["జనని","తల్లి"],["హర్మ్యం","మేడ"],["వాంఛ","కోరిక"],["వాక్కు","మాట"],["హితము","మేలు"],["చక్షువు","కన్ను"],["వహ్ని","అగ్ని"],["వసుధ","భూమి"],["అనఘుడు","పాపం లేనివాడు"],["ముదుసళ్ళు","వృద్ధులు"],["శుశ్రూష","సేవ"]],"gr":{"t":"భాషాంశాలు","p":["త్రిక సంధి: ఆ, ఈ, ఏ లు త్రికాలు – ఈ + మహాత్ముడు = ఇమ్మహాత్ముడు; ఆ + విప్రుడు = అవ్విప్రుడు.","రూపకాలంకారం: ఉపమేయ, ఉపమానాలకు అభేదం – శోకవహ్ని (శోకమనెడు అగ్ని), సంసారసాగరం.","ద్వంద్వ సమాసం: జననీజనకులు, ఫలపుష్పములు; రూపక సమాసం: శోకవహ్ని.","ఛందస్సు: ఉత్పలమాల (భ ర న భ భ ర వ, యతి 10), చంపకమాల (న జ భ జ జ జ ర, యతి 11), ఆటవెలది (1,3 పాదాలు 3 సూర్య + 2 ఇంద్ర; 2,4 పాదాలు 5 సూర్యగణాలు)."]},"qa":[["ధర్మవ్యాధుని కథ ఎవరు ఎవరికి చెప్పారు?","మార్కండేయ మహర్షి ధర్మరాజుకు చెప్పాడు."],["కౌశికుని తల్లిదండ్రులు చూపు ఎందుకు కోల్పోయారు?","ఏకైక కుమారుడు అనుమతి లేకుండా వెళ్ళిపోయిన దుఃఖంతో ఏడ్చి ఏడ్చి."],["గృహస్థుడు ఎవరిని సంతోషపెట్టాలి?","తల్లి, తండ్రి, గురువు, అగ్ని, ఆత్మ – ఐదుగురిని."],["ఎఱ్ఱన బిరుదులు?","శంభుదాసుడు, ప్రబంధ పరమేశ్వరుడు."],["ఈ పాఠం ఏ గ్రంథం నుండి?","మహాభారతం – అరణ్యపర్వం, ఐదవ ఆశ్వాసం."]],"act":"తల్లిదండ్రుల సేవకు పేరుపొందిన శ్రవణకుమారుడు, శ్రీరాముడు, భీష్ముడు, గరుత్మంతుడు, శివాజీ – వీరిలో ఇద్దరి కథలు సేకరించి తరగతిలో చెప్పండి. \"తల్లిదండ్రుల సేవ\" అంశంపై ఏకపాత్రాభినయం చేయండి.","kn":"ఐక్యరాజ్య సమితి 2012 నుండి జూన్ 1 ను \"ప్రపంచ తల్లిదండ్రుల దినోత్సవం\" గా ప్రకటించింది. భారతదేశంలో వృద్ధులైన తల్లిదండ్రుల పోషణ బాధ్యత పిల్లలదే అని 2007 లో చట్టం కూడా వచ్చింది.","qz":[["ప్రత్యక్ష దైవాలు పాఠం రచయిత?","ఎఱ్ఱన","నన్నయ","తిక్కన","పోతన"],["ఎఱ్ఱన ఎవరి ఆస్థాన కవి?","ప్రోలయ వేమారెడ్డి","శ్రీకృష్ణదేవరాయలు","రాజరాజ నరేంద్రుడు","కాకతీయ రుద్రదేవుడు"],["ఈ పాఠం మహాభారతంలోని ఏ పర్వం?","అరణ్యపర్వం","ఆదిపర్వం","సభాపర్వం","విరాటపర్వం"],["ధర్మవ్యాధుని కథ చెప్పినది?","మార్కండేయ మహర్షి","వ్యాసుడు","నారదుడు","విదురుడు"],["కౌశికుని ధర్మవ్యాధుని దగ్గరకు పంపినది?","ఒక పతివ్రత","అతని గురువు","అతని తండ్రి","ఒక పక్షి"],["ధర్మవ్యాధుడు ఉన్న నగరం?","మిథిల","అయోధ్య","హస్తినాపురం","ద్వారక"],["గృహస్థుడు సంతోషపెట్టవలసిన వారు ఎంతమంది?","ఐదుగురు","ముగ్గురు","నలుగురు","ఏడుగురు"],["ఎఱ్ఱన బిరుదు?","ప్రబంధ పరమేశ్వరుడు","కవిబ్రహ్మ","ఆదికవి","సహజ పండితుడు"],["\"శోకవహ్ని\" లో అలంకారం?","రూపకాలంకారం","ఉపమాలంకారం","ఉత్ప్రేక్ష","అతిశయోక్తి"],["ఈ + మహాత్ముడు = ?","ఇమ్మహాత్ముడు","ఈమహాత్ముడు","ఇమహాత్ముడు","యీమహాత్ముడు"],["\"జననీజనకులు\" ఏ సమాసం?","ద్వంద్వ సమాసం","ద్విగు సమాసం","బహువ్రీహి","తత్పురుష"],["వహ్ని అంటే?","అగ్ని","నీరు","గాలి","భూమి"],["కౌశికుని తల్లిదండ్రుల పరిస్థితి?","దుఃఖంతో చూపు కోల్పోయారు","ధనవంతులయ్యారు","తీర్థయాత్రకు వెళ్ళారు","సంతోషంగా ఉన్నారు"],["ఉత్పలమాల గణాలు?","భ ర న భ భ ర వ","న జ భ జ జ జ ర","స భ ర న మ య వ","మ స జ స త త గ"],["ఆటవెలది 2, 4 పాదాల్లో గణాలు?","ఐదు సూర్యగణాలు","మూడు సూర్య + రెండు ఇంద్ర","ఆరు ఇంద్రగణాలు","నాలుగు సూర్యగణాలు"],["ఎఱ్ఱన జన్మస్థలం?","గుడ్లూరు (నెల్లూరు జిల్లా)","అద్దంకి","రాజమండ్రి","హంపి"]],"wb":{"mis":"ప్రతిపదార్థాల్లో పదాలను పద్యంలోని క్రమంలో కాకుండా అన్వయ క్రమంలో రాయాలి. అర్థసందర్భంలో కవి, పాఠం, గ్రంథం, ఎవరు–ఎవరితో అన్నారు, సందర్భం, అర్థం – అన్నీ రాయాలి.","qz":[["జ్ఞాన + అర్థంబు – సంధి?","సవర్ణదీర్ఘ సంధి","గుణ సంధి","యణాదేశ సంధి","వృద్ధి సంధి"],["విజ్ఞాన + ఉన్నతి = ?","విజ్ఞానోన్నతి – గుణ సంధి","విజ్ఞానూన్నతి","విజ్ఞానున్నతి","విజ్ఞానౌన్నతి"],["అభి + అంతరం – సంధి?","యణాదేశ సంధి","సవర్ణదీర్ఘ","గుణ","త్రిక"],["నిజంబగు విడదీస్తే?","నిజంబు + అగు (ఉకార సంధి)","నిజం + బగు","నిజంబ + గు","నిజ + అంబగు"],["\"ధర్మపథం\" సమాసం?","విశేషణ పూర్వపద కర్మధారయం","ద్వంద్వం","షష్ఠీ తత్పురుషం","బహువ్రీహి"],["\"మానుషదేహం\" సమాసం?","షష్ఠీ తత్పురుషం","ద్వంద్వం","ద్విగు","రూపక"],["చక్షువు పర్యాయపదాలు?","కన్ను, నేత్రం, నయనం","చెవి, కర్ణం","ముక్కు, నాసిక","నోరు, ముఖం"],["వసుధ వ్యుత్పత్తి?","సంపదలను ధరించునది (భూమి)","నీటిని ధరించునది","గాలిని ధరించునది","కాంతినిచ్చునది"],["\"అనుపమ మెట్టివారలకు…\" ఏ పద్యం?","చంపకమాల","ఉత్పలమాల","శార్దూలం","మత్తేభం"],["\"సంసార సాగరం\" అలంకారం?","రూపకాలంకారం","ఉపమ","యమకం","శ్లేష"]],"pg":"1–14","f":"books/10/Class10_Telugu_Textbook_Sem1.pdf","p":9,"lb":"పాఠ్యపుస్తకం","ws":["అవగాహన – ప్రతిస్పందన: అ) ప్రశ్నలు (పుట 6)","అవగాహన: ఆ) పద్యం – ప్రశ్నలు (పుట 7)","అవగాహన: ఇ) అపరిచిత గద్యం, ఈ) అర్థసందర్భాలు, ఉ) ఏకవాక్య సమాధానాలు; వ్యక్తీకరణ: అ) లఘు సమాధానాలు (పుట 8)","వ్యక్తీకరణ: ఆ) వ్యాసరూప, ఇ) సృజనాత్మకం; భాషాంశాలు – పదజాలం అ, ఆ, ఇ (పుట 9)","భాషాంశాలు: ఈ) వ్యుత్పత్త్యర్థాలు, ఉ) ప్రకృతి–వికృతి; సంధులు అ) (పుట 10)","సంధులు ఆ), ఇ) త్రికసంధి; సమాసాలు ఈ), ఉ) (పుట 11)","అలంకారం, ఛందస్సు (పుట 12)","ఆటవెలది సమన్వయం, ఆధునిక వచనం, ప్రాజెక్టు (పుట 13)"]},"tg":[["అవగాహన – ప్రతిస్పందన: అ) ప్రశ్నలు (పుట 6)",["1) కౌశికుడు తల్లిదండ్రుల అనుమతి లేకుండా, వారి స్థితిగతులు పట్టించుకోకుండా వేదాధ్యయనానికి వెళ్ళిపోయాడు. ఒక్కగానొక్క కొడుకు దూరమైన దుఃఖంతో ఏడ్చి ఏడ్చి వారు చూపు కోల్పోయారు","2) ధర్మవ్యాధుడు మనసా, వాచా, కర్మణా వారిని సేవిస్తాడు; ఇష్టమైన ఆహారం, పండ్లు, పూలు, గంధం, వస్త్రాలు, ఆభరణాలు సమర్పిస్తాడు; భార్యాపిల్లలతో కలిసి సేవ చేస్తాడు – అందుకే వారు సంతోషంగా ఉన్నారు","3) తల్లి, తండ్రి, గురువు, అగ్ని, ఆత్మ – ఈ ఐదుగురిని","4) ప్రతిపదార్థం (8వ పద్యం): కట్టా = అయ్యో!; తమకున్ = వారికి; నీవు ఒకరుండవ = నీవొక్కడివే; ఎప్ప = ఆధారం; కాగన్ = కాగా; అత్యంత ముదంబునన్ = ఎంతో సంతోషంతో; బ్రదుకు = జీవించే; ఎంతయు వృద్ధులై = చాలా ముసలివారైన; తల్లిని దండ్రిని = తల్లిదండ్రులను; ఉజ్జగించి = విడిచి; నిశ్చింతుండవై = చింత లేనివాడవై; సదా అధ్యయనశీలతన్ = ఎప్పుడూ చదువుకోవాలనే కోరికతో; వారి అనుజ్ఞ లేక = వారి అనుమతి లేకుండా; ఏకాంతము = ఒంటరిగా; ఎమ్మెయిన్ = ఏ విధంగానో; వెడలితి = వెళ్ళిపోయావు; నీవు గరంబు క్రూరతన్ = నీవు ఎంతో కఠినంగా (ప్రవర్తించావు)"]],["అవగాహన: ఆ) పద్యం – ప్రశ్నలు (పుట 7)",["1) పిల్లలు తమపై భక్తి కలిగి ఉండాలని, ధర్మమార్గంలో నడవాలని కోరుకుంటారు","2) తొమ్మిది నెలలు కడుపులో ఎంతో భారంగా మోస్తుంది; ప్రసవ సమయంలో ప్రాణాపాయ స్థితిని అనుభవించి బిడ్డను కంటుంది","3) తండ్రి పుత్రుడు కలగాలని కోరుతూ తపస్సులు, యజ్ఞాలు, దానాలు, వ్రతాలు, దేవతా–సజ్జన సేవలు చేస్తాడు","4) ఉదా: తల్లిదండ్రుల ఆశలను నెరవేర్చే వాడిని ఏమంటారు? (జ: నిజమైన నందనుడు)"]],["అవగాహన: ఇ) అపరిచిత గద్యం, ఈ) అర్థసందర్భాలు, ఉ) ఏకవాక్య సమాధానాలు; వ్యక్తీకరణ: అ) లఘు సమాధానాలు (పుట 8)",["ఇ) 1) తన కాలేయంలో కొంత భాగాన్ని తండ్రికి దానం చేయాలనుకుంది 2) అనేక సమస్యలను ఎదుర్కొంటూ ఇంతటి త్యాగానికి సిద్ధమైనందుకు 3) శస్త్రచికిత్స ఖర్చులను ఆసుపత్రి యాజమాన్యం ఉపసంహరించింది (మాఫీ చేసింది) 4) ఉదా: దేవనంద తన కాలేయం దానం చేయడానికి ఏం చేసింది?","ఈ) 1) \"వాఁడ సువె ధర్మాత్ముండు వసుధ మీఁద\" – ఎఱ్ఱన రచించిన మహాభారతం అరణ్యపర్వంలోని \"ప్రత్యక్ష దైవాలు\" పాఠం. ధర్మవ్యాధుడు కౌశికునికి గృహస్థ ధర్మం చెప్పే సందర్భం. అర్థం: తల్లి, తండ్రి, గురువు, అగ్ని, ఆత్మలను సంతోషపెట్టే గృహస్థుడే భూమిపై ధర్మాత్ముడు","ఈ) 2) \"గురుజనములకుఁ బ్రీతిఁ జేసెద ననఘా!\" – అదే పాఠం. ధర్మవ్యాధుని హితవు విని కౌశికుడు అతనితో అన్న మాట. అర్థం: పాపం లేనివాడా! ఇకపై తల్లిదండ్రులు (పెద్దలు) సంతోషించేలా సేవ చేస్తాను","ఉ) 1) ఎఱ్ఱన ప్రోలయ వేమారెడ్డి ఆస్థాన కవి 2) మార్కండేయ మహర్షి ధర్మరాజుకు చెప్పాడు 3) తన తల్లిదండ్రులకు సేవ చేయడం తన ధర్మమని గ్రహించాడు 4) మహాభారతం, అరణ్యపర్వం (5వ ఆశ్వాసం)","వ్యక్తీకరణ అ) 1) \"వీరు నా తల్లిదండ్రులు; వీరి సేవ వల్లే నాకు ఈ జ్ఞానం వచ్చింది. అందరూ దేవతలను పూజిస్తారు; నాకు వీరే దేవతలు. పండ్లు, పూలు, గంధం, వస్త్రాలు, మంచి ఆహారం సమర్పించి భార్యాపిల్లలతో కలిసి సేవ చేస్తాను. వేదాలు, యజ్ఞాలు, వ్రతాలు అన్నీ నాకు వీరే\" అని తల్లిదండ్రుల సేవ గొప్పతనం చెప్పాడు","అ) 2) \"నాయనా! నీలాంటి సత్పుత్రుడు ఉండగా మాకేం లోటు? నువ్వు చేసే ధర్మమే నిన్ను కాపాడుతుంది; దీర్ఘాయువు, సంపదలు పొందు. నీ ప్రవర్తనతో మన వంశం పవిత్రమైంది. నువ్వు మనిషి రూపంలో ఉన్న దేవుడివి. మనసు, మాట, పనితో మమ్మల్ని ప్రేమిస్తున్నావు; పరశురాముని తర్వాత నిన్నే చెప్పుకోవాలి\" అని వ్యక్తీకరించారు","అ) 3) పుణ్యాన్ని కోరే గృహస్థుడు తల్లి, తండ్రి, గురువు, అగ్ని, ఆత్మ – ఈ ఐదుగురిని సంతోషపెట్టాలి. అలా చేసేవాడే ఈ భూమిపై నిజమైన ధర్మాత్ముడు అని ధర్మవ్యాధుడు చెప్పాడు"]],["వ్యక్తీకరణ: ఆ) వ్యాసరూప, ఇ) సృజనాత్మకం; భాషాంశాలు – పదజాలం అ, ఆ, ఇ (పుట 9)",["ఆ) 1) సారాంశం: మార్కండేయుడు ధర్మరాజుకు చెప్పిన కథ ఇది. కౌశికుడు తల్లిదండ్రులను విడిచి వేదాధ్యయనానికి వెళ్ళాడు. ఒక పతివ్రత మాట ప్రకారం ధర్మసూక్ష్మాలు తెలుసుకోవడానికి మిథిలలోని ధర్మవ్యాధుని దగ్గరకు వచ్చాడు. ధర్మవ్యాధుడు అతనిని తన ఇంటిలోకి తీసుకువెళ్ళి, సుఖంగా ఉన్న తన తల్లిదండ్రులను చూపించి నమస్కరించాడు. వారు కుమారుని ఆశీర్వదించారు. \"వీరే నా ప్రత్యక్ష దైవాలు; వీరి సేవ వల్లే జ్ఞానం పొందాను. తల్లి, తండ్రి, గురువు, అగ్ని, ఆత్మలను సంతోషపెట్టేవాడే ధర్మాత్ముడు\" అని చెప్పాడు. \"నీవు తల్లిదండ్రులను విడిచి రావడం క్రూరత్వం; వారు ఏడ్చి చూపు కోల్పోయారు; వారి సేవ లేకుంటే నీ చదువు నిష్ఫలం\" అని హితవు పలికాడు. కౌశికుడు తప్పు తెలుసుకుని తల్లిదండ్రులను సేవిస్తానని, ధర్మవ్యాధుని స్నేహం తన అదృష్టమని పలికాడు","ఆ) 2) ధర్మవ్యాధుడు వృత్తిరీత్యా సాధారణ వ్యక్తి అయినా గొప్ప జ్ఞాని; తల్లిదండ్రులను దైవంగా భావించే సత్పుత్రుడు; కుటుంబమంతా సేవలో పాల్గొనేలా చేసే బాధ్యతాయుత గృహస్థుడు; వినయశీలి – తన జ్ఞానానికి కారణం తల్లిదండ్రుల సేవేనని చెప్పుకున్నాడు; అతిథి మర్యాద తెలిసినవాడు; కౌశికుని తప్పును నిర్భయంగా కానీ ప్రేమగా చెప్పి సరిదిద్దిన హితైషి – ధర్మానికి ప్రతిరూపం","ఆ) 3) నేడు ఉద్యోగాలు, విదేశాల పేరుతో పిల్లలు దూరంగా వెళ్ళి వృద్ధులైన తల్లిదండ్రులను ఆశ్రమాల్లో చేర్చుతున్నారు. ధర్మవ్యాధుడు తల్లిదండ్రుల సేవే వేదాధ్యయనం, యజ్ఞాలు, వ్రతాల ఫలం ఇస్తుందని చెప్పాడు; తల్లిదండ్రుల సేవ లేని చదువు, శ్రమ నిష్ఫలం అన్నాడు. కాబట్టి పిల్లలు ఎక్కడ ఉన్నా వారి బాగోగులు చూసుకోవాలి, దగ్గర ఉంచుకోవాలి, ప్రేమ పంచాలి – అప్పుడే వృద్ధాశ్రమాల అవసరం తగ్గుతుంది","ఇ) 1) సంభాషణ (నమూనా): కౌశికుడు: అయ్యా! ధర్మసూక్ష్మాలు తెలుసుకోవాలని వచ్చాను. ధర్మవ్యాధుడు: రండి మహాత్మా! మా ఇంట్లోకి రండి. (తల్లిదండ్రులను చూపిస్తూ) వీరే నా దేవతలు. కౌశికుడు: నీకు ఇంత జ్ఞానం ఎలా వచ్చింది? ధర్మవ్యాధుడు: వీరి సేవ వల్లే. మీరు మీ తల్లిదండ్రులను చెప్పకుండా వదిలి వచ్చారు; వారు దుఃఖంతో చూపు కోల్పోయారు. కౌశికుడు: నా తప్పు తెలిసింది; వెంటనే వెళ్ళి వారిని సేవిస్తాను. ధర్మవ్యాధుడు: మీకు మేలు కలుగుతుంది","ఇ) 2) ఆత్మకథ (నమూనా): నా పేరు రమణమ్మ. నా కొడుకు బెంగళూరులో ఉద్యోగం చేస్తున్నాడు. వాడు చిన్నప్పుడు నా ఒడిలోనే నిద్రపోయేవాడు. ఇప్పుడు వారానికి ఒకసారి ఫోన్ చేస్తాడు. వాడు బాగా చదివి పైకి రావాలనే మేం కష్టపడ్డాం; వాడి అభివృద్ధి చూసి గర్వపడుతున్నాం. కానీ పండుగలకు ఇల్లు బోసిపోతుంది. ఆరోగ్యం బాగోలేనప్పుడు వాడు దగ్గర ఉంటే బాగుండనిపిస్తుంది. పిల్లలు ఎక్కడ ఉన్నా తల్లిదండ్రులతో మాట్లాడుతూ, అప్పుడప్పుడు వచ్చి చూసిపోతే చాలు – అదే మాకు సంతోషం","పదజాలం అ) 1) జనకుడు = తండ్రి – మా జనకుడు రైతు 2) అమరులు = మరణం లేనివారు (దేవతలు) – స్వాతంత్ర్య సమరయోధులు అమరులయ్యారు 3) వాక్కు = మాట – మంచి వాక్కు అందరినీ ఆకట్టుకుంటుంది 4) వాంఛ = కోరిక – దురాశతో వాంఛలు పెంచుకోకూడదు 5) హర్మ్యాలు = మేడలు – నగరంలో హర్మ్యాలు ఎక్కువ 6) హితము = మేలు – పెద్దలు మన హితమే కోరతారు","ఆ) పుత్రుడు – కుమారుడు, తనయుడు, సుతుడు, నందనుడు; వస్త్రం – బట్ట, వలువ, అంబరం; జనని – తల్లి, మాత, అమ్మ; చక్షువు – కన్ను, నేత్రం, నయనం; వహ్ని – అగ్ని, అనలుడు, పావకుడు","ఇ) గురువు – ఉపాధ్యాయుడు, తండ్రి, బృహస్పతి, పెద్ద; అర్థం – ధనం, ప్రయోజనం, శబ్దార్థం; ఫలం – పండు, ప్రయోజనం, ఫలితం; బుధుడు – పండితుడు, బుధగ్రహం, దేవత; వంశం – కులం, వెదురు, సమూహం"]],["భాషాంశాలు: ఈ) వ్యుత్పత్త్యర్థాలు, ఉ) ప్రకృతి–వికృతి; సంధులు అ) (పుట 10)",["ఈ) ధర్మం – లోకాన్ని ధరించునది (నిలిపేది); బుధుడు – బోధించువాడు, అన్నీ తెలిసినవాడు (పండితుడు); జనని – జన్మనిచ్చునది (తల్లి); జామదగ్ని – జమదగ్ని కుమారుడు (పరశురాముడు); వసుధ – వసువులను (సంపదలను) ధరించునది (భూమి)","ఉ) ప్రకృతి – వికృతి: కార్యం – కర్జం; పుత్రుడు – బొట్టె; ధర్మం – దమ్మం; భక్తి – బత్తి; ఆజ్ఞ – ఆన; ఆశ్చర్యం – అచ్చెరువు (పట్టికలోని పదాలతో జతచేయండి)","సంధులు అ) 1) నిజంబు + అగు – ఉకార సంధి 2) మూలంబు + ఐనది – ఉకార సంధి 3) కలదు + ఒక – ఉకార సంధి 4) వేల్పులు + అనఘ – ఉకార సంధి 5) నీవు + ఒకరుండవు – ఉకార సంధి"]],["సంధులు ఆ), ఇ) త్రికసంధి; సమాసాలు ఈ), ఉ) (పుట 11)",["ఆ) 1) జ్ఞానార్థంబు – సవర్ణదీర్ఘ సంధి 2) విజ్ఞానోన్నతి – గుణ సంధి 3) అభ్యంతరం – యణాదేశ సంధి 4) ధర్మాత్ముడు – సవర్ణదీర్ఘ సంధి","ఇ) 1) ఇమ్మహాత్ముడు 2) అవ్విప్రుడు 3) అప్పతివ్రత 4) ఎమ్మెయిన్ 5) ఇక్కన్య (త్రిక సంధి)","ఈ) 1) జననీజనకులు – జననియు, జనకుడును – ద్వంద్వ సమాసం 2) ఫలపుష్పములు – ఫలములును, పుష్పములును – ద్వంద్వ 3) వస్త్రభూషణములు – వస్త్రములును, భూషణములును – ద్వంద్వ 4) భక్ష్యభోజ్యములు – భక్ష్యములును, భోజ్యములును – ద్వంద్వ","ఉ) 1) ధర్మపథం – విశేషణ పూర్వపద కర్మధారయం 2) సనాతనధర్మం – విశేషణ పూర్వపద కర్మధారయం 3) మానుషదేహం – షష్ఠీ తత్పురుష 4) శోకవహ్ని – రూపక సమాసం"]],["అలంకారం, ఛందస్సు (పుట 12)",["అలంకారం: 1) \"సంసార సాగరం\" – రూపకాలంకారం: సంసారం (ఉపమేయం), సాగరం (ఉపమానం) మధ్య అభేదం చెప్పారు 2) \"దయావర్షం\" – రూపకాలంకారం: దయ (ఉపమేయం) పై వర్షం (ఉపమానం) లక్షణం ఆరోపించారు","ఛందస్సు: 1) \"ఎంతయు వృద్ధులై తమకు నీవొకరుండవ తెప్ప గాఁగ న…\" – భ ర న భ భ ర వ గణాలు – ఉత్పలమాల (యతి 1–10 అక్షరాలు: ఎ–ఎ) 2) \"అనుపమ మెట్టివారలకు నందదు ధర్మపథంబు ధాత్రిలో\" – న జ భ జ జ జ ర గణాలు – చంపకమాల (యతి 1–11: అ–అ)"]],["ఆటవెలది సమన్వయం, ఆధునిక వచనం, ప్రాజెక్టు (పుట 13)",["ఆటవెలది: భూమి (UI–హ)","లోన (UI–హ)","బుట్టు (UI–హ)","భూసార (UUI–త)","మెల్లను (UII–భ) → 3 సూర్య + 2 ఇంద్ర గణాలు; యతి: భూ – భూ. తనువు (III–న)","లోన (హ)","బుట్టు (హ)","తత్త్వ (హ)","మెల్ల (హ) → 5 సూర్యగణాలు; యతి: త – త. కాబట్టి ఆటవెలది","వచనం: 1) ధర్మవ్యాధుడు కౌశికునితో ఇలా అన్నాడు 2) ఇంటిలోకి రమ్మని అతనిని తీసుకువెళ్ళాడు 3) ఈ మహాత్ముడు మనలను చూడడానికి ఇక్కడికి వచ్చాడని చెప్పగా 4) పతివ్రత పంపగా నీవు ధర్మం తెలుసుకోవడానికి నేను ఉన్న చోటికి వచ్చావు","ప్రాజెక్టు: శ్రవణకుమారుడు (అంధులైన తల్లిదండ్రులను కావడిలో మోసి తీర్థయాత్రలు చేయించాడు), భీష్ముడు (తండ్రి సంతోషం కోసం రాజ్యం, వివాహం త్యజించాడు), శ్రీరాముడు (తండ్రి మాట కోసం వనవాసం) – ఇద్దరి వివరాలు సేకరించి రాయాలి"]]]},{"id":"te2","no":2,"t":"బతుకు గంప","m":[6],"ty":"కథానిక","th":"కుటుంబ విలువలు","by":"మూలింటి చంద్రకళ","sum":"పండ్ల గంప నెత్తిన పెట్టుకుని వీధుల్లో పండ్లు అమ్మే ఎల్లమ్మతో ఒక మధ్యతరగతి గృహిణి (రచయిత్రి) కి ఏర్పడిన అనుబంధమే ఈ కథ. బాల్యంలోనే పెళ్లయిన ఎల్లమ్మ చదువులేని భర్త, అత్త, పిల్లల భారం మోస్తూ పండ్లమ్ముకుని బతుకుతుంది. ఊరి ఏటి వరదలో దొరికిన దిక్కులేని బిడ్డను \"సాయిలు\" అని పేరు పెట్టి సొంత బిడ్డల్లా పెంచి పది వరకు చదివించగా అతడు బస్సు కండక్టర్ అయ్యాడు. రచయిత్రికి జ్వరం వచ్చినప్పుడు ఇంటి పనంతా చేసి డబ్బు తీసుకోవడానికి నిరాకరిస్తుంది. లారీ క్లీనర్‌గా పనిచేసే భర్తకు ప్రమాదం జరిగినప్పుడు కూడా ఆమె కుంగిపోలేదు. అన్నీ ఉన్నా ఎప్పుడూ వెలితిగా మాట్లాడే తన స్నేహితులు (నీరజ, వసుంధర, సునీత) కంటే కష్టాలను చిరునవ్వుతో ఎదుర్కొనే ఎల్లమ్మ ఎంతో ఎత్తులో ఉన్నట్లు రచయిత్రికి అనిపిస్తుంది.","pts":["రచయిత్రి: మూలింటి చంద్రకళ – చిత్తూరు జిల్లా; నిరుపేదల జీవిత వాస్తవాలు కథావస్తువులు; \"ఒక ప్రయాణం\", \"బతుకు గంప\", \"ఒక రైతుకథ\" కథలు; మరణం 05.12.2004.","ప్రక్రియ: కథానిక – జీవితంలోని ఒక ముఖ్య సన్నివేశాన్ని క్లుప్తంగా, ప్రభావవంతంగా చెప్పేది.","ఎల్లమ్మ – ఈతపుల్లల గంపలో పండ్లు అమ్మే శ్రమజీవి; బాల్య వివాహ బాధితురాలు.","సాయిలు – వరదలో దొరికిన అనాథ బాలుడు; ఎల్లమ్మ పెంచి చదివించింది; బస్సు కండక్టర్.","ఎల్లమ్మ భర్త – లారీ క్లీనర్; హైదరాబాద్ దగ్గర టిప్పర్ ఢీకొని ప్రమాదం.","రచయిత్రి జ్వరంతో ఉన్నప్పుడు ఇంటిపని చేసి డబ్బు వద్దన్న ఎల్లమ్మ మానవత్వం.","సందేశం: కష్టాల్లో ఆత్మస్థైర్యం, ఉన్నంతలో తృప్తి, తోటివారికి చేయూత – మానవత్వమే జీవిత పరమార్థం."],"w":[["వెలితి","లోటు"],["నిరాశ్రయులు","ఆశ్రయం లేనివారు"],["పొద్దస్తమానం","రోజంతా"],["స్తిమితపడు","కుదుటపడు, శాంతించు"],["దిక్కులేని","ఆధారం లేని"],["గంప","బుట్ట"],["బతుకు","జీవనం"],["ఆత్మస్థైర్యం","మనోధైర్యం"],["చేయూత","సహాయం"],["సాకు","పోషించు"]],"gr":{"t":"భాషాంశాలు","p":["అవ్యయీభావ సమాసం: పూర్వపదం అవ్యయం (అను, యథా, ప్రతి, ఉప, స) – యథాశక్తి, ప్రతిదినం.","ఛేకానుప్రాసాలంకారం: సమాన అక్షరాలు గల పదాలు అర్థభేదంతో వెంటవెంటనే రావడం – \"ధర ధర పెరిగింది\".","కర్తరి → కర్మణి: \"ఎల్లమ్మ పండ్లను అమ్మింది\" → \"ఎల్లమ్మ చేత పండ్లు అమ్మబడ్డాయి\".","ఆమ్రేడిత సంధి: అక్కడ + అక్కడ = అక్కడక్కడ."]},"qa":[["సాయిలు ఎవరు?","వరదలో దొరికిన దిక్కులేని బాలుడు; ఎల్లమ్మ పెంచి చదివించింది; బస్సు కండక్టర్."],["రచయిత్రికి ఎల్లమ్మతో పరిచయం ఎలా?","ఎల్లమ్మ దగ్గర రోజూ పండ్లు కొనడంతో మొదలై ఆత్మీయ బంధంగా మారింది."],["ఎల్లమ్మ ఎందుకు ఏడ్చింది?","లారీ క్లీనర్ అయిన భర్తకు ప్రమాదం జరిగి తీవ్ర గాయాలయ్యాయి."],["శీర్షిక \"బతుకు గంప\" సరిపోతుందా?","అవును – పండ్ల గంపే ఎల్లమ్మ బతుకుదెరువు; కుటుంబ భారాన్నంతా గంపలా మోసింది."]],"act":"మీ ఊరిలో కష్టపడి కుటుంబాన్ని పోషిస్తున్న ఒక శ్రమజీవి (కూరగాయలమ్మే వ్యక్తి, కూలీ) ని ఇంటర్వ్యూ చేసి వారి జీవితం గురించి నివేదిక రాయండి.","kn":"బాల్య వివాహ నిషేధ చట్టం (2006) ప్రకారం అమ్మాయికి 18, అబ్బాయికి 21 సంవత్సరాలు నిండకుండా పెళ్లి చేయడం నేరం. ఫిర్యాదులకు చైల్డ్ లైన్ 1098.","qz":[["\"బతుకు గంప\" రచయిత్రి?","మూలింటి చంద్రకళ","వాసిరెడ్డి సీతాదేవి","శీలా వీర్రాజు","ఓల్గా"],["ఈ పాఠం ప్రక్రియ?","కథానిక","నాటకం","శతకం","వ్యాసం"],["ఎల్లమ్మ వృత్తి?","పండ్లు అమ్మడం","కూరగాయలు అమ్మడం","పాలు అమ్మడం","కుట్టుపని"],["సాయిలు ఉద్యోగం?","బస్సు కండక్టర్","ఉపాధ్యాయుడు","పోలీసు","లారీ డ్రైవర్"],["సాయిలు ఎల్లమ్మకు ఎలా దొరికాడు?","ఏటి వరదలో","రైలులో","ఆసుపత్రిలో","అడవిలో"],["ఎల్లమ్మ భర్తకు ఏమైంది?","లారీ ప్రమాదంలో గాయపడ్డాడు","జ్వరం వచ్చింది","ఊరు వదిలి వెళ్ళాడు","ఉద్యోగం పోయింది"],["రచయిత్రి జ్వరంతో ఉన్నప్పుడు ఎల్లమ్మ?","ఇంటి పనంతా చేసి డబ్బు వద్దంది","డబ్బు అడిగింది","రాలేదు","వైద్యుని పిలిచింది"],["ఎల్లమ్మ కంటే \"వెలితి\" గా మాట్లాడేవారు?","రచయిత్రి స్నేహితులు","ఎల్లమ్మ అత్త","సాయిలు","ఎల్లమ్మ భర్త"],["గంప దేనితో అల్లారు?","ఈతపుల్లలు","వెదురు","ప్లాస్టిక్","తాడు"],["\"అక్కడ + అక్కడ\" సంధి?","ఆమ్రేడిత సంధి","ఉకార సంధి","గుణ సంధి","త్రిక సంధి"],["\"యథాశక్తి\" సమాసం?","అవ్యయీభావ","ద్వంద్వ","ద్విగు","బహువ్రీహి"],["\"పదిరోజులు\" సమాసం?","ద్విగు సమాసం","ద్వంద్వ","అవ్యయీభావ","షష్ఠీ తత్పురుష"],["\"నేడు ధర ధర బాగా పెరిగింది\" – అలంకారం?","ఛేకానుప్రాసం","రూపకం","ఉపమ","అతిశయోక్తి"],["ఈ పాఠం సందేశం?","కష్టాల్లో ఆత్మస్థైర్యం, మానవత్వం","ధనమే ముఖ్యం","చదువు అనవసరం","పల్లెలు వదలాలి"],["మూలింటి చంద్రకళ జిల్లా?","చిత్తూరు","నెల్లూరు","గుంటూరు","విశాఖ"],["\"స్తిమితపడు\" అర్థం?","కుదుటపడు","కంగారుపడు","కోపపడు","భయపడు"]],"wb":{"mis":"కర్మణి వాక్యంలో \"చేత\" + \"బడు\" రూపం రావాలి. ఛేకానుప్రాసంలో పదాలు వెంటవెంటనే రావాలి; అర్థం వేరుగా ఉండాలి – అర్థం ఒకటే అయితే అది అనుప్రాసం కాదు.","qz":[["పుణ్యాత్ముడు విడదీస్తే?","పుణ్య + ఆత్ముడు (సవర్ణదీర్ఘ)","పుణ్యా + త్ముడు","పుణ్యు + ఆత్ముడు","పుణ్య + అత్ముడు (గుణ)"],["ఏమి + ఐనది = ?","ఏమైనది (ఇకార సంధి)","ఏమియైనది","ఏమ్యైనది","ఏమేనది"],["\"కాళ్ళుసేతులు\" సమాసం?","ద్వంద్వ సమాసం","ద్విగు","బహువ్రీహి","కర్మధారయ"],["\"అసాధారణం\" సమాసం?","నఞ్ తత్పురుష","ద్విగు","ద్వంద్వ","అవ్యయీభావ"],["\"గోరువంక వంక చూసెను\" – అలంకారం?","ఛేకానుప్రాసం","రూపకం","ఉపమ","శ్లేష"],["\"అతడికి మంచి జరుగుగాక!\" – వాక్యం?","ఆశీరర్థక వాక్యం","నిషేధార్థక","సామర్థ్యార్థక","అనుమత్యర్థక"],["\"ఇటువైపు నీవు రావద్దు\" – వాక్యం?","నిషేధార్థక వాక్యం","ఆశీరర్థక","ప్రశ్నార్థక","సామర్థ్యార్థక"],["\"ఎల్లమ్మ ఆ పని చేయగలదు\" – వాక్యం?","సామర్థ్యార్థక వాక్యం","అనుమత్యర్థక","నిషేధార్థక","విధ్యర్థక"],["\"మీరు మా ఇంటికి రావచ్చు\" – వాక్యం?","అనుమత్యర్థక వాక్యం","సామర్థ్యార్థక","ఆశీరర్థక","నిషేధార్థక"],["ముఖం – వికృతి?","మోము","ముఖి","ముక్కు","మూతి"]],"pg":"15–26","f":"books/10/Class10_Telugu_Textbook_Sem1.pdf","p":23,"lb":"పాఠ్యపుస్తకం","ws":["అవగాహన: అ) చెప్పండి, ఆ) అపరిచిత పద్యం, ఇ) అపరిచిత గద్యం (పుట 20)","అవగాహన: ఈ) అర్థసందర్భాలు, ఉ) ఏకవాక్య; వ్యక్తీకరణ అ), ఆ), ఇ); పదజాలం అ) (పుట 21)","పదజాలం: ఆ) పర్యాయపదాలు, ఇ) నానార్థాలు, ఈ) వికృతులు, ఉ) జాతీయాలు (పుట 22)","వ్యాకరణం: సంధులు అ), ఆ); సమాసాలు ఇ), ఈ) అవ్యయీభావం (పుట 23)","అలంకారం, కర్మణి వాక్యాలు, వాక్య భేదాలు, ప్రాజెక్టు (పుట 24)"]},"tg":[["అవగాహన: అ) చెప్పండి, ఆ) అపరిచిత పద్యం, ఇ) అపరిచిత గద్యం (పుట 20)",["అ) 1) నచ్చిన సన్నివేశం (నమూనా): రచయిత్రి జ్వరంతో ఉన్నప్పుడు ఎల్లమ్మ రోజుల తరబడి పేరుకున్న బట్టలుతికి, ఇల్లంతా సర్దింది. డబ్బు ఇవ్వబోతే \"నన్ను ఆప్యాయంగా పిలిచి నువ్వు తినే కూడు పెట్టావు; ఒక్కపూట నీ పని చేస్తే డబ్బా?\" అంది – పేదరికంలోనూ ఆమె మానవత్వం నచ్చింది 2) సరిపోతుంది – ఈతపుల్లల పండ్ల గంపే ఎల్లమ్మ జీవనాధారం; ఆ గంపతోనే కుటుంబాన్ని, సాయిలును పోషించింది; జీవిత భారాన్నంతా గంపలా నెత్తిన మోసింది","ఆ) 1) గట్టున తుంగకు, గరిక కాడలకు అల్లిన సాలెగూళ్ళపై పడిన మంచు బిందువులు సూర్యకాంతిలో ముత్యాల సరాల్లా కనిపించాయి 2) \"రైతా! ఇంత అందమైన ప్రకృతి శిల్పాలను చూడకుండా దాటి వెళ్ళకు\" అన్నాడు 3) గట్టు మీది తుంగకు, గరిక కాడలకు 4) ఉదా: ఈ పద్యం ఎవరు రచించారు? (దువ్వూరి రామిరెడ్డి)","ఇ) 1) పరాయి ఆంగ్లేయులు మనపై అధికారం ఎందుకు చలాయించాలి, దేశసంపదను ఎందుకు కొల్లగొట్టాలి, కొందరు మేడల్లో – మరికొందరు గుడిసెల్లో ఎందుకుండాలి అని ఆలోచించేవాడు 2) స్వాతంత్ర్య ఉద్యమంలో పాల్గొని ఉపన్యాసాలు ఇవ్వడం వల్ల బ్రిటిష్ ప్రభుత్వం ఉపకార వేతనం ఆపేసింది 3) అమెరికాలో ఖాళీ సమయాల్లో పండ్ల తోటల్లో, హోటళ్ళలో పనిచేసి సంపాదించి చదువు కొనసాగించారు 4) ఉదా: జయప్రకాష్ నారాయణ ఏ ఉద్యమ నాయకుడిగా పేరు పొందారు?"]],["అవగాహన: ఈ) అర్థసందర్భాలు, ఉ) ఏకవాక్య; వ్యక్తీకరణ అ), ఆ), ఇ); పదజాలం అ) (పుట 21)",["ఈ) 1) \"అయితే నువ్వు ఇట్లా వచ్చావేమే?\" – మూలింటి చంద్రకళ \"బతుకు గంప\" కథానిక. భర్తకు ప్రమాదం జరిగిందని ఏడుస్తూ వచ్చిన ఎల్లమ్మను రచయిత్రి అడిగిన మాట. అర్థం: భర్త ఆసుపత్రిలో ఉంటే నువ్వు ఇక్కడికి ఎందుకు వచ్చావు? (ఎల్లమ్మ తాను దాచుకున్న డబ్బు తీసుకెళ్ళడానికి వచ్చింది)","ఈ) 2) \"వారితో ఎప్పుడు కలిసినా వెలితిగానే మాట్లాడుతారు\" – అదే పాఠం. అన్నీ ఉన్నా అసంతృప్తిగా ఉండే తన స్నేహితులు (లెక్చరర్ నీరజ, బ్యాంక్ క్లర్క్ వసుంధర, టీచర్ సునీత) గురించి రచయిత్రి అనుకున్న మాట. అర్థం: ఆర్థిక ఇబ్బందులు లేకపోయినా వారు ఎప్పుడూ ఏదో లోటు ఉన్నట్లే మాట్లాడతారు","ఉ) 1) సాయిలు – ఏటి వరదలో దొరికిన దిక్కులేని బిడ్డ; ఎల్లమ్మ పెంచి చదివించిన కొడుకు (బస్సు కండక్టర్) 2) ఇలాంటివారు రెక్కలు ముక్కలు చేసుకుని బిడ్డల కోసం బతుకుతారని, కష్టాలను దరిచేరనివ్వని వారు అందరికంటే ఎత్తులో ఉన్నారని అన్నది 3) ఎల్లమ్మ దగ్గర రోజూ పండ్లు కొనడంతో పరిచయం ఏర్పడింది","వ్యక్తీకరణ అ) 1) ఈతపుల్లల గంపలో పండ్లు అమర్చుకుని నెత్తిన పెట్టుకుని వీధుల్లో \"పండ్లమ్మో…\" అంటూ అమ్ముకునే వృత్తి. రోజుకు కొద్ది లాభం మిగిలినా దానితోనే కుటుంబాన్ని పోషించింది 2) కష్టపడే తత్వం, ఆత్మస్థైర్యం, ఆత్మాభిమానం, దయ (అనాథను పెంచడం), కృతజ్ఞత, నిస్వార్థ సేవ (జ్వరంలో డబ్బు తీసుకోకుండా పని), ఉన్నంతలో తృప్తి 3) బాల్య వివాహాల వల్ల చదువు ఆగిపోతుంది; చిన్నవయసులో గర్భం వల్ల తల్లి, బిడ్డ ఆరోగ్యం దెబ్బతింటాయి; ఆర్థిక స్వాతంత్ర్యం ఉండదు; బాధ్యతల భారం, వేధింపులు; ఇది చట్టరీత్యా నేరం","ఆ) 1) సారాంశం: రచయిత్రి ఒకరోజు ఏ పనీ చేయలేక ఎల్లమ్మ గురించి ఆలోచిస్తుంది. నాలుగేళ్ళ క్రితం పండ్ల గంపతో వచ్చిన ఎల్లమ్మతో పరిచయం ఆత్మీయతగా మారింది. ఆ రోజు ఎల్లమ్మ ఏడుస్తూ వచ్చి, లారీ క్లీనర్ అయిన భర్తకు ప్రమాదం జరిగిందని, తాను దాచుకున్న డబ్బు తీసుకెళ్ళడానికి వచ్చానని చెప్పింది. చిన్నతనంలోనే పెళ్ళి, అత్తను సాకడం, సంకలో బిడ్డ–కడుపులో బిడ్డతో పండ్లమ్మి బతకడం, వరదలో దొరికిన సాయిలును పెంచి కండక్టర్‌ను చేయడం – అన్నీ గుర్తు చేసుకుంది. అన్నీ ఉన్నా అసంతృప్తితో ఉండే తన స్నేహితులకంటే కష్టాలను లెక్కచేయని ఎల్లమ్మ ఎంతో ఎత్తులో ఉన్నట్లు రచయిత్రికి అనిపించింది","ఆ) 2) ఎల్లమ్మ వ్యక్తిత్వం: శ్రమజీవి – గంప మోసి కుటుంబాన్ని పోషించింది; మానవత్వం – దిక్కులేని సాయిలును సొంత బిడ్డలా పెంచి చదివించింది; ఆత్మాభిమానం – సాయిలును తిట్టిన వారిపై కోపపడింది; నిస్వార్థం – జ్వరంలో రచయిత్రి ఇంటి పనిచేసి డబ్బు వద్దంది; ఆత్మస్థైర్యం – భర్త ప్రమాదం, పేదరికం వచ్చినా కుంగిపోలేదు; పొదుపు – కొద్దికొద్దిగా డబ్బు దాచుకుంది; ఉన్నంతలో తృప్తి","ఆ) 3) అనుబంధం: పండ్లు కొనడంతో మొదలైన పరిచయం క్రమంగా ఇంటి మనిషి బంధమైంది. ఎల్లమ్మ రాకపోతే రచయిత్రికి వెలితిగా అనిపించేది; ఆమె కష్టం తన కష్టంలా బాధపడింది. రచయిత్రి ఆప్యాయంగా పిలిచి తిండి పెట్టేది; ఎల్లమ్మ జ్వరంలో ఇంటి పని చేసి కృతజ్ఞత చూపింది; కష్టం వచ్చినప్పుడు ముందుగా రచయిత్రి దగ్గరికే వచ్చింది – ఇది వర్గ భేదాలకు అతీతమైన మానవ సంబంధం","ఇ) 1) సంభాషణ (నమూనా): రచయిత్రి: ఏంటి ఎల్లమ్మా ఇలా ఉన్నావు? ఎల్లమ్మ: మా ఆయనకు యాక్సిడెంట్ అయ్యిందమ్మా. రచయిత్రి: అయ్యో! ఎప్పుడు? ప్రాణానికి ప్రమాదం లేదు కదా? ఎల్లమ్మ: లేదంటమ్మా, కానీ ఖర్చు శానా అవుతుందంట. రచయిత్రి: భయపడకు, నేను కూడా సాయం చేస్తా. ఎల్లమ్మ: నువ్వు ఉన్నావనే ధైర్యమే చాలమ్మా","ఇ) 2) లేఖ/నినాదాలు (నమూనా): \"కష్టాలు శాశ్వతం కావు – ధైర్యమే మనకు బలం\"; \"ఓటమి ఒక పాఠం, ప్రయత్నమే విజయ మార్గం\" – ఎల్లమ్మ లాంటి వారి ఉదాహరణలతో స్నేహితునికి ధైర్యం చెప్పే లేఖ రాయాలి","పదజాలం అ) 1) వెలితి = లోటు – మా ఇంట్లో ఏ వెలితీ లేదు 2) నిరాశ్రయులు = ఆశ్రయం లేనివారు – వరదల్లో నిరాశ్రయులకు భోజనం పెట్టారు 3) పొద్దస్తమానం = రోజంతా – పొద్దస్తమానం టీవీ చూడకూడదు 4) స్తిమితపడు = కుదుటపడు – మందు వేసుకున్నాక స్తిమితపడ్డాను 5) దిక్కులేని = ఆధారం లేని – దిక్కులేని వారిని ఆదుకోవాలి"]],["పదజాలం: ఆ) పర్యాయపదాలు, ఇ) నానార్థాలు, ఈ) వికృతులు, ఉ) జాతీయాలు (పుట 22)",["ఆ) 1) సొమ్ము, ధనం, డబ్బు 2) ఝషం, చేప, మీనం 3) దేహం, ఒళ్ళు, శరీరం 4) ప్రభాతం, ప్రాతఃకాలం, ఉదయం (పొద్దున)","ఇ) బతుకు – ఆ) జీవనం, స్థితి, జరుగుబాటు; సంతానం – ఇ) బిడ్డ, ఒక కల్పవృక్షం, కులం; సంసారం – అ) కాపురం, కుటుంబం, పుట్టుక","ఈ) ముఖం – మోము; పంక్తి – బంతి; కష్టం – కస్తి; మూర్ఖుడు – మొరకు; సుఖము – సుగము; వీథి – వీది","ఉ) 1) పొద్దస్తమానం – ఉదయం నుండి సాయంత్రం వరకు, నిరంతరం (ఉదా: పొద్దస్తమానం ఆటలేనా?) 2) ఊపిరి పీల్చుకొను – ఆందోళన తీరి ఉపశమనం పొందడం 3) తెల్లముఖం వేయు – ఏమీ అర్థంకాక / నిరుత్తరుడై బిత్తరపోవడం"]],["వ్యాకరణం: సంధులు అ), ఆ); సమాసాలు ఇ), ఈ) అవ్యయీభావం (పుట 23)",["అ) 1) పుణ్య + ఆత్ముడు – సవర్ణదీర్ఘ సంధి 2) విషయము + అంతా – ఉకార సంధి 3) పండ్లు + అమ్ముకొను – ఉకార సంధి 4) ఉన్నది + ఏదో – ఇకార సంధి","ఆ) 1) పోదామనుకుంటే – ఉకార సంధి 2) స్నానములు – లు ల న ల సంధి (స్నానాలు) 3) ఏమైనది – ఇకార సంధి 4) అక్కడక్కడ – ఆమ్రేడిత సంధి 5) జీవితములు/జీవితాలు – లులనల సంధి","ఇ) 1) పదిరోజులు – పది సంఖ్య గల రోజులు – ద్విగు సమాసం 2) కాళ్ళుసేతులు – కాళ్ళును, సేతులును – ద్వంద్వ సమాసం 3) తెల్లముఖం – తెల్లనైన ముఖం – విశేషణ పూర్వపద కర్మధారయం 4) అసాధారణం – సాధారణం కానిది – నఞ్ తత్పురుష 5) చిన్నబిడ్డ – చిన్నదైన బిడ్డ – విశేషణ పూర్వపద కర్మధారయం","ఈ) అనుకూలం – కూలమునకు అనుకూలంగా; యథాశక్తి – శక్తి ఎంతో అంత / శక్తిని అతిక్రమించకుండా; ప్రతిమాసం – మాసము మాసము; ప్రతిదినం – దినము దినము; ఉపవనం – వనమునకు సమీపం; సకుటుంబం – కుటుంబంతో కూడి"]],["అలంకారం, కర్మణి వాక్యాలు, వాక్య భేదాలు, ప్రాజెక్టు (పుట 24)",["ఉ) అన్నీ ఛేకానుప్రాసాలంకారాలు: 1) వంక – వంక (గోరువంక పక్షి / వైపు) 2) నారి – నారి (స్త్రీ / వింటినారి) 3) సుందర – దర (దరహాసం) 4) శుభంకర – కరం (చేయి) 5) కొమ్మ – కొమ్మ (స్త్రీ / చెట్టు కొమ్మ). లక్షణం: అర్థభేదం గల సమాన అక్షరాలు వెంటవెంటనే రావడం","ఊ) 1) ఎల్లమ్మ చేత పండ్లు అమ్మబడ్డాయి 2) ఆమె చేత బిడ్డ చదివించబడ్డాడు 3) వైద్యుని చేత వైద్యం చేయబడింది 4) అతని చేత కండక్టర్ ఉద్యోగం చేయబడింది 5) వారి చేత పిల్లవాడు కాపాడబడ్డాడు","ౠ) 1) ఆశీరర్థక వాక్యం 2) నిషేధార్థక వాక్యం 3) సామర్థ్యార్థక వాక్యం 4) అనుమత్యర్థక వాక్యం","ప్రాజెక్టు: కుటుంబ ఆర్థిక కష్టాలను దాటి లక్ష్యాన్ని సాధించిన వారు – చిలకమర్తి లక్ష్మీనరసింహం, డా. బి.ఆర్. అంబేద్కర్, ఏ.పి.జె. అబ్దుల్ కలాం, టంగుటూరి ప్రకాశం – వివరాలు సేకరించి ప్రదర్శించాలి"]]]},{"id":"te3","no":3,"t":"శతక మాధుర్యం","m":[7],"ty":"శతకం (పద్యాలు)","th":"నైతిక విలువలు","by":"వివిధ శతక కవులు (11 పద్యాలు)","sum":"ఈ పాఠంలో 11 మంది కవుల శతకాల నుండి ఎంపిక చేసిన పద్యాలు ఉన్నాయి. మంచి వారు పరుషంగా మాట్లాడరని (భాస్కర శతకం), రాజసేవ కంటే భగవంతుని ఆశ్రయం మేలని (శ్రీకాళహస్తీశ్వర శతకం), ధర్మస్థాపనకు సంస్కారులు యుగయుగాలా పుడతారని (కాళికాంబ శతకం), శ్రమే సర్వానికి మూలమని (వేమన), ధీరులు న్యాయమార్గం విడువరని, జ్ఞానం పెరిగే కొద్దీ గర్వం తగ్గుతుందని (సుభాషిత రత్నావళి), భావం–మాట–పని–ఫలితం ఒకదానిని అనుసరిస్తాయని (భావలింగ శతకం), మాతృభాష–మాతృదేశం పట్ల మమకారం ఉండాలని (కుప్పుసామి శతకం), చంచలమైన మనసుకు తృప్తి కావాలని (హరిహరనాథ శతకం), సత్సంగం దుర్జనుణ్ణి కూడా మారుస్తుందని (వేంకటాద్రీశ్వర శతకం), శౌర్యం, శాంతం, వినయం, దానం వంటి సద్గుణాల గొప్పతనాన్ని (వేంకటేశ శతకం) ఈ పద్యాలు బోధిస్తాయి.","pts":["ప్రక్రియ: శతకం – 100 నుండి 108 పద్యాలు; ప్రతి పద్యం చివర \"మకుటం\" (కిరీటం) ఉంటుంది; పద్యాలు ముక్తకాలు (దేనికదే స్వతంత్ర భావం).","1. మారద వెంకయ్య (1550–1600) – భాస్కర శతకం; తెలుగులో మొదటి దృష్టాంత శతకం.","2. ధూర్జటి (16వ శతాబ్దం) – అష్టదిగ్గజ కవి; శ్రీకాళహస్తీశ్వర శతకం, శ్రీకాళహస్తి మాహాత్మ్యం.","3. పోతులూరి వీరబ్రహ్మేంద్రస్వామి (17వ శతాబ్దం, కడప) – కాలజ్ఞానం, కాళికాంబ సప్తశతి.","4. వేమన (1652–1730) – శ్రీ సత్యసాయి జిల్లా కటారుపల్లిలో సిద్ధి; మకుటం \"విశ్వదాభిరామ వినురవేమ\"; ఆటవెలది ఛందం.","5–6. ఏనుగు లక్ష్మణకవి (1720–1780, పెద్దాడ) – భర్తృహరి \"సుభాషిత త్రిశతి\" ని \"సుభాషిత రత్నావళి\" గా అనువదించారు.","7. దార్ల సుందరీమణి (19వ శతాబ్ది కవయిత్రి, చర్లగుడిపాడు) – భావలింగ శతకం (1883).","8. త్రిపురనేని రామస్వామి చౌదరి (1887–1943, అంగలూరు) – కుప్పుస్వామి శతకం, సూతపురాణం, ఖూని.","9. షేక్ మహమ్మద్ హుస్సేన్ (20వ శతాబ్దం, దొరసానిపాడు) – హరిహరనాథ శతకం.","10. గాడేపల్లి సీతారామమూర్తి (1935–2018, అద్దంకి) – వేంకటాద్రీశ్వర శతకం.","11. తాళ్లపాక పెద్ద తిరుమలాచార్యులు (1460–1548) – అన్నమయ్య రెండవ కుమారుడు; వేంకటేశ శతకం.","సందేశం: శతక పద్యాలు జీవన నైపుణ్యాలు, నైతిక విలువలు నేర్పి ఉత్తమ పౌరులుగా తీర్చిదిద్దుతాయి."],"w":[["దుష్టుడు","చెడ్డవాడు"],["ఖ్యాతి","కీర్తి"],["తల్పం","పాన్పు, శయ్య"],["కానలు","అడవులు"],["భాస్వంతుడు","సూర్యుడు"],["నిష్ఠురోక్తులు","కఠినమైన మాటలు"],["ఘటం","కుండ"],["భుజగం","పాము"],["పల్లవం","చిగురు"],["తనువు","శరీరం"],["ధీరోత్తములు","ధైర్యవంతులలో శ్రేష్ఠులు"],["మమత","మమకారం, ప్రేమ"],["వదరు","వ్యర్థంగా మాట్లాడు"],["ముదము","సంతోషం"],["సజ్జనసంగతి","మంచివారితో స్నేహం"]],"gr":{"t":"భాషాంశాలు","p":["అనునాసిక సంధి: క,చ,ట,త,ప ల తర్వాత న/మ వస్తే ఆయా వర్గ అనునాసికాలు (ఙ,ఞ,ణ,న,మ) వస్తాయి – వాక్ + మయము = వాఙ్మయము, జగత్ + నాథుడు = జగన్నాథుడు.","వృత్త్యనుప్రాసాలంకారం: ఒకే హల్లు పలుమార్లు వచ్చి శబ్ద చమత్కారం – \"భేరికా దాండదడాండదాండ నినదంబుల\".","దృష్టాంతాలంకారం: ఉపమాన ఉపమేయాల వేర్వేరు ధర్మాలను బింబప్రతిబింబ భావంతో చెప్పడం – \"పెరుగు ఎంత చిలికినా వెన్ననే ఇస్తుంది; మంచివారిని ఎంత బాధించినా మంచే చేస్తారు\".","తేటగీతి: ఉపజాతి; 4 పాదాలు; ప్రతి పాదంలో 1 సూర్య + 2 ఇంద్ర + 2 సూర్య గణాలు; 4వ గణం మొదటి అక్షరానికి యతి; ప్రాసయతి చెల్లుతుంది; ప్రాస నియమం లేదు.","ఆటవెలది (వేమన, భావలింగ పద్యాలు): 1, 3 పాదాల్లో 3 సూర్య + 2 ఇంద్ర; 2, 4 పాదాల్లో 5 సూర్య గణాలు; 4వ గణం మొదట యతి; ప్రాస లేదు."]},"qa":[["మంచి గుణాలు కలవాడు ఎలా మాట్లాడతాడు?","నిండుకుండ తొణకనట్లు గుణవంతుడు పరుషంగా మాట్లాడడు; మృదువుగా, న్యాయంగా మాట్లాడతాడు."],["వేటిపై మమత ఉండాలి?","మాతృభాషపై, మాతృదేశంపై – మృగపక్షులకు కూడా తమ జాతిపై మమకారం ఉంటుంది."],["శ్రమ గొప్పతనం గురించి వేమన ఏమన్నాడు?","భూసారం భూమిలో, జ్ఞానం శరీరంలో పుట్టినట్లు సర్వ సంపదలూ శ్రమ నుండే పుడతాయి."],["ధూర్జటి మానవులను ఎందుకు ప్రశ్నించాడు?","అడవుల్లో కందమూలాలు, గుహలు, నదీజలం, చిగురు పాన్పులు ఉండగా, రక్షించే దేవుడు ఉండగా రాజులను ఎందుకు సేవిస్తారని."],["సత్సంగ ప్రభావానికి ఇచ్చిన ఉదాహరణ?","సూర్యుని స్నేహం వల్ల ఉప్పు సముద్రం మేఘాల ద్వారా తీయని నీరు ఇస్తుంది."],["ధీరోత్తముల లక్షణం?","పొగడ్త/నింద, సంపద/నష్టం, మరణం ఏది ఎదురైనా న్యాయమార్గం తప్పరు."],["ఏనుగు లక్ష్మణకవి గర్వం ఎలా పోయింది?","పండితుల సాంగత్యంలో కొంత జ్ఞానం రాగానే తనకు తెలిసింది తక్కువని గ్రహించి గర్వం వదిలాడు."]],"act":"పాఠంలోని పద్యాలను రాగయుక్తంగా కంఠస్థం చేసి పాఠశాల పద్య పోటీలో పాడండి; శతక కవుల పేరు–కాలం–శతకం–మకుటం పట్టిక తయారు చేసి తరగతిలో ప్రదర్శించండి.","kn":"జముకుల కథ – ఉత్తరాంధ్ర (శ్రీకాకుళం) జానపద కళ; గంగమ్మ జాతర – తిరుపతి తాతయ్యగుంట గంగమ్మ జాతరను రాష్ట్ర పండుగగా గుర్తించారు.","qz":[["భాస్కర శతకం రచయిత?","మారద వెంకయ్య","ధూర్జటి","వేమన","ఏనుగు లక్ష్మణకవి"],["తెలుగులో మొదటి దృష్టాంత శతకం?","భాస్కర శతకం","వేమన శతకం","సుమతీ శతకం","కుప్పుస్వామి శతకం"],["శ్రీకాళహస్తీశ్వర శతకం రాసిన అష్టదిగ్గజ కవి?","ధూర్జటి","పోతన","తెనాలి రామకృష్ణుడు","అల్లసాని పెద్దన"],["శతకంలో ప్రతి పద్యం చివర ఉండే దానిని ఏమంటారు?","మకుటం","ప్రాస","యతి","గణం"],["శతకంలో సాధారణంగా ఎన్ని పద్యాలు?","100 నుండి 108","50","1000","12"],["\"శ్రమములోన బుట్టు సర్వంబు\" అన్న కవి?","వేమన","ధూర్జటి","మారద వెంకయ్య","దార్ల సుందరీమణి"],["\"సుభాషిత రత్నావళి\" అనువాదకుడు?","ఏనుగు లక్ష్మణకవి","త్రిపురనేని రామస్వామి","గాడేపల్లి సీతారామమూర్తి","వీరబ్రహ్మేంద్రస్వామి"],["\"మాతృభాషయందు మాతృదేశమునందు మమత లేనివాడు మనుజుండగునె?\" – శతకం?","కుప్పుస్వామి శతకం","భావలింగ శతకం","హరిహరనాథ శతకం","వేంకటేశ శతకం"],["భావలింగ శతకం రచించిన కవయిత్రి?","దార్ల సుందరీమణి","మొల్ల","తరిగొండ వెంగమాంబ","ఆతుకూరి మొల్ల"],["వెలితి కుండ తొణుకుతుంది – నిండుకుండ తొణకదు; ఇందులో నిండుకుండ ఎవరికి పోలిక?","గుణవంతుడు","నీచుడు","రాజు","పండితుడు కానివాడు"],["సముద్రం తీయని నీరు ఇవ్వడానికి కారణం (పద్యం 10)?","సూర్యుని స్నేహం","చంద్రుని వెలుగు","నదుల నీరు","వర్షాకాలం"],["తాళ్లపాక పెద్ద తిరుమలాచార్యులు ఎవరి కుమారుడు?","అన్నమాచార్యులు","పోతన","త్యాగరాజు","క్షేత్రయ్య"],["జగత్ + నాథుడు = జగన్నాథుడు – సంధి?","అనునాసిక సంధి","సవర్ణదీర్ఘ","గుణ సంధి","త్రిక సంధి"],["ఒకే హల్లు పలుమార్లు వచ్చే అలంకారం?","వృత్త్యనుప్రాసం","ఉపమ","రూపకం","దృష్టాంతం"],["తేటగీతి ప్రతి పాదంలో గణాలు?","1 సూర్య, 2 ఇంద్ర, 2 సూర్య","3 సూర్య, 2 ఇంద్ర","6 ఇంద్ర, 2 సూర్య","5 సూర్య"],["\"ముక్తకం\" అంటే?","దేనికదే స్వతంత్ర భావం గల పద్యం","కథ చెప్పే పద్యం","పాట","వచన కవిత"]],"wb":{"mis":"అనునాసిక సంధిలో వర్గ అనునాసికం (ఙ ఞ ణ న మ) వస్తుంది – దిక్ + మండలం = దిఙ్మండలం (దిగ్మండలం కాదు). వృత్త్యనుప్రాసంలో ఒకే హల్లు మళ్ళీ మళ్ళీ రావాలి; ఛేకానుప్రాసంలో పదాలు జంటగా అర్థభేదంతో రావాలి.","qz":[["నిష్ఠురోక్తులు విడదీస్తే?","నిష్ఠుర + ఉక్తులు (గుణ సంధి)","నిష్ఠు + రోక్తులు","నిష్ఠుర + ఓక్తులు","నిష్ఠురో + ఉక్తులు"],["కాళికా + అంబ = ?","కాళికాంబ (సవర్ణదీర్ఘ సంధి)","కాళికంబ","కాళికేంబ","కాళికయంబ"],["ఆ + పలుకులు = ?","అప్పలుకులు (త్రిక సంధి)","ఆపలుకులు","అపలుకులు","ఆప్పలుకులు"],["దానంబు + చేయుట = ?","దానంబు సేయుట (గసడదవాదేశ సంధి)","దానంబుచేయుట","దానంబుజేయుట","దానంబేయుట"],["దిక్ + మండలము = ?","దిఙ్మండలము","దిక్మండలము","దిగ్మండలము","దిఖ్మండలము"],["\"ప్రతిదినము\" సమాసం?","అవ్యయీభావ సమాసం","ద్విగు","ద్వంద్వ","బహువ్రీహి"],["\"శౌర్యలక్ష్మి\" – విగ్రహవాక్యం?","శౌర్యము అనెడి లక్ష్మి (రూపక సమాసం)","శౌర్యము యొక్క లక్ష్మి","శౌర్యము మరియు లక్ష్మి","శౌర్యమైన లక్ష్మి"],["భాస్కరుడు – వ్యుత్పత్త్యర్థం?","కాంతిని కలిగించువాడు (సూర్యుడు)","రాత్రిని ఇచ్చువాడు","నీటిని ఇచ్చువాడు","గాలిని నడిపేవాడు"],["చంద్రుడు – వికృతి?","చందురుడు","సామి","అంచ","దమ్మము"],["\"అక్షరజ్ఞానం లేని నిరక్షరకుక్షి ఈ క్షితిలో...\" – అలంకారం?","వృత్త్యనుప్రాసం","ఉపమ","దృష్టాంతం","ఉత్ప్రేక్ష"]],"pg":"27–37","f":"books/10/Class10_Telugu_Textbook_Sem1.pdf","p":35,"lb":"పాఠ్యపుస్తకం","ws":["అవగాహన – ప్రతిస్పందన: అ) ప్రశ్నలు, ఆ) పద్య భావం (పుట 31)","ఇ) అపరిచిత గద్యం, ఈ) అర్థసందర్భాలు, ఉ) ఏకవాక్య సమాధానాలు (పుట 32)","వ్యక్తీకరణ – సృజనాత్మకత (అ, ఆ, ఇ); పదజాలం: అర్థాలు, పర్యాయపదాలు, నానార్థాలు (పుట 33)","పదజాలం: మిత్రుడు, వ్యుత్పత్త్యర్థాలు, ప్రకృతి–వికృతి; వ్యాకరణం: సంధులు విడదీయడం, కలపడం (పుట 34)","ఇ) అనునాసిక సంధి, ఈ) సమాసాలు, ఉ) అలంకారాలు (పుట 35)","దృష్టాంతాలంకారం, ఊ) గురులఘువులు – గణవిభజన, ప్రాజెక్టుపని (పుట 36)"]},"tg":[["అవగాహన – ప్రతిస్పందన: అ) ప్రశ్నలు, ఆ) పద్య భావం (పుట 31)",["అ) 1) పాఠంలోని పద్యాలను రాగ, భావయుక్తంగా పాడాలి (ఉపాధ్యాయుని సహాయంతో సాధన చేయండి)","2) నమూనా: వేమన పద్యం \"భూమిలోన బుట్టు…\" నచ్చింది – శ్రమే సర్వ సంపదలకు మూలమని చెబుతుంది; కష్టపడే రైతులు, కూలీల గొప్పతనం తెలుస్తుంది. కుప్పుస్వామి శతక పద్యం కూడా నచ్చింది – మాతృభాష, మాతృదేశంపై ప్రేమ ఉండాలని చెబుతుంది","3) గుణవంతుడు నిండుకుండలా తొణకడు – న్యాయం ఆలోచించి మృదువుగా, హితంగా మాట్లాడతాడు; నీచుడిలా కఠినమైన మాటలు (నిష్ఠురోక్తులు) పలకడు","4) మాతృభాషపై, మాతృదేశంపై మమత ఉండాలి; మృగాలు, పక్షులకు కూడా తమ జాతిపై అభిమానం ఉంటుంది – మమత లేనివాడు మనిషే కాదు","ఆ) పద్య భావం: సద్గురువు చేసే ఉపదేశ సారం వల్ల ఎంత గొప్ప అజ్ఞానమైనా తొలగిపోతుంది – మంచి వైద్యుడు ఇచ్చే చిన్న మాత్రతో భయంకరమైన రోగం తగ్గిపోయినట్లు. (చిలకమర్తి లక్ష్మీనరసింహం)"]],["ఇ) అపరిచిత గద్యం, ఈ) అర్థసందర్భాలు, ఉ) ఏకవాక్య సమాధానాలు (పుట 32)",["ఇ) 1) శుభదత్తుడికి సంతానం లేదు 2) ముసలి కోతి చీల్చుతున్న దూలం మీద చీలికలో కూర్చుని, అందులో బిగించిన కొయ్య మేకును బలంగా ఊడబెరికింది – చీలిక మూసుకుపోయి నలిగి చనిపోయింది 3) నీతి: మనకు సంబంధం లేని పనుల్లో తలదూర్చకూడదు 4) ఉదా: శుభదత్తుడు తన ధనాన్ని ఏ పనులకు ఖర్చు చేశాడు?","ఈ) 1) \"పనుల ననుసరించి ఫలములు చేకూరు\" – కవయిత్రి: దార్ల సుందరీమణి, భావలింగ శతకం (శతక మాధుర్యం పాఠం). సందర్భం: మనసులోని భావాన్ని బట్టి మాట, మాటను బట్టి పని ఉంటాయని చెబుతూ అన్న మాట. అర్థం: మనం చేసే పనులను బట్టే ఫలితాలు వస్తాయి","2) \"మాతృభాష యందు మాతృదేశమునందు మమత లేనివాడు మనుజుండగునె\" – కవి: త్రిపురనేని రామస్వామి చౌదరి, కుప్పుస్వామి శతకం. సందర్భం: మృగపక్షులకు కూడా తమ జాతిపై మమత ఉంటుందని చెబుతూ అన్న మాట. అర్థం: మాతృభాష, మాతృదేశం పట్ల ప్రేమ లేనివాడు మనిషి కాదు","ఉ) 1) ముక్తకం అంటే దేనికదే స్వతంత్ర భావం గల పద్యం 2) చంచలమైన మనసుకు ఏకాగ్రత, ఉన్నదానితో తృప్తి పడే వివేకం ఇమ్మని కోరాడు 3) సజ్జన సాంగత్యం దుర్జనుణ్ణి కూడా మంచివాడిగా మార్చి పరసేవ చేసేలా చేస్తుంది","వ్యక్తీకరణ అ) 1) సంస్కారులు సత్యం, శీలం, ధర్మాలను తిరిగి స్థాపించడానికి ప్రతి యుగంలో పుడతారు. వారికి వివేకం, విచక్షణ, సహజ శక్తి ఉంటాయి. సమాజంలో చెడు పెరిగినప్పుడు దానిని తొలగించి మంచి మార్గం చూపిస్తారు. వారి ఆచరణే ఇతరులకు ఆదర్శం"]],["వ్యక్తీకరణ – సృజనాత్మకత (అ, ఆ, ఇ); పదజాలం: అర్థాలు, పర్యాయపదాలు, నానార్థాలు (పుట 33)",["అ) 2) సత్ఫలితాలు పొందాలంటే మంచి ఆలోచనలు చేయాలి; ఆలోచనకు తగిన మంచి మాటలు మాట్లాడాలి; మాటకు తగినట్లు మంచి పనులు చేయాలి. భావం–మాట–పని–ఫలితం ఒకదాని వెంట ఒకటి వస్తాయి (భావలింగ శతకం). కష్టపడి శ్రమించాలి","3) ధీరోత్తములు నీతివేత్తలు పొగిడినా, నిందించినా చలించరు; సంపదలు నిలిచినా పోయినా లెక్కచేయరు; మరణం ఇప్పుడే వచ్చినా, యుగాంతంలో వచ్చినా న్యాయమార్గం నుండి ఒక్క అడుగు కూడా తప్పరు","ఆ) 1) విద్యావంతులు శౌర్యం (జన్మసాఫల్యం), శాంతం (వివేక సాధనం), ఆత్మగౌరవం (గొప్ప సంపద), లజ్జ (సంజీవనం), వినయంతో కూడిన మాట (అందరినీ ఆకట్టుకుంటుంది), సదాచారం (పెనుబలం), దానం (దాచుకున్న సంపద), సజ్జన సాంగత్యం (సుఖం) అనే గుణాలను వదలరు; భగవంతుని భక్తితో సేవిస్తారు (వేంకటేశ శతకం)","2) నైతిక విలువలు – సత్యం, నిజాయితీ, వినయం, దయ, శ్రమపట్ల గౌరవం, బాధ్యత – మనిషిని మనిషిగా నిలుపుతాయి. అవి లేకపోతే మోసం, స్వార్థం, హింస పెరుగుతాయి. కుటుంబంలో ప్రేమ, సమాజంలో నమ్మకం, దేశంలో శాంతి నైతిక విలువల వల్లే ఉంటాయి. శతక పద్యాలు ఇవే నేర్పుతాయి – మంచివారితో స్నేహం, మాతృభాష–దేశంపై ప్రేమ, న్యాయమార్గం, గర్వం లేకపోవడం. చిన్నప్పటి నుండి వీటిని అలవాటు చేసుకుంటే ఉత్తమ పౌరులం అవుతాం","3) పది నీతివాక్యాలు: 1. గుణవంతుడు కఠినంగా మాట్లాడడు 2. రాజుల కంటే భగవంతుని ఆశ్రయం మేలు 3. ధర్మస్థాపనకు సంస్కారులు పుడుతూనే ఉంటారు 4. శ్రమే సర్వ సంపదలకు మూలం 5. ధీరులు న్యాయమార్గం విడువరు 6. జ్ఞానం పెరిగితే గర్వం తగ్గాలి 7. పనులను బట్టి ఫలితాలు 8. మాతృభాష, మాతృదేశంపై మమత ఉండాలి 9. సత్సంగం దుర్జనుణ్ణీ మారుస్తుంది 10. వినయం, దానం, శాంతం గొప్ప సంపదలు","ఇ) 1) ప్రకటన: \"విద్యార్థులకు శుభవార్త! జిల్లా పరిషత్ ఉన్నత పాఠశాల, టి.వి. పల్లిలో ఈ నెల 15న ఉదయం 10 గంటలకు శతక పద్యాల పోటీ జరుగుతుంది. 6 నుండి 10వ తరగతి విద్యార్థులందరూ పాల్గొనవచ్చు. ప్రతి ఒక్కరూ ఏదైనా శతకం నుండి రెండు పద్యాలు రాగయుక్తంగా పాడి భావం చెప్పాలి. విజేతలకు బహుమతులు. పేర్లు తెలుగు ఉపాధ్యాయుని వద్ద నమోదు చేసుకోండి. – ప్రధానోపాధ్యాయులు\"","2) నీతికథ (నిండుకుండ పద్యానికి): ఒక ఊరిలో రాము, సోము ఉండేవారు. సోముకు కొంచెం చదువు రాగానే అందరినీ ఎగతాళి చేసేవాడు. రాము బాగా చదువుకున్నా నెమ్మదిగా, మర్యాదగా మాట్లాడేవాడు. ఊరి పెద్ద ఒకసారి ఇద్దరినీ ప్రశ్నలు అడిగాడు – సోము తడబడ్డాడు, రాము చక్కగా జవాబిచ్చాడు. పెద్ద \"నిండుకుండ తొణకదు, వెలితికుండ తొణుకుతుంది\" అన్నాడు. నీతి: గుణవంతులు గర్వపడరు","పదజాలం అ) 1) దుష్టుడు = చెడ్డవాడు 2) ఖ్యాతి = కీర్తి 3) తల్పం = పాన్పు, శయ్య 4) కానలు = అడవులు 5) భాస్వంతుడు = సూర్యుడు","ఆ) పర్యాయపదాలు: 1) పండితుడు = విద్వాంసుడు, బుధుడు 2) భుజగం = పాము, సర్పం 3) కరి = ఏనుగు, గజం 4) పక్షి = పులుగు, విహంగం 5) హరి = విష్ణువు, నారాయణుడు","ఇ) నానార్థాలు: 1) ధర = భూమి, వెల 2) శ్రీ = లక్ష్మి, సంపద 3) వారి = నీరు, సముద్రం (వారిధి) / వారు 4) శ్రమ = కష్టం, అలసట"]],["పదజాలం: మిత్రుడు, వ్యుత్పత్త్యర్థాలు, ప్రకృతి–వికృతి; వ్యాకరణం: సంధులు విడదీయడం, కలపడం (పుట 34)",["ఆ) 5) మిత్రుడు = స్నేహితుడు, సూర్యుడు (నానార్థం) / చెలికాడు","ఈ) 1) భాస్కరుడు – కాంతిని కలిగించువాడు (సూర్యుడు) 2) భుజగము – భుజములతో (వంకరగా) పోవునది (పాము) 3) ఈశ్వరుడు – ఐశ్వర్యం కలవాడు (శివుడు) 4) హస్తి – హస్తం (తొండం) కలది (ఏనుగు)","ఉ) 1) చంద్రుడు – ఆ (చందురుడు) 2) నిత్యము – ఉ (నిచ్చలు) 3) స్వామి – అ (సామి) 4) హంస – ఇ (అంచ) 5) ధర్మము – ఈ (దమ్మము)","సంధి అ) 1) నిష్ఠురోక్తులు = నిష్ఠుర + ఉక్తులు (గుణ సంధి) 2) వేంకటేశ = వేంకట + ఈశ (గుణ సంధి) 3) అవ్వారి = ఆ + వారి (త్రిక సంధి) 4) మనుజుడగునే = మనుజుడు + అగునే (ఉకార సంధి) 5) ధీరోత్తముడు = ధీర + ఉత్తముడు (గుణ సంధి)","ఆ) 1) కాళికా + అంబ = కాళికాంబ (సవర్ణదీర్ఘ సంధి) 2) ఆ + పలుకులు = అప్పలుకులు (త్రిక సంధి) 3) దానంబు + చేయుట = దానంబు సేయుట (గసడదవాదేశ సంధి) 4) ఏల + ఒకో = ఏలొకో (అకార సంధి)"]],["ఇ) అనునాసిక సంధి, ఈ) సమాసాలు, ఉ) అలంకారాలు (పుట 35)",["ఇ) 1) జగత్ + నివేశ = జగన్నివేశ 2) దిక్ + మండలము = దిఙ్మండలము 3) రాట్ + మణి = రాణ్మణి (అనునాసిక సంధి)","ఈ) 1) శౌర్యలక్ష్మి – శౌర్యము అనెడి లక్ష్మి (రూపక సమాసం) 2) ప్రతిదినము – దినము దినము (అవ్యయీభావ సమాసం) 3) బ్రతుకుదెరువు – బ్రతుకు యొక్క తెరువు (షష్ఠీ తత్పురుష) 4) సజ్జనసంగతి – సజ్జనుల యొక్క సంగతి (షష్ఠీ తత్పురుష) 5) గురుతరబాధ్యత – గురుతరమైన బాధ్యత (విశేషణ పూర్వపద కర్మధారయ)","ఉ) 1) వృత్త్యనుప్రాసాలంకారం (\"క్ష\" పలుమార్లు) 2) వృత్త్యనుప్రాసాలంకారం (\"ద\" పలుమార్లు) 3) వృత్త్యనుప్రాసాలంకారం (\"క్ష\" పలుమార్లు)"]],["దృష్టాంతాలంకారం, ఊ) గురులఘువులు – గణవిభజన, ప్రాజెక్టుపని (పుట 36)",["దృష్టాంత ఉదాహరణలు: 1) వెలితికుండ తొణుకుతుంది, నిండుకుండ తొణకదు – నీచుడు కఠినంగా మాట్లాడతాడు, గుణవంతుడు మాట్లాడడు (పద్యం 1) 2) సూర్యుని స్నేహంతో సముద్రం తీయని నీరిస్తుంది – సత్సంగంతో దుర్జనుడూ మంచివాడవుతాడు (పద్యం 10) 3) మంచి వైద్యుని చిన్న మాత్రతో రోగం తొలగుతుంది – సద్గురువు ఉపదేశంతో అజ్ఞానం పోతుంది","ఊ) పద్యం 5 \"నీతి ప్రౌఢ…\" – శార్దూలం: నీతిప్రౌ (UUU మ)","ఢవిహా (IIU స)","రులైన (IUI జ)","నిపుణుల్ (IIU స)","నిందింప (UUI త)","నీమెచ్చ (UUI త)","నీ (U గ). లక్షణాలు: 4 పాదాలు; మ స జ స త త గ గణాలు; 19 అక్షరాలు; 13వ అక్షరం యతి; ప్రాస నియమం ఉంది","పద్యం 6 \"తెలివి యొకింత…\" – చంపకమాల: న జ భ జ జ జ ర గణాలు; 21 అక్షరాలు; 11వ అక్షరం యతి; ప్రాస నియమం ఉంది (తెలివి – III న గణంతో మొదలవుతుంది)","పద్యం 10 \"ధరలో నెంతటి…\" – మత్తేభం: ధరలో (IIU స)","నెంతటి (UII భ)","దుర్జనుం (UIU ర)","డయిన (III న)","సత్సంగ (UUU మ)","ప్రభా (IUU య)","వంబుచేఁ (IU వ). లక్షణాలు: 4 పాదాలు; స భ ర న మ య వ; 20 అక్షరాలు; 14వ అక్షరం యతి; ప్రాస నియమం ఉంది","ప్రాజెక్టు: పట్టిక – కవి","కాలం","శతకం","మకుటం → మారద వెంకయ్య","1550–1600","భాస్కర","భాస్కరా; ధూర్జటి","16వ శ.","శ్రీకాళహస్తీశ్వర","శ్రీకాళహస్తీశ్వరా; వీరబ్రహ్మం","17వ శ.","కాళికాంబ","కాళికాంబ! హంస! కాళికాంబ; వేమన","1652–1730","వేమన","విశ్వదాభిరామ వినురవేమ; దార్ల సుందరీమణి","19వ శ.","భావలింగ","భావలింగ; త్రిపురనేని","1887–1943","కుప్పుస్వామి","కుప్పుసామి; షేక్ మహమ్మద్ హుస్సేన్","20వ శ.","హరిహరనాథ","హరిహరనాథా; గాడేపల్లి","1935–2018","వేంకటాద్రీశ్వర","వేంకటాద్రీశ్వరా; పెద్ద తిరుమలాచార్యులు","1460–1548","వేంకటేశ","వేంకటేశ"]]]},{"id":"te4","no":4,"t":"ఉపన్యాస కళ","m":[7],"ty":"వ్యాసం","th":"వ్యక్తిత్వ వికాసం – మాటతీరు","by":"వాసిరెడ్డి సీతాదేవి","sum":"మాట (వాక్కు) మనిషిని ఇతర ప్రాణుల నుండి వేరు చేసి సృష్టిలో ఉన్నత స్థానం ఇచ్చింది. వక్తృత్వం పుట్టుకతో వచ్చే వరం కాదు – కృషి, సాధన, పట్టుదల ఉంటే ఎవరైనా వక్త కావచ్చు; లింకన్, రూజ్వెల్ట్, చర్చిల్ మొదట్లో ఇబ్బందిపడి సాధనతోనే మహావక్తలయ్యారు (చర్చిల్ అద్దం ముందు అభ్యాసం చేసేవాడు). ఇతరులను అనుకరించకూడదు – కాగితం పువ్వులో గులాబీ సువాసన రాదు. సభాకంపం అందరికీ సహజం. వేదికపై హుందాగా కూర్చోవాలి, సందర్భానికి తగిన దుస్తులు ధరించాలి; మైకు ముందు రిలాక్స్‌గా నిలబడాలి. ప్రసంగానికి ప్రారంభం, విషయ ప్రతిపాదన, ఉపసంహారం అనే మూడు భాగాలు. ఊతపదాలు, స్వోత్కర్ష, అతిగా పొగడడం, కఠినమైన పండిత భాష మానాలి; సరళ వ్యావహారిక భాషలో మాట్లాడాలి. శ్రోతల ఆసక్తి తగ్గకముందే ముగించాలి. ఉపన్యాసం తర్వాత తనను తాను ప్రశ్నించుకుని లోపాలు సరిదిద్దుకోవాలి.","pts":["రచయిత్రి: వాసిరెడ్డి సీతాదేవి – గుంటూరు జిల్లా చేబ్రోలు; 39 నవలలు, 100కు పైగా కథలు; \"మట్టి మనిషి\" 14 భాషల్లోకి అనువాదం; జవహర్ బాలభవన్ డైరెక్టర్; సాహిత్య అకాడమీ పురస్కారం 5 సార్లు; \"ఆంధ్ర పెర్ల్‌బక్\"; మరణం 13.04.2007.","ప్రక్రియ: వ్యాసం – ఒక విషయాన్ని పూర్వాపరాలతో విశ్లేషిస్తూ రాయడం; ఉపోద్ఘాతం, విషయ విస్తరణ, ముగింపు ప్రధానాంగాలు.","\"మాట్లాడే శక్తిని వదిలి నా సర్వస్వం దోచుకున్నా విచారించను\" – డేనియల్ వెబ్‌స్టర్; \"బలమైన శబ్దం ఇవ్వు, ప్రపంచాన్ని ఊపేస్తాను\" – జోసఫ్ కాన్రాడ్.","వక్తృత్వం: కృషి, సాధన, పట్టుదలతో ఎవరైనా వక్త కావచ్చు – చర్చిల్ ఉదాహరణ.","అనుకరణ వద్దు; సభాకంపం 100 మందిలో 99 మందికి సహజం.","వేదిక మర్యాద: ఊగడం, నేలచూపులు, ఆవలింత, చేయి ఊపడం, కాలు మీద కాలు – ఇవి మానాలి.","ప్రసంగ భాగాలు: 1. ప్రారంభం (క్షణం మౌనం, చిరునవ్వు) 2. విషయ ప్రతిపాదన (స్పష్టమైన వాచకం, ఆరోహణ–అవరోహణ, మధ్యమ స్వరం) 3. ఉపసంహారం (ఆసక్తి తగ్గకముందే ముగింపు).","ఊతపదాలు (\"అన్నమాట\", \"అంచేత\") అదుపులో; భాష సరళ వ్యావహారికం.","ఆగస్టు 7 – ప్రొఫెషనల్ స్పీకర్స్ దినోత్సవం."],"w":[["శబ్దకోశం","నిఘంటువు"],["అపహాస్యం","ఎగతాళి"],["సానపట్టు","పదును పెట్టు"],["ఆసీనులు","కూర్చున్నవారు"],["మనీష","బుద్ధి"],["మనీషి","బుద్ధిమంతుడు, జ్ఞాని"],["కుత్తుక","కంఠం"],["శ్రోతలు","వినేవారు"],["సభాకంపం","సభలో మాట్లాడేటప్పుడు కలిగే భయం"],["స్వోత్కర్ష","తనను తాను పొగుడుకోవడం"],["రసాభాస","రసభంగం, గందరగోళం"],["ఊతపదం","అలవాటుగా మళ్ళీ మళ్ళీ వచ్చే మాట"],["హుందాగా","గౌరవంగా"],["ఉపసంహారం","ముగింపు"],["కరతలామలకం","అరచేతిలో ఉసిరికాయ – చాలా సులభం"]],"gr":{"t":"భాషాంశాలు","p":["ప్రాతాది సంధి: సమాసంలో ప్రాతాదుల (ప్రాత, లేత, క్రొత్త, క్రిందు, పూవు, మీదు, కెంపు, చెన్ను…) తొలి అచ్చు మీది వర్ణాలకు బహుళంగా లోపం – క్రొత్త + మావి = క్రొమ్మావి, ముందు + చేయి = ముంజేయి, మీదు + కడ = మీగడ, లేత + మొగ్గ = లేమొగ్గ.","గుణ సంధి: అ + ఇ/ఉ/ఋ → ఏ/ఓ/అర్ – ఉన్నత + ఉన్నత = ఉన్నతోన్నత; స్వ + ఉత్కర్ష = స్వోత్కర్ష.","యణాదేశ సంధి: ఇ/ఉ/ఋ + అసవర్ణ అచ్చు → య/వ/ర – అతి + అంత = అత్యంత.","వాక్యాల రకాలు: ప్రశ్నార్థకం (\"…పిరికివాళ్ళా?\"), విధ్యర్థకం (\"అదుపులో పెట్టుకోండి\"), సందేహార్థకం (\"…ఉండవచ్చునేమో\")."]},"qa":[["మనిషికి మనీషికి తేడా?","మాట్లాడగల ప్రాణి మనిషి; మనీష (బుద్ధి/జ్ఞానం) కలవాడు మనీషి – వాక్కును సాధన చేసి జ్ఞాని అయినవాడు."],["వాక్కుకు సానపట్టడం అంటే?","మాట్లాడే శక్తిని సాధనతో పదును పెట్టి మెరుగుపరచుకోవడం."],["చర్చిల్‌కు గొప్ప వక్తగా గుర్తింపు ఎలా వచ్చింది?","జనం ముందు ఇబ్బందిపడినా పట్టుదలతో శ్రమించాడు; అద్దం ముందు నిలబడి ప్రసంగం అభ్యాసం చేశాడు."],["అనుకరణ ఎందుకు మంచిది కాదు?","అనుకరించగానే శ్రోతలు గుర్తించి నవ్వుతారు; అసలు అసలే, నకిలీ నకిలీయే – కాగితం పువ్వులో గులాబీ సువాసన రాదు."],["ప్రసంగ భాగాలు ఏవి?","ప్రారంభం, విషయ ప్రతిపాదన, ఉపసంహారం."],["ప్రేక్షకులను ఆకట్టుకునే మంచి చిట్కా?","ప్రేక్షకులను సంబోధించే ముందు, ఒక అంశం నుండి మరో అంశానికి వెళ్ళే ముందు ఒక క్షణం మౌనం."],["ఉపన్యాస భాష ఎలా ఉండాలి?","సరళ వ్యావహారిక భాష – శ్రోతలు విషయం వినడానికి వస్తారు, భాష నేర్చుకోవడానికి కాదు."]],"act":"తరగతిలో ప్రతి విద్యార్థి \"మా ఊరు – టి.వి. పల్లి\" లేదా \"చెట్ల పెంపకం\" అంశంపై 2 నిమిషాలు మాట్లాడండి; తర్వాత పాఠంలోని 10 స్వీయ ప్రశ్నలతో మీ ప్రసంగాన్ని మీరే అంచనా వేసుకోండి.","kn":"పగటి వేషాలు (బహురూపాలు) – కృష్ణా జిల్లా గడ్డిపాడు కేంద్రం. కసుమూరు మస్తానయ్య దర్గా (నెల్లూరుకు 35 కి.మీ.) – సర్వమత సమ్మేళనానికి నిదర్శనం; ఏటా ఉరుసు జరుగుతుంది.","qz":[["\"ఉపన్యాస కళ\" రచయిత్రి?","వాసిరెడ్డి సీతాదేవి","మూలింటి చంద్రకళ","ఓల్గా","రంగనాయకమ్మ"],["ఈ పాఠం ప్రక్రియ?","వ్యాసం","కథానిక","శతకం","నాటిక"],["వాసిరెడ్డి సీతాదేవిని ఏమని పిలుస్తారు?","ఆంధ్ర పెర్ల్‌బక్","ఆంధ్ర కోకిల","కవికోకిల","కళాప్రపూర్ణ"],["14 భాషల్లోకి అనువదించబడిన సీతాదేవి నవల?","మట్టి మనిషి","బతుకు గంప","ఖూని","సూతపురాణం"],["అద్దం ముందు ప్రసంగం అభ్యాసం చేసిన మహావక్త?","చర్చిల్","ఐన్‌స్టీన్","వెబ్‌స్టర్","కాన్రాడ్"],["ప్రసంగంలోని మూడు భాగాలు?","ప్రారంభం, విషయ ప్రతిపాదన, ఉపసంహారం","ఉపోద్ఘాతం, కథ, నీతి","పద్యం, భావం, ముగింపు","ప్రశ్న, జవాబు, చర్చ"],["సభలో మాట్లాడేటప్పుడు కలిగే భయాన్ని ఏమంటారు?","సభాకంపం","సభామర్యాద","స్వోత్కర్ష","రసాభాస"],["ఉపన్యాసంలో ఉత్తమమైన స్వరస్థాయి?","మధ్యమ స్థాయి","చాలా పెద్ద స్వరం","చాలా తగ్గు స్వరం","ఒకే స్థాయి గీతలా"],["ఉపన్యాసంలో వాడవలసిన భాష?","సరళ వ్యావహారిక భాష","కఠిన గ్రాంథిక భాష","ఆంగ్లం మాత్రమే","సంస్కృత పదాలు"],["తెలివైన వక్త ఉపన్యాసం ఎప్పుడు ముగిస్తాడు?","శ్రోతల ఆసక్తి తగ్గకముందే","శ్రోతలు లేచి వెళ్ళాక","మైకు ఆగిపోయాక","అధ్యక్షుడు అడిగాక"],["\"అన్నమాట\", \"అంచేత\" వంటి వాటిని ఏమంటారు?","ఊతపదాలు","జాతీయాలు","సామెతలు","నానార్థాలు"],["తనను తాను పొగుడుకోవడాన్ని ఏమంటారు?","స్వోత్కర్ష","సభాకంపం","అనుకరణ","ఉపసంహారం"],["ప్రొఫెషనల్ స్పీకర్స్ దినోత్సవం?","ఆగస్టు 7","జూన్ 5","సెప్టెంబర్ 5","నవంబర్ 14"],["\"బలమైన శబ్దం ఇవ్వు, ప్రపంచాన్ని ఊపేస్తాను\" అన్నది?","జోసఫ్ కాన్రాడ్","చర్చిల్","లింకన్","గాంధీ"],["క్రొత్త + మావి = క్రొమ్మావి – సంధి?","ప్రాతాది సంధి","గుణ సంధి","యణాదేశ","త్రిక సంధి"],["పాఠాంత పద్యం (ఇచ్చిన మాట తప్పను) కవి?","బమ్మెర పోతన","వేమన","ధూర్జటి","తిక్కన"]],"wb":{"mis":"ప్రాతాది సంధిలో మొదటి పదం తొలి అక్షరం మాత్రమే మిగులుతుంది (క్రొత్త → క్రొం/క్రొ). \"సమయసందర్భాలు\" ద్వంద్వ సమాసం (మరియు/ను); \"రెండునిమిషాలు\" ద్విగు (సంఖ్యతో మొదలవుతుంది).","qz":[["ఏడేళ్ళు విడదీస్తే?","ఏడు + ఏళ్ళు (ఉకార సంధి)","ఏ + డేళ్ళు","ఏడ + ఏళ్ళు","ఏడి + ఏళ్ళు"],["మహోత్కృష్ట విడదీస్తే?","మహా + ఉత్కృష్ట (గుణ సంధి)","మహో + త్కృష్ట","మహ + ఓత్కృష్ట","మహి + ఉత్కృష్ట"],["అతి + అంత = ?","అత్యంత (యణాదేశ సంధి)","అతీంత","అతంత","అతేంత"],["స్వ + ఉత్కర్ష = ?","స్వోత్కర్ష (గుణ సంధి)","స్వూత్కర్ష","స్వత్కర్ష","స్వాత్కర్ష"],["మీదు + కడ = ?","మీగడ (ప్రాతాది సంధి)","మీదుకడ","మీదగడ","మీకడ"],["\"సభాకంపం\" విగ్రహవాక్యం?","సభ వలన కంపం","సభ మరియు కంపం","సభ అనెడి కంపం","సభ యొక్క కంపం లేనిది"],["\"రెండునిమిషాలు\" సమాసం?","ద్విగు సమాసం","ద్వంద్వ","బహువ్రీహి","అవ్యయీభావ"],["\"ప్రసన్నవదనం\" సమాసం?","విశేషణ పూర్వపద కర్మధారయ","షష్ఠీ తత్పురుష","ద్వంద్వ","ద్విగు"],["\"అలవాటును అదుపులో పెట్టుకోండి\" – వాక్యం?","విధ్యర్థక వాక్యం","ప్రశ్నార్థక","సందేహార్థక","ఆశీరర్థక"],["\"ముందు మాట్లాడిన వక్త అభిమానులు శ్రోతల్లో ఉండవచ్చునేమో\" – వాక్యం?","సందేహార్థక వాక్యం","నిషేధార్థక","విధ్యర్థక","అనుమత్యర్థక"]],"pg":"38–51","f":"books/10/Class10_Telugu_Textbook_Sem1.pdf","p":46,"lb":"పాఠ్యపుస్తకం","ws":["అవగాహన – ప్రతిస్పందన: అ) చర్చ, ఆ) ఉపన్యాసం చదివి జవాబులు (పుట 44)","ఆ) ఉపన్యాసం (మిగతా), ఇ) అపరిచిత గద్యం, ఈ) సందర్భసహిత వాక్యాలు (పుట 45)","ఉ) ఏకవాక్య సమాధానాలు; వ్యక్తీకరణ – సృజనాత్మకత; పదజాలం (పుట 46)","పర్యాయపదాలు, ఇ) జాతీయాలు; వ్యాకరణం: సంధులు (పుట 47)","ప్రాతాది సూత్రం; ఇ, ఈ) సమాసాలు; ఉ, ఊ) వాక్యాల రకాలు (పుట 48)","ప్రాజెక్టుపని (పుట 49)"]},"tg":[["అవగాహన – ప్రతిస్పందన: అ) చర్చ, ఆ) ఉపన్యాసం చదివి జవాబులు (పుట 44)",["అ) 1) అవును – వక్తృత్వం పుట్టుకతో వచ్చే వరం కాదు. కృషి, సాధన, పట్టుదల ఉంటే ఎవరైనా వక్త కావచ్చు. లింకన్, రూజ్వెల్ట్, చర్చిల్ మొదటి వేదికపై ఇబ్బందిపడ్డవారే; చర్చిల్ అద్దం ముందు నిలబడి అభ్యాసం చేసి ప్రపంచ ప్రసిద్ధ వక్తయ్యాడు. ఒకటి రెండు ప్రయత్నాల్లో విఫలమై విరమించుకోవడం పొరపాటు","2) ఊతపదాలు ఆలోచించుకోవడానికి కొంత సమయం ఇస్తాయి, మాటల మధ్య ఖాళీ నింపుతాయి (లాభం). కానీ అతిగా వస్తే (\"అన్నమాట\", \"అంచేత\", \"అసలు విషయం\") శ్రోతలు నవ్వుతారు, తామే ఊతమిస్తారు, ఏకాగ్రత చెదిరి ఉపన్యాసం మధ్యలో ఆగిపోతుంది (నష్టం). కాబట్టి వాటిని అదుపులో పెట్టుకోవాలి","ఆ) 1) ఆ కార్యక్రమానికి ఎప్పుడో ఒప్పుకున్నాడు; చాలామంది ఎదురుచూస్తుంటారు – వారిని నిరాశపరచడం ఇష్టం లేదు"]],["ఆ) ఉపన్యాసం (మిగతా), ఇ) అపరిచిత గద్యం, ఈ) సందర్భసహిత వాక్యాలు (పుట 45)",["ఆ) 2) సమయస్ఫూర్తి అంటే అనుకోని సమస్య ఎదురైనప్పుడు వెంటనే తెలివిగా ఆలోచించి తగిన విధంగా స్పందించడం 3) వాహనచోదకుడు ఆత్మవిశ్వాసంతో తనలాగే ఉపన్యసించడం, క్లిష్టమైన ప్రశ్న రాగానే \"చివరి వరుసలోని మా వాహనచోదకుడు కూడా చెప్పగలడు\" అని తప్పించుకున్న సమయస్ఫూర్తి చూసి ఆశ్చర్యపడ్డాడు 4) ఆత్మవిశ్వాసం, సమయస్ఫూర్తి, విషయ పరిజ్ఞానం, స్పష్టమైన మాటతీరు, శ్రోతలను ఆకట్టుకునే నేర్పు","ఇ) 1) విధేయత, సంసిద్ధత, కార్యదీక్ష 2) పవిత్రత, సహనం, పట్టుదల – వీటన్నిటికంటే ప్రేమ 3) అభివృద్ధికరమైన, లోకోపకారకమైన గొప్ప భావాలు 4) ఉదా: సమస్త ఆపదలకు ఏకైక కారణం ఏది? (బలహీనత)","ఈ) 1) \"నా వాక్కుతో నేను పోగొట్టుకున్నవన్నీ తిరిగి సంపాదించుకోగలను\" – ఆక్స్‌ఫర్డ్ శబ్దకోశకారుడు డేనియల్ వెబ్‌స్టర్ అన్న మాట (ఉపన్యాస కళ – వాసిరెడ్డి సీతాదేవి). సందర్భం: మాట్లాడే శక్తి తప్ప సర్వస్వం దోచుకున్నా విచారించనని, వాక్కు ఎంత గొప్పదో చెప్పిన సందర్భం","2) \"మాట్లాడగల శక్తి ప్రతి మానవుడికీ ఉంది. ఆ వాక్కుకు నేను సాన పట్టాను\" – చర్చిల్ మాట. సందర్భం: మొదట్లో జనం ముందు ఇబ్బందిపడి, పట్టుదలతో శ్రమించి గొప్ప వక్తనయ్యానని చెప్పిన సందర్భం","3) \"తెలివైన వక్త శ్రోతల ఆసక్తి స్థాయి పడిపోక ముందే తన ఉపన్యాసం ముగిస్తాడు\" – రచయిత్రి ఉపసంహారం గురించి చెబుతూ, మైకు వదలని \"మైకాసురుల\" గురించి చెప్పిన సందర్భం"]],["ఉ) ఏకవాక్య సమాధానాలు; వ్యక్తీకరణ – సృజనాత్మకత; పదజాలం (పుట 46)",["ఉ) 1) వక్త వేదికపై హుందాగా, సందర్భానికి తగిన దుస్తులతో, సభామర్యాద పాటిస్తూ ప్రవర్తించాలి 2) శ్రోతల ఆసక్తి స్థాయి పడిపోకముందే ముగిస్తాడు 3) ప్రేక్షకులను సంబోధించే ముందు, ఒక అంశం నుండి మరో అంశానికి మారే ముందు ఒక క్షణం మౌనం వహించడం","అ) 1) సభలో మాట్లాడేటప్పుడు కలిగే భయం, వణుకు సభాకంపం. గొప్ప వక్తలు కూడా మొదటి వేదికపై దీనికి గురైనవారే – ఇది సహజం. ముందుగా విషయం బాగా సిద్ధం చేసుకోవాలి, అద్దం ముందు/ఇంట్లో అభ్యాసం చేయాలి, చిన్న సభల్లో మాట్లాడటం అలవాటు చేసుకోవాలి, ఆత్మవిశ్వాసంతో ప్రారంభంలో ఒక క్షణం మౌనంగా నిలబడి చిరునవ్వుతో మొదలుపెట్టాలి","2) వేదికపై ఎబ్బెట్టుగా కూర్చున్నప్పుడు, సందర్భానికి తగని దుస్తులు ధరించినప్పుడు, ఇతరులను అనుకరించినప్పుడు, అతిగా పొగిడినప్పుడు/అతిశయోక్తులు చెప్పినప్పుడు, స్వోత్కర్ష చేసుకున్నప్పుడు, ఊతపదాలు ఎక్కువైనప్పుడు, మైకు వదలకుండా సాగదీసినప్పుడు వక్త అపహాస్యం పాలవుతాడు","3) సూక్తి/కవితా చరణం ఒకరిది మరొకరిదిగా చెప్పినప్పుడు, ముందు వక్త అభిప్రాయాలను అక్కసుతో ఖండించినప్పుడు, వేదికపైని వ్యక్తుల గురించి అనవసరంగా మాట్లాడినప్పుడు, \"ప్రసంగించడం\" బదులు \"ప్రసవించడం\" వంటి తప్పు ఉచ్చారణ చేసినప్పుడు ఉపన్యాసం రసాభాస అవుతుంది","ఆ) 1) ఉపన్యాస భాష సరళ వ్యావహారికంగా ఉండాలి. కొందరు పాండిత్యం చూపడానికి పెద్ద పెద్ద పదాలు వాడతారు – బహిరంగ సభల్లో అది పనికిరాదు; శ్రోతలు విషయం వినడానికి వస్తారు, భాష నేర్చుకోవడానికి కాదు. వాచకం స్పష్టంగా ఉండాలి; స్వరంలో ఆరోహణ–అవరోహణలు ఉండాలి; మధ్యమ స్థాయి మేలు. కొత్త వక్తలు కొన్ని పదాలు జాగ్రత్తగా పలకాలి. ఊతపదాలు తగ్గించాలి. మధ్యలో చమత్కారాలు, పెద్దల సూక్తులు (ఎవరివో సరిగా తెలుసుకుని) చెప్పాలి. ఉదాహరణలు క్లుప్తంగా, అతిశయోక్తులు లేకుండా ఉండాలి","2) మంచి వక్త కావాలంటే: కృషి, సాధన, పట్టుదల కావాలి; ఒకటి రెండు వైఫల్యాలకు వెనుకడుగు వేయకూడదు; చర్చిల్‌లా అద్దం ముందు అభ్యాసం చేయాలి; ఎవరినీ అనుకరించకూడదు – మనం మనంగా ఉండాలి; సభాకంపం సహజమని గ్రహించాలి; వేదికపై హుందాగా ఉండాలి; మైకు ముందు రిలాక్స్‌గా నిలవాలి; ప్రారంభం–విషయ ప్రతిపాదన–ఉపసంహారం క్రమంగా ఉండాలి; సరళ భాష, స్పష్టమైన వాచకం; ఊతపదాలు, స్వోత్కర్ష, అతిగా పొగడడం మానాలి; సమయానికి ముగించాలి; ఉపన్యాసం తర్వాత ఆత్మపరిశీలన చేసుకోవాలి","3) నేను వేదికపై ఎలా ప్రవర్తించాను? బిగిసిపోయి కూర్చున్నానా, హాయిగా ఉన్నానా? గొంతు మైకుకు సరిపోయిందా? శ్రోతలతో స్నేహపూర్వక వాతావరణం ఏర్పడిందా? సమయానికి ముగించానా? అనుకున్న అంశాలన్నీ చెప్పానా? ముఖ్యమైనవి ఎందుకు మరిచాను? శ్రోతలు పక్కవారితో మాట్లాడుతున్నారా? \"బ్రతుకుజీవుడా\" అని ముందే కూర్చున్నానా? శ్రోతల అసహనంతో మధ్యలో ఆపానా? – వీటి జవాబులతో లోపాలు తెలిసి మళ్ళీ జరగకుండా చూసుకోవచ్చు","ఇ) 1) ఉపన్యాస ప్రతి సిద్ధం: స్వాతంత్ర్య పోరాటం, నాయకుల త్యాగాలు (గాంధీ, నెహ్రూ, అల్లూరి, భగత్ సింగ్), జాతీయ పతాకం, నేటి మన బాధ్యతలు – సమాచారం సేకరిస్తాను. ప్రారంభం: \"గౌరవనీయులైన ప్రధానోపాధ్యాయులకు, ఉపాధ్యాయులకు, మిత్రులకు స్వాతంత్ర్య దినోత్సవ శుభాకాంక్షలు\". విషయం: 1947 ఆగస్టు 15 ప్రాధాన్యం, త్యాగాలు, నేటి ప్రగతి. ముగింపు: \"చదువుతో, క్రమశిక్షణతో దేశాన్ని ముందుకు నడిపిద్దాం – జై హింద్!\". 3 నిమిషాల్లో ముగిసేలా అద్దం ముందు అభ్యాసం చేస్తాను","2) అభినందన పత్రం: \"ప్రియమైన చి. ______ కి, జిల్లాస్థాయి వక్తృత్వ పోటీలో ప్రథమ బహుమతి సాధించి మన పాఠశాల (జి.ప.ఉ.పా., టి.వి. పల్లి) పేరును జిల్లా అంతటా వినిపించావు. నీ స్పష్టమైన వాచకం, ఆత్మవిశ్వాసం, విషయ పరిజ్ఞానం మాకు గర్వకారణం. ఇదే పట్టుదలతో రాష్ట్రస్థాయిలోనూ విజయం సాధించాలని ఆశిస్తున్నాం. – ప్రధానోపాధ్యాయులు, ఉపాధ్యాయ బృందం, విద్యార్థులు\"","పదజాలం అ) 1) శబ్దకోశం = నిఘంటువు – తెలియని పదాలకు నిఘంటువు చూడాలి 2) అపహాస్యం = ఎగతాళి – ఎవరినీ ఎగతాళి చేయకూడదు 3) సానపట్టు = పదును పెట్టు – సాధన మాటకు పదును పెడుతుంది 4) ఆసీనులు = కూర్చున్నవారు – అతిథులు వేదికపై కూర్చున్నారు","ఆ) 1) మనీష = బుద్ధి, ప్రజ్ఞ 2) కుత్తుక = కంఠం, గొంతు 3) శ్రోతలు = వినేవారు, ఆలకించువారు"]],["పర్యాయపదాలు, ఇ) జాతీయాలు; వ్యాకరణం: సంధులు (పుట 47)",["ఆ) 4) వేదిక = వేదిక మంచె, అరుగు (స్టేజి) / ఆసీనులు = కూర్చున్నవారు","ఇ) 1) సానబట్టు – ఏదైనా నైపుణ్యాన్ని సాధనతో మెరుగుపరచుకున్నప్పుడు; ఉదా: చర్చిల్ తన వాక్కుకు సానబట్టాడు 2) ఏ పుట్టలో ఏముందో – ఎవరిలో ఏ ప్రతిభ దాగి ఉందో చెప్పలేనప్పుడు; ఉదా: పల్లెటూరి పిల్లవాడు జిల్లా విజేత అయ్యాడు – ఏ పుట్టలో ఏముందో! 3) నేల చూపులు చూడటం – సిగ్గు, భయం లేదా అపరాధభావంతో ఎదుటివారి ముఖం చూడలేనప్పుడు","సంధి అ) 1) ఏడేళ్ళు = ఏడు + ఏళ్ళు (ఉకార సంధి) 2) మహోత్కృష్ట = మహా + ఉత్కృష్ట (గుణ సంధి) 3) ఎవరన్నారు = ఎవరు + అన్నారు (ఉకార సంధి) 4) పొందాలనుకుంటారు = పొందాలి + అనుకుంటారు (ఇకార సంధి) 5) కదిలినప్పుడు = కదిలిన + అప్పుడు (అకార సంధి)","ఆ) 1) ఉన్నత + ఉన్నత = ఉన్నతోన్నత (గుణ సంధి) 2) అతి + అంత = అత్యంత (యణాదేశ సంధి) 3) ఉత్తమము + ఐనది = ఉత్తమమైనది (ఉకార సంధి) 4) స్వ + ఉత్కర్ష = స్వోత్కర్ష (గుణ సంధి)","ప్రాతాది సంధి ఉదాహరణలు: క్రొత్త + మావి = క్రొమ్మావి; ముందు + చేయి = ముంజేయి; ప్రాత + కెంపు = ప్రాగెంపు; లేత + మొగ్గ = లేమొగ్గ; క్రొత్త + చెమట = క్రొంజెమట; మీదు + కడ = మీగడ; క్రొత్త + కుండలు = క్రొంగుండలు"]],["ప్రాతాది సూత్రం; ఇ, ఈ) సమాసాలు; ఉ, ఊ) వాక్యాల రకాలు (పుట 48)",["సూత్రం: సమాసంబున ప్రాతాదుల తొలియచ్చు మీది వర్ణంబులకెల్ల లోపంబు బహుళంబుగా నగు (తర్వాత నుగాగమం, సరళాదేశం జరిగి తుదిరూపం వస్తుంది)","ఇ) 1) శబ్దశక్తి – శబ్దము యొక్క శక్తి 2) కార్యక్షేత్రం – కార్యము యొక్క క్షేత్రం 3) సమయసందర్భాలు – సమయమును, సందర్భమును 4) వింతచప్పుడు – వింతయైన చప్పుడు 5) సభాకంపం – సభ వలన కంపం","ఈ) 1) గులాబీపువ్వు – గులాబీ అను పేరుగల పువ్వు (సంభావనా పూర్వపద కర్మధారయ) 2) ప్రజాహితం – ప్రజల యొక్క హితం (షష్ఠీ తత్పురుష) 3) ప్రసన్నవదనం – ప్రసన్నమైన వదనం (విశేషణ పూర్వపద కర్మధారయ) 4) ఉత్తమవక్త – ఉత్తముడైన వక్త (విశేషణ పూర్వపద కర్మధారయ) 5) రెండునిమిషాలు – రెండు సంఖ్య గల నిమిషాలు (ద్విగు సమాసం)","ఉ) 1) ప్రశ్నార్థక వాక్యం 2) విధ్యర్థక వాక్యం 3) సందేహార్థక వాక్యం 4) ప్రశ్నార్థక వాక్యం","ఊ) ప్రశ్నార్థక వాక్యాలు: 1) వక్తృత్వ ప్రావీణ్యత ఒక వరమా? 2) అది కొందరికే పుట్టుకతో లభ్యమయ్యే కళా? 3) గులాబీలో ఉండే సుగంధాన్ని కాగితం పువ్వులో నింపగలమా? 4) సభలో మాట్లాడడానికి భయపడేవాళ్లు పిరికివాళ్లా?"]],["ప్రాజెక్టుపని (పుట 49)",["ప్రముఖ వక్తలు: 1) స్వామి వివేకానంద – 1893 చికాగో సర్వమత సమ్మేళనంలో \"అమెరికా సోదర సోదరీమణులారా\" ప్రసంగం 2) ఎ.పి.జె. అబ్దుల్ కలాం – విద్యార్థులను \"కలలు కనండి\" అని ప్రేరేపించిన ప్రసంగాలు 3) దుగ్గిరాల గోపాలకృష్ణయ్య – \"ఆంధ్రరత్న\"; చీరాల–పేరాల ఉద్యమం 4) సరోజినీ నాయుడు – \"భారత కోకిల\"; స్వాతంత్ర్య ఉద్యమ ప్రసంగాలు. (పేరు, కాలం, ప్రసిద్ధ ప్రసంగం, ప్రభావం – పట్టికగా రాసి ప్రదర్శించండి)"]]]},{"id":"te5","no":5,"t":"జలియన్‌వాలా బాగ్","m":[8],"ty":"ఖండకావ్యం (పద్యాలు)","th":"దేశభక్తి","by":"డా. ఉమర్ ఆలీషా","sum":"1919 ఏప్రిల్ 13న పంజాబ్‌లోని అమృత్‌సర్ జలియన్‌వాలా బాగ్‌లో వైశాఖీ పండుగ రోజు సభకు చేరిన నిరాయుధ ప్రజలపై జనరల్ డయ్యర్ 1650 రౌండ్లు కాల్పులు జరిపించాడు; వందలాది మంది మరణించారు, వేలాది మంది గాయపడ్డారు. ఈ దురంతాన్ని కవి ఆవేదనతో వర్ణించాడు. మొదటి ప్రపంచ యుద్ధంలో ఆంగ్ల కిరీటం కోసం మంచురాళ్లపై నిద్రిస్తూ, నీళ్ళు తాగి బతుకుతూ, వెన్ను చూపకుండా సింహంలా పోరాడి విజయం తెచ్చిన భారత వీరులకు బహుమతిగా రౌలట్ చట్టం అనే గాలం వేశారని, భారతీయులను \"వట్టి సేవకులు\" అనడానికి నోరెలా వచ్చిందని ప్రశ్నిస్తాడు. బానిసత్వాన్ని ఉగ్గుపాలతో పోసి, అన్నవస్త్రాలు దోచి, కరువు, కక్షలు, పన్నులు, మత్తు పదార్థాలతో దేశాన్ని పీల్చిన ఆంగ్లేయుల దుర్మార్గాలను, పసిపిల్లలను ఎండలో నడిపించడం, పొట్టపై పాకించడం వంటి చిత్రహింసలను వివరిస్తాడు. ఈ పాపం ఊరికే పోదని, వడ్డీతో అనుభవించక తప్పదని హెచ్చరిస్తాడు.","pts":["కవి: కవిశేఖర డా. ఉమర్ ఆలీషా (28.02.1885 – 23.01.1945) – పిఠాపురం (కాకినాడ జిల్లా); తల్లిదండ్రులు చాంద్‌బీబీ, మొహియుద్దీన్ బాద్షా.","మహాకవి, వక్త, అవధాని, ఆధ్యాత్మికవేత్త, బహుభాషా పండితుడు, పార్లమెంటు సభ్యుడు; గురుపీఠం \"జ్ఞానసభ\".","రచనలు: మణిమాల, అనసూయాదేవి, చంద్రగుప్త (నాటకాలు); బ్రహ్మవిద్యా విలాసం, సూఫీ వేదాంత దర్శనం; పండిట్, మౌల్వీ బిరుదులు; ఇంటర్నేషనల్ అకాడమీ ఆఫ్ అమెరికా గౌరవ డాక్టరేట్.","పాఠం \"ఖండ కావ్యములు\" గ్రంథం నుండి.","ప్రక్రియ: ఖండకావ్యం – ఒక స్వతంత్ర ఘట్టం / చారిత్రక సంఘటన / స్వీయానుభవం తీసుకుని రాసే చిన్న కావ్యం; ఆత్మాశ్రయ రీతి; వస్తువు, భావం, శైలిలో నవ్యత.","జలియన్‌వాలా బాగ్ – అమృత్‌సర్ (పంజాబ్) లోని ఉద్యానవనం; 13 ఏప్రిల్ 1919, వైశాఖీ; జనరల్ డయ్యర్; 1650 రౌండ్ల కాల్పులు.","రౌలట్ చట్టం – తిరుగుబాట్లను అణచడానికి బ్రిటిష్ వారు తెచ్చిన నిరంకుశ శాసనం (విచారణ లేకుండా నిర్బంధం).","పద్యాలు: ఉత్పలమాల, చంపకమాల, శార్దూలం, సీసం + తేటగీతి."],"w":[["కాటకం","కరువు"],["సితజాతి","తెల్లజాతి (ఆంగ్లేయులు)"],["తులువ","దుష్టుడు"],["రుధిరం","రక్తం"],["పయోదం","మేఘం"],["ఆర్తి","బాధ, దుఃఖం"],["రణం","యుద్ధం"],["ఉదకం","నీరు"],["నీహారం","మంచు"],["హర్యక్షం","సింహం"],["అఘం","పాపం"],["శుద్ధాంతం","అంతఃపురం"],["మూక","గుంపు"],["ఫరంగి","ఆంగ్లేయుడు (విదేశీయుడు)"],["ఆసవం","మద్యం"]],"gr":{"t":"భాషాంశాలు","p":["జశ్త్వ సంధి: వర్గ ప్రథమాక్షరాలకు (క,చ,ట,త,ప) అచ్చులు, స్థిరాలు (య,వ,ర,హ), వర్గ తృతీయ/చతుర్థ/పంచమాలు పరమైతే గ,జ,డ,ద,బ లు ఆదేశం – వాక్ + ఈశుడు = వాగీశుడు, జగత్ + అంబ = జగదంబ, విరాట్ + రూపం = విరాడ్రూపం.","సీస పద్యం: ప్రతి పాదం రెండు భాగాలు; 8 గణాలు (6 ఇంద్ర + 2 సూర్య) – మొదటి భాగంలో 4 ఇంద్ర, రెండో భాగంలో 2 ఇంద్ర + 2 సూర్య; ప్రతి అర్ధభాగంలో 3వ గణం మొదటి అక్షరంతో యతి; ప్రాసయతి చెల్లుతుంది; ప్రాస లేదు; చివర తేటగీతి/ఆటవెలది తప్పనిసరి.","ఉత్పలమాల: భ ర న భ భ ర వ; 20 అక్షరాలు; 10వ అక్షరం యతి. చంపకమాల: న జ భ జ జ జ ర; 21 అక్షరాలు; 11వ అక్షరం యతి.","రూపకాలంకారం: ఉపమేయ ఉపమానాలకు అభేదం – \"దుఃఖ సముద్రము\" (దుఃఖమే సముద్రం)."]},"qa":[["జలియన్‌వాలా బాగ్‌లో భారతీయులను పొట్టన పెట్టుకున్నదెవరు?","బ్రిటిష్ అధికారి జనరల్ డయ్యర్."],["రౌలట్ చట్టం ఎందుకు రూపొందించారు?","భారతీయుల తిరుగుబాట్లను, స్వాతంత్ర్య ఉద్యమాన్ని అణచివేయడానికి."],["బ్రిటిష్ వారు భారతీయులను ఎలా భావించారు?","కేవలం తమకు \"వట్టి సేవకులు\" గా, బానిసలుగా."],["భారత వీరుని పరాక్రమం ఎటువంటిది?","మంచురాళ్లపై నిద్రించి, ఉన్నది తిని లేకపోతే నీళ్ళు తాగి పోరాడాడు; సింహంలా శత్రుగజాలను చీల్చాడు; అగ్నిగోళాలకు ఆహుతైనా వెన్ను చూపలేదు."],["కాల్పుల సమయంలో బాగ్‌లో పరిస్థితి?","రక్తం వర్షంలా ప్రవహించింది; మొండేలతో బతికినవారి ఆర్తనాదాలు దిక్కుల్లో మారుమోగాయి; ప్రళయం వచ్చిందని ప్రజలు ప్రాణభయంతో పారిపోయారు."],["తెల్లదొరలు చేసిన చిత్రహింసలు?","పసిపిల్లలను ఎండలో నడిపించారు, ప్రజలను పొట్టపై పాకించారు, నిరపరాధులను కొట్టారు, స్త్రీలను అవమానించారు, వేలాది మందిని కాల్చి చంపారు."]],"act":"మీ ప్రాంతంలోని (గూడూరు, నెల్లూరు జిల్లా) స్వాతంత్ర్య సమరయోధుల వివరాలు సేకరించి నివేదిక తయారు చేసి తరగతిలో ప్రదర్శించండి; ఏప్రిల్ 13న జలియన్‌వాలా బాగ్ అమరులకు శ్రద్ధాంజలి కార్యక్రమం నిర్వహించండి.","kn":"చెక్క భజన – చేతుల్లో చెక్కలు, కాళ్లకు గజ్జెలతో గుండ్రంగా తిరుగుతూ చేసే జానపద భక్తి నృత్యం. మొహర్రం (పీర్ల పండుగ) – ఇస్లాం నూతన సంవత్సరం; హసన్, హుసేన్‌ల త్యాగ స్మరణ.","qz":[["\"జలియన్‌వాలా బాగ్\" పాఠం కవి?","డా. ఉమర్ ఆలీషా","గుర్రం జాషువా","కరుణశ్రీ","నార్ల చిరంజీవి"],["ఈ పాఠం ప్రక్రియ?","ఖండకావ్యం","శతకం","వ్యాసం","కథానిక"],["జలియన్‌వాలా బాగ్ ఉన్న నగరం?","అమృత్‌సర్","ఢిల్లీ","లాహోర్","కలకత్తా"],["కాల్పులకు ఆదేశించిన బ్రిటిష్ అధికారి?","జనరల్ డయ్యర్","లార్డ్ కర్జన్","మౌంట్‌బాటన్","వెల్లస్లీ"],["జలియన్‌వాలా బాగ్ దురంతం జరిగిన సంవత్సరం?","1919","1857","1942","1930"],["ఆ రోజు పంజాబీల పండుగ?","వైశాఖీ","దీపావళి","హోళీ","సంక్రాంతి"],["తిరుగుబాట్లను అణచడానికి తెచ్చిన శాసనం?","రౌలట్ చట్టం","ఉప్పు చట్టం","భూమి చట్టం","పన్నుల చట్టం"],["ఉమర్ ఆలీషా జన్మస్థలం?","పిఠాపురం","అమృత్‌సర్","నెల్లూరు","విజయవాడ"],["ఉమర్ ఆలీషా గురుపీఠం పేరు?","జ్ఞానసభ","సాహితీ సమితి","కవిసభ","భువనవిజయం"],["రౌలట్ చట్టాన్ని కవి దేనితో పోల్చాడు?","చేపలను పట్టే గాలంతో","కత్తితో","అగ్నితో","విషంతో"],["భారత వీరుడు శత్రువులను చీల్చడంలో దేనితో పోలిక?","సింహం (హర్యక్షం)","ఏనుగు","గుర్రం","నక్క"],["\"బానిసత్వము నుగ్గు పాలఁ బోసిన దోషి\" – ఎవరు?","ఆంగ్లేయుడు","భారతీయుడు","సామంతరాజు","కవి"],["వాక్ + ఈశుడు = వాగీశుడు – సంధి?","జశ్త్వ సంధి","అనునాసిక సంధి","గుణ సంధి","సవర్ణదీర్ఘ"],["సీస పద్యంలో ప్రతి పాదంలో గణాలు?","6 ఇంద్ర + 2 సూర్య","3 సూర్య + 2 ఇంద్ర","5 సూర్య","భ ర న భ భ ర వ"],["సీస పద్యం తర్వాత తప్పనిసరిగా వచ్చేది?","తేటగీతి లేదా ఆటవెలది","కందం","ఉత్పలమాల","మత్తేభం"],["\"దుఃఖ సముద్రము\" – అలంకారం?","రూపకం","ఉపమ","వృత్త్యనుప్రాసం","ఛేకానుప్రాసం"]],"wb":{"mis":"జశ్త్వ సంధిలో మొదటి పదం చివర క/చ/ట/త/ప ఉండాలి – అవి గ/జ/డ/ద/బ గా మారతాయి (జగత్ + అంబ = జగదంబ; \"జగతంబ\" కాదు). సీసంలో యతి ప్రతి అర్ధపాదంలో 3వ గణం మొదటి అక్షరం.","qz":[["కవటాకులు విడదీస్తే?","కవట + ఆకులు (సవర్ణదీర్ఘ సంధి)","కవ + టాకులు","కవటా + కులు","కవటు + ఆకులు"],["ప్రాణార్థములు విడదీస్తే?","ప్రాణ + అర్థములు (సవర్ణదీర్ఘ సంధి)","ప్రాణా + ర్థములు","ప్రాణ + ఆర్థములు (గుణ)","ప్రాణు + అర్థములు"],["పాలుం జేసి విడదీస్తే?","పాలున్ + చేసి (సరళాదేశ సంధి)","పాలు + జేసి","పా + లుంజేసి","పాలుం + జేసి (ఉత్వ)"],["ధ్వజమెత్తి విడదీస్తే?","ధ్వజము + ఎత్తి (ఉత్వ సంధి)","ధ్వజ + మెత్తి","ధ్వజమ + ఎత్తి","ధ్వజం + ఎత్తి (గుణ)"],["వాగ్వాదం విడదీస్తే?","వాక్ + వాదం (జశ్త్వ సంధి)","వాగ + వాదం","వా + గ్వాదం","వాగు + వాదం"],["దిగంతం విడదీస్తే?","దిక్ + అంతం (జశ్త్వ సంధి)","దిగ + అంతం","ది + గంతం","దిక + అంతం"],["\"శౌర్యపరాక్రమములు\" సమాసం?","ద్వంద్వ సమాసం","ద్విగు","షష్ఠీ తత్పురుష","బహువ్రీహి"],["\"దేహపంజరం\" విగ్రహవాక్యం?","దేహము అనెడి పంజరం (రూపక సమాసం)","దేహము యొక్క పంజరం","దేహము మరియు పంజరం","దేహమైన పంజరం"],["యముడు – వికృతి?","జముడు","చండి","దోసి","రక్కసుడు"],["\"వెన్నుచూపు\" జాతీయం అర్థం?","భయపడి పారిపోవు","ధైర్యంగా నిలుచు","సహాయం చేయు","వెనుక చూడు"]],"pg":"52–64","f":"books/10/Class10_Telugu_Textbook_Sem1.pdf","p":60,"lb":"పాఠ్యపుస్తకం","ws":["అవగాహన – ప్రతిస్పందన: అ) చర్చ, ఆ) గేయం (పుట 58)","ఇ) అపరిచిత గద్యం, ఈ) అర్థసందర్భాలు, ఉ) ఏకవాక్య సమాధానాలు (పుట 59)","వ్యక్తీకరణ – సృజనాత్మకత; పదజాలం (పుట 60)","వ్యుత్పత్త్యర్థాలు, వికృతులు, జాతీయాలు; సంధులు, జశ్త్వ సంధి (పుట 61)","జశ్త్వ సంధి అన్వయం; ఇ, ఈ) సమాసాలు; ఉ) అలంకారం; ఊ) గణవిభజన (పుట 62)","సీస పద్య లక్షణ సమన్వయం; ప్రాజెక్టుపని (పుట 63)"]},"tg":[["అవగాహన – ప్రతిస్పందన: అ) చర్చ, ఆ) గేయం (పుట 58)",["అ) 1) రౌలట్ చట్టం ప్రకారం విచారణ లేకుండానే ఎవరినైనా అరెస్టు చేసి జైల్లో పెట్టవచ్చు; పత్రికా స్వేచ్ఛ, ప్రజల హక్కులు హరించబడ్డాయి. మొదటి ప్రపంచ యుద్ధంలో ఆంగ్లేయుల కోసం ప్రాణాలొడ్డి పోరాడిన భారతీయులకు బహుమతిగా ఇలాంటి నిరంకుశ చట్టం ఇవ్వడం కృతఘ్నత – అందుకే వ్యతిరేకించారు","2) భారత వీరుడు ఆంగ్ల కిరీట రక్షణ కోసం భక్తిశ్రద్ధలతో పోరాడాడు; ఆహారం కోసం దేహీ అనలేదు; సింహంలా శత్రుగజాల కుంభస్థలాలు చీల్చాడు; రాత్రింబవళ్ళు మంచురాళ్లపై నిద్రించాడు; ఉన్నది తిని, లేకుంటే నీళ్ళు తాగి జీవించాడు; మద్యం కోసం శత్రువుల వైపు వెళ్ళలేదు; అగ్నిగోళాలకు ఆహుతైనా వెన్ను చూపలేదు; తుపాకి గుండ్లు దేహాన్ని జల్లెడ చేసినా శత్రువుకు చిక్కలేదు","3) \"ప్రళయపయోదముల్…\" భావం: ప్రళయకాల మేఘాలు వర్షించినట్లు ఆంగ్లేయులు ఫిరంగి గుండ్ల వాన కురిపించి దేహమనే పంజరాన్ని జల్లెడలా మార్చినా, భారత వీరుడు అలసి నిట్టూర్చలేదు, శత్రువు చేతికి చిక్కలేదు. బలవంతులైన శత్రువులనే చెట్లకు పెనుగాలి వంటి భారత వీరుని పరాక్రమం మాటలతో చెప్పలేము","ఆ) 1) భారతమాతకు 2) బంగారు పూవులు, జీవనదులు, సంపదలు, పవిత్ర ఋక్కులు (వేదాలు), భవ్య కావ్యాలు, హిమాలయాది పర్వతాలు, ఋషుల వాక్కులు, సామగానాలు, దివ్య శిల్పులు, గాయకులు, ప్రపంచానికి ఆదర్శాలు 3) పుస్తకంలో కవి పేరు ఇవ్వలేదు – ఉపాధ్యాయుని సహాయంతో తెలుసుకుని రాయండి 4) శీర్షిక: \"భారతమాతకు వందనం\""]],["ఇ) అపరిచిత గద్యం, ఈ) అర్థసందర్భాలు, ఉ) ఏకవాక్య సమాధానాలు (పుట 59)",["ఇ) 1) సైనిక దాడులను అరికట్టవచ్చేమో గానీ ప్రజల హృదయాల నుండి పొంగే స్వాతంత్ర్య భావ తరంగాలను ఆపలేరు 2) మనకు వెలుగుబాట చూపి, మన వ్యక్తిత్వాన్ని వికసింపజేసి ప్రజలను చైతన్యవంతులను చేశారు 3) నిర్బంధాలతో, \"విభజించి పాలించు\" పద్ధతితో, స్వల్ప సంస్కరణలతో బుజ్జగించి అణచాలని చూసింది 4) ఉదా: మన దేశానికి స్వరాజ్యం ఎలా సిద్ధించింది?","ఈ) 1) \"సితజాతికి నీతియటంచు నున్నదే\" – కవి: డా. ఉమర్ ఆలీషా, \"ఖండ కావ్యములు\" నుండి జలియన్‌వాలా బాగ్ పాఠం. సందర్భం: యూరపు యుద్ధంలో విజయం తెచ్చిన భారత వీరులకు రౌలట్ శాసనాగ్నితో బదులిచ్చిన ఆంగ్లేయులను నిందిస్తూ అన్న మాట. అర్థం: తెల్లజాతికి నీతి అనేది ఉందా? (లేదు)","2) \"కయ్యాల బెంచిన కఠినతముడు\" – కవి: ఉమర్ ఆలీషా, జలియన్‌వాలా బాగ్. సందర్భం: ఆంగ్లేయుని దుర్మార్గాలను వరుసగా వర్ణించే సీస పద్యంలోనిది. అర్థం: భారతీయుల మధ్య తగవులు పెంచిన అతి కఠిన హృదయుడు ఆంగ్లేయుడు","ఉ) 1) జనరల్ డయ్యర్ (ఆంగ్ల పిశాచం) 2) రౌలట్ చట్టం 3) ఆంగ్లేయుడు (బ్రిటిష్ పాలకుడు)"]],["వ్యక్తీకరణ – సృజనాత్మకత; పదజాలం (పుట 60)",["అ) 1) భారత వీరులు యూరపు యుద్ధంలో తమ రణనైపుణ్యంతో శత్రువులను చీల్చి చెండాడి, రక్తసిక్తులై విజయధ్వజం ఎగురవేశారు. ఆహారం లేకున్నా నీళ్ళు తాగి, మంచురాళ్లపై నిద్రించి పోరాడారు. ఫిరంగి గుండ్లు దేహాన్ని జల్లెడ చేసినా శత్రువుకు లొంగలేదు. అగ్నికి ఆహుతైనా వెన్ను చూపలేదు","2) బ్రిటిష్ వారు \"విభజించి పాలించు\" విధానంతో కులాల, మతాల, ప్రాంతాల మధ్య కక్షలు, కయ్యాలు పెంచారు. కరువు తెచ్చారు, అన్నవస్త్రాలు దోచారు, భారీ పన్నులు వేశారు, మత్తు పదార్థాలు అమ్మి సంపద పీల్చారు, నిర్బంధ శాసనాలు తెచ్చారు","3) నిరాయుధ ప్రజలపై తుపాకుల వాన కురిసింది. బయటికి వెళ్ళే దారి లేదు. రక్తం వర్షంలా ప్రవహించింది. మొండేలతో బతికినవారి ఆర్తనాదాలు దిక్కుల్లో మారుమోగాయి. ప్రళయం వచ్చిందని ప్రజలు ప్రాణభయంతో పరుగులు తీశారు. పిల్లలు, స్త్రీలు, వృద్ధులు నేలకొరిగారు","ఆ) 1) 1919 ఏప్రిల్ 13న అమృత్‌సర్ జలియన్‌వాలా బాగ్‌లో వైశాఖీ పండుగ రోజు రౌలట్ చట్టానికి వ్యతిరేకంగా శాంతియుత సభ జరుగుతోంది; పండుగ చూడవచ్చిన ప్రజలూ చేరారు. తన ఆదేశాలను ధిక్కరించారని జనరల్ డయ్యర్ సైనికులతో వచ్చి ఏకైక ద్వారాన్ని మూసి, ఎలాంటి హెచ్చరిక లేకుండా నిరాయుధ ప్రజలపై 1650 రౌండ్లు కాల్పులు జరిపించాడు. తప్పించుకునే దారి లేక చాలామంది బావిలో దూకారు. వందలాది మంది మరణించారు, వేలాది మంది గాయపడ్డారు. స్త్రీలు, పిల్లలు కూడా బలయ్యారు. ఈ ఘటన దేశమంతా ఆగ్రహం రగిలించింది; రవీంద్రనాథ్ ఠాగూర్ \"సర్\" బిరుదును త్యజించారు. స్వాతంత్ర్య చరిత్రలో ఇది చీకటి రోజుగా మిగిలింది; ఉద్యమం మరింత ఉధృతమైంది","2) ఆంగ్లేయులు వ్యాపారం పేరుతో వచ్చి దేశాన్ని ఆక్రమించారు. భారీ పన్నులతో రైతులను పీల్చారు; కరువులు వచ్చినా పట్టించుకోలేదు; మన కుటీర పరిశ్రమలు నాశనం చేసి విదేశీ వస్తువులు అమ్మారు; మత్తు పదార్థాలతో సంపద దోచారు. కులమతాల మధ్య కక్షలు పెంచారు. రౌలట్ వంటి నిర్బంధ చట్టాలతో స్వేచ్ఛ హరించారు; ప్రశ్నించినవారిని జైల్లో పెట్టారు, కాల్చారు. భారతీయులను సేవకులుగా, బానిసలుగా చూశారు. ప్రజలు ఆకలి, పేదరికం, అవమానాలతో బతికారు","3) అల్లూరి సీతారామరాజు – మన్యం విప్లవం, ఆంగ్లేయులను గడగడలాడించాడు; కొమరం భీం – \"జల్, జంగల్, జమీన్\"; టంగుటూరి ప్రకాశం పంతులు – \"ఆంధ్ర కేసరి\", సైమన్ కమిషన్‌కు తుపాకీకి ఎదురు నిలిచాడు; పొట్టి శ్రీరాములు – గాంధేయవాది, ఆంధ్ర రాష్ట్రం కోసం ఆత్మార్పణ (నెల్లూరు); దుగ్గిరాల గోపాలకృష్ణయ్య – చీరాల–పేరాల ఉద్యమం; పింగళి వెంకయ్య – జాతీయ పతాక రూపకర్త; ఉయ్యాలవాడ నరసింహారెడ్డి – 1846లోనే ఆంగ్లేయులపై తిరుగుబాటు; దుర్గాబాయి దేశ్‌ముఖ్ – ఉప్పు సత్యాగ్రహం","ఇ) 1) ఏకపాత్ర (నమూనా): \"ఓరీ డయ్యరూ! ఆగు! నిరాయుధులైన నా సోదరులపై తుపాకులెక్కుపెట్టడమేనా నీ వీరత్వం? మీ యుద్ధాల్లో మీ కిరీటం కోసం మంచుపై పడుకుని, ఆకలితో పోరాడి విజయం తెచ్చిన చేతులు ఇవే! దానికి బహుమతి రౌలట్ గాలమా? గుర్తుంచుకో – తుపాకులు శరీరాలను కూల్చగలవు, స్వాతంత్ర్య కాంక్షను కాదు. ఈ రక్తం ఊరికే పోదు. ప్రతి చుక్క ఒక వీరుడై పుడుతుంది. భారతమాతకు జై!\"","2) అభినందన పత్రం: \"మన్యం వీరుడు అల్లూరి సీతారామరాజు గారికి – విల్లంబులతో తుపాకులను ఎదిరించి, గిరిజనులను ఏకం చేసి ఆంగ్ల ప్రభుత్వాన్ని గడగడలాడించిన మీ ధైర్యం, త్యాగం మాకు స్ఫూర్తి. 27 ఏళ్ల వయసులోనే దేశం కోసం ప్రాణాలర్పించిన మీకు జి.ప.ఉ.పా. టి.వి. పల్లి విద్యార్థుల జోహార్లు!\"","పదజాలం అ) 1) కాటకం = కరువు – కాటకం వల్ల రైతులు బాధపడ్డారు 2) సితజాతి = తెల్లజాతి – సితజాతి వారు మన దేశాన్ని పాలించారు 3) తులువ = దుష్టుడు – తులువలకు దూరంగా ఉండాలి 4) రుధిరం = రక్తం – రుధిరదానం ప్రాణదానం","ఆ) 1) పయోదం = మేఘం, మబ్బు, జలదం 2) ఆర్తి = బాధ, దుఃఖం, వేదన 3) రణం = యుద్ధం, పోరు, సమరం 4) ఉదకం = నీరు, జలం, సలిలం","ఇ) 1) హరి = విష్ణువు, సింహం, కోతి, ఇంద్రుడు 2) గజం = ఏనుగు, కొలతకర్ర (గజం పొడవు) 3) మోక్షం = ముక్తి, విడుదల","ఈ) 1) నీహారము – నిశ్చయముగా హరింపబడునది (మంచు)"]],["వ్యుత్పత్త్యర్థాలు, వికృతులు, జాతీయాలు; సంధులు, జశ్త్వ సంధి (పుట 61)",["ఈ) 2) పాతకము – పతనమునకు (నరకమునకు) కారణమైనది (పాపం) 3) పానీయము – పానము చేయదగినది (నీరు, పానకం)","ఉ) 1) యముడు – జముడు 2) దోషి – దోసి 3) చండికా – చండి 4) రాక్షసుడు – రక్కసుడు","ఊ) 1) అంగలార్చు – ఆశతో, ఆతృతతో పడే బాధ; ఉదా: భారత సైనికుడు ఆహారానికి అంగలార్చలేదు 2) వెన్నుచూపు – భయపడి పారిపోవు; ఉదా: వీరులు యుద్ధంలో వెన్నుచూపరు 3) ఉగ్గుపాలతో పెట్టు – చిన్నప్పటి నుండే అలవాటు చేయు; ఉదా: ఆంగ్లేయులు బానిసత్వాన్ని ఉగ్గుపాలతో పోశారు","అ) 1) కవటాకులు = కవట + ఆకులు (సవర్ణదీర్ఘ సంధి) 2) ప్రాణార్థములు = ప్రాణ + అర్థములు (సవర్ణదీర్ఘ సంధి) 3) పాలుం జేసి = పాలున్ + చేసి (సరళాదేశ సంధి) 4) ధ్వజమెత్తి = ధ్వజము + ఎత్తి (ఉత్వ సంధి)","ఆ) సవర్ణదీర్ఘ: కవటాకులు, ప్రాణార్థములు, శుద్ధాంతము (శుద్ధ + అంతము), మహాప్రళయము; సరళాదేశ: పాలుం జేసి, బోసిన (పాలన్ + పోసిన), దూరి వధించెన్ + తత్; ఉత్వ: ధ్వజమెత్తి, రక్తమొలికించెన్ (రక్తము + ఒలికించెన్), మోసములకు నెలవు"]],["జశ్త్వ సంధి అన్వయం; ఇ, ఈ) సమాసాలు; ఉ) అలంకారం; ఊ) గణవిభజన (పుట 62)",["జశ్త్వం: 1) వాగ్వాదం = వాక్ + వాదం – \"క\" కు స్థిరమైన \"వ\" పరమై \"గ\" ఆదేశం 2) హృద్ద్వారం = హృత్ + ద్వారం – \"త\" కు వర్గ తృతీయమైన \"ద\" పరమై \"ద\" ఆదేశం 3) దిగంతం = దిక్ + అంతం – \"క\" కు అచ్చు పరమై \"గ\" ఆదేశం","ఇ) 1) శౌర్యపరాక్రమములు – శౌర్యమును, పరాక్రమమును (ద్వంద్వ) 2) శుద్ధాంతకాంత – శుద్ధాంతము నందలి కాంత (సప్తమీ తత్పురుష) 3) పాపఫలం – పాపము యొక్క ఫలం (షష్ఠీ తత్పురుష) 4) దేహపంజరం – దేహము అనెడి పంజరం (రూపక సమాసం) 5) రాకాసిమూక – రాకాసుల యొక్క మూక (షష్ఠీ తత్పురుష) 6) ఘోరరణం – ఘోరమైన రణం (విశేషణ పూర్వపద కర్మధారయ)","ఈ) మరికొన్ని: దుఃఖసముద్రము – దుఃఖము అనెడి సముద్రము (రూపక); జయధ్వజము – జయము యొక్క ధ్వజము (షష్ఠీ); భారతవీరుడు – భారతదేశము యొక్క వీరుడు (షష్ఠీ); పసిబాలురు – పసివారైన బాలురు (విశేషణ పూర్వపద కర్మధారయ); మహాప్రళయము – గొప్పదైన ప్రళయము (విశేషణ పూర్వపద కర్మధారయ)","ఉ) రూపకాలంకారం – దుఃఖానికి, సముద్రానికి అభేదం చెప్పారు","ఊ) 1) రౌలటు (UII భ)","శాసనం (UIU ర)","బుసమ (III న)","రంబున (UII భ)","గెల్చిన (UII భ)","దానికం (UIU ర)","కుగా (IU వ) → ఉత్పలమాల పద్యపాదం (భ ర న భ భ ర వ; 20 అక్షరాలు; యతి 1–10 అక్షరాలు: రౌ–రం)","2) జలియ (III న)","నుబాగు (IUI జ)","లోజను (UII భ)","లజంపి (IUI జ)","నరక్త (IUI జ)","మువర్ష (IUI జ)","పాతముం (UIU ర) → చంపకమాల పద్యపాదం (న జ భ జ జ జ ర; 21 అక్షరాలు; యతి 1–11 అక్షరాలు: జ–జం)"]],["సీస పద్య లక్షణ సమన్వయం; ప్రాజెక్టుపని (పుట 63)",["ఊ) 1) బానిస (UIU ర)","త్వమునుగ్గు (IIUI సల)","పాలబో (UIU ర)","సినదోషి (IIUI సల) – మొదటి అర్ధభాగంలో 4 ఇంద్రగణాలు; యతి: బా – పా (1వ, 3వ గణం మొదటి అక్షరాలు) – సీస పద్యపాదం","2) ఒకచోట (IIUI సల)","నీహార (UUI త)","నికరంపు (IIUI సల)","రాలపై (UIU ర) || బవళించు (IIUI సల)","రణమురే (IIIU నగ)","బవలు (III న)","సలిపి (III న) – 6 ఇంద్ర + 2 సూర్య గణాలు; యతి: ఒ–ని (ప్రాసయతి/సరళయతి), బ–బ – సీస పద్యపాదం","ప్రాజెక్టు: నెల్లూరు జిల్లా సమరయోధులు – పొట్టి శ్రీరాములు (ఆంధ్ర రాష్ట్రం కోసం 58 రోజుల నిరాహార దీక్ష, 1952), వెన్నెలకంటి రాఘవయ్య, బెజవాడ గోపాలరెడ్డి మొదలైనవారి వివరాలు (పేరు, ఊరు, ఉద్యమం, సేవ) సేకరించి నివేదిక రాయండి"]]]},{"id":"te6","no":6,"t":"చేజారిన బాల్యం","m":[8],"ty":"వ్యాసం (ఆత్మకథాత్మక)","th":"బాల్యం – వ్యక్తిత్వ వికాసం","by":"శీలా వీర్రాజు","sum":"రచయిత శీలా వీర్రాజు తన బాల్యాన్ని ప్రేమగా గుర్తుచేసుకుంటాడు. రాజమండ్రిలో చితికిపోయిన మధ్యతరగతి కుటుంబంలో పెరిగాడు. \"నువ్వింకా చిన్నపిల్లవాడివా\" అని నాన్న కోప్పడినప్పుడే బాల్యం దాటిపోయిందని గ్రహించాడు. రామ్మూర్తి మాస్టారి ప్రయివేటులో పలకపై విమానం, ఇల్లు, కిరసనాయిలు దీపం బొమ్మలు వేసి ఫస్టు మార్కు పొందడం చిత్రకళకు పునాది అయింది. పెద్దమ్మ అక్క గదిలోని బొమ్మలు కళాఖండాల సేకరణ అభిరుచికి, రంగుటద్దాల కిటికీ గది, గోదావరి, పడవలు, రంగుల ఆకాశం చిత్రకళాసక్తికి దోహదం చేశాయి. మిత్రులు ప్రకాశరావు, అప్పారావులతో కలిసి నడిపిన చేతివ్రాత పత్రిక సాహిత్యాభిరుచికి తొలిమెట్టు. 14వ ఏట రాజమండ్రి ఆర్ట్ ఎగ్జిబిషన్‌లో డా. గరికపాటి రాజారావు చేతుల మీదుగా తొలి బహుమతి అందుకున్నాడు. అభిరుచులు, విశ్వాసాలు, వ్యక్తిత్వం అన్నిటికీ బాల్యంలోనే పునాదులు పడతాయని, బాల్య స్నేహాలు నిష్కల్మషమైనవని, కనీసం బాల్యంలోని ఆ మనసైనా మళ్ళీ వస్తే బాగుండునని రచయిత కోరుకుంటాడు.","pts":["రచయిత: శీలా వీర్రాజు (\"శీలావీ\") – రాజమండ్రి; తల్లిదండ్రులు వీరభద్రమ్మ, సూర్యనారాయణ; రచయిత, చిత్రకారుడు; మరణం 01.06.2022.","రచనలు: సమాధి, మబ్బుతెరలు, రంగుటద్దాలు, మనసులో కుంచె (కథా సంపుటాలు); కొడిగట్టిన సూర్యుడు, కిటికీకన్ను (కవితలు); మైనా, కరుణించని దేవత, వెలుగురేఖలు (నవలలు). 1969లో \"మైనా\" నవలకు ఆంధ్రప్రదేశ్ సాహిత్య అకాడమీ పురస్కారం.","పాఠం \"కలానికి ఇటూ అటూ\" వ్యాస సంపుటి నుండి.","ప్రక్రియ: వ్యాసం – ఇందులో అనుభవాలకు సంబంధించిన ఆత్మకథాత్మక వ్యాసాలు కూడా ఉంటాయి.","చిత్రకళకు బీజం: రామ్మూర్తి మాస్టారి ప్రయివేటులో పలకపై బొమ్మలు; దామెర్ల రామారావు ఆర్ట్ గేలరీ పోటీలు.","కళాఖండాల సేకరణ అభిరుచి: పెద్దమ్మ అక్క గది నిండా బొమ్మలు.","సాహిత్యాభిరుచి: ప్రకాశరావు, అప్పారావులతో చేతివ్రాత పత్రిక – రామకృష్ణా మిషన్ రీడింగ్ రూంలో పెట్టేవారు.","తొలి బహుమతి: 14వ ఏట, డా. గరికపాటి రాజారావు చేతుల మీదుగా.","సందేశం: వ్యక్తిత్వానికి బాల్యంలోనే మూలబీజాలు; బాల్య స్నేహం స్నేహం కోసమే."],"w":[["నిష్కల్మషం","కల్మషం (మాలిన్యం) లేని, స్వచ్ఛమైన"],["బీజం","విత్తనం, మూలం"],["ఉత్తరోత్తరా","రాను రాను, ముందు ముందు"],["అబ్దం","సంవత్సరం"],["డెందము","హృదయం"],["వృష్టి","వర్షం"],["ఆకాంక్ష","కోరిక"],["వైధవ్యం","భర్త మరణించిన స్థితి"],["దస్తూరీ","చేతిరాత"],["సాహచర్యం","కలిసి ఉండటం"],["పునాదులు","మూలాలు, ఆధారం"],["మారం","మొండిపట్టు"],["దోహదం","సహాయం, తోడ్పాటు"],["సన్నిహితం","దగ్గరితనం"],["వానాకాలపు చదువు","అరకొర చదువు"]],"gr":{"t":"భాషాంశాలు","p":["ప్రత్యక్ష అనుకృతి: ఇతరుల మాటను ఉన్నది ఉన్నట్లు చెప్పడం – \"నేను రాను\" అని రవి రాజుతో అన్నాడు.","పరోక్ష అనుకృతి: విషయాన్ని/అభిప్రాయాన్ని మాత్రమే చెప్పడం – తాను రానని రవి రాజుతో అన్నాడు. \"అని\" = అనుకారకం (కొన్నిసార్లు లోపిస్తుంది).","ప్రత్యక్షం → పరోక్షం: నేను → తాను, నువ్వు → తాను/అతడు; ఉద్ధరణ చిహ్నాలు పోతాయి; \"అని\" ముందు అక్షరంతో కలుస్తుంది (రాను + అని = రానని).","యణాదేశ సంధి: ప్రతి + ఏకత = ప్రత్యేకత; లులనల సంధి: దీపము + లు = దీపాలు, పుస్తకము + లు = పుస్తకాలు."]},"qa":[["వీర్రాజుకు బాల్యం ఎప్పుడు గుర్తొస్తుంది?","రైలు ప్రయాణంలో, సాయంత్రం వర్షం పడుతుంటే కిటికీలోంచి వీధి చూస్తున్నప్పుడు, పుట్టినరోజు నాడు."],["రామ్మూర్తి మాస్టారు ఎవరు?","వెనకవీధిలో ఒక రూపాయి ఫీజుతో ప్రయివేటు చెప్పే ముసలాయన; పెద్దబాలశిక్ష, శతక పద్యాలు, ఎక్కాలు, పంచతంత్ర కథలు నేర్పేవారు."],["మాస్టారు బొమ్మలు వేయమన్నప్పుడు వేసినవి?","విమానం, ఇల్లు, కిరసనాయిలు బుడ్డి దీపం బొమ్మలు."],["కళాఖండాల సేకరణ అభిరుచి ఎలా కలిగింది?","పెద్దమ్మ అక్క గది నిండా ఉన్న రకరకాల బొమ్మలను కిటికీలోంచి చూసి ఆశ్చర్యపడటం వల్ల."],["వీధిలో కిరసనాయిలు దీపాలు ఎందుకు?","ఆ రోజుల్లో పెద్ద రోడ్లలో మాత్రమే కరెంటు దీపాలు ఉండేవి; మిగతా వీధుల్లో కిరసనాయిలు దీపాలే."],["వీర్రాజు చదువుకునే గది ఎలాంటిది?","వీధివైపు, ఆకుపచ్చ–ఎర్ర రంగు అద్దాల రెక్కల కిటికీలున్న గది; ఎండ పడితే రంగులు గదినిండా పరుచుకునేవి."],["బాల్య మిత్రులను ఎందుకు వదులుకోలేము?","బాల్య స్నేహం స్వార్థం లేనిది, నిష్కల్మషమైనది; లోపాలను తేలిగ్గా క్షమించుకుంటాం."]],"act":"మీ బాల్యంలో మీకు నచ్చిన ఒక సంఘటన (మొదటి బహుమతి, మొదటి బొమ్మ, స్నేహితుడు) గురించి ఒక పేజీ ఆత్మకథాత్మక వ్యాసం రాయండి; తరగతిలో చేతివ్రాత పత్రిక ప్రారంభించండి.","kn":"చిందు భాగవతం – యక్షగాన నృత్య నాటక కళ; ప్రదర్శనలో ఎల్లమ్మ ఆట తప్పనిసరి. జగ్గన్నతోట ప్రభల తీర్థం – కోనసీమ, కనుమ రోజు; 90 గ్రామాల ప్రభలు, కౌశిక నది దాటిస్తారు.","qz":[["\"చేజారిన బాల్యం\" రచయిత?","శీలా వీర్రాజు","వాసిరెడ్డి సీతాదేవి","మూలింటి చంద్రకళ","కొడవటిగంటి కుటుంబరావు"],["శీలా వీర్రాజు జన్మస్థలం?","రాజమండ్రి","పిఠాపురం","చేబ్రోలు","నెల్లూరు"],["ఈ పాఠం ఏ గ్రంథం నుండి?","కలానికి ఇటూ అటూ","ఖండ కావ్యములు","మట్టి మనిషి","మా నాన్నగారు"],["శీలా వీర్రాజుకు సాహిత్య అకాడమీ పురస్కారం తెచ్చిన నవల?","మైనా","మట్టి మనిషి","వెలుగురేఖలు","కరుణించని దేవత"],["వీర్రాజుకు ప్రయివేటు చెప్పిన మాస్టారు?","రామ్మూర్తి గారు","ప్రకాశరావు","అప్పారావు","గరికపాటి రాజారావు"],["చేతివ్రాత పత్రికను అందంగా రాసే పని ఎవరిది?","అప్పారావు","ప్రకాశరావు","వీర్రాజు","రామ్మూర్తి"],["చేతివ్రాత పత్రికను ఎక్కడ పెట్టేవారు?","రామకృష్ణా మిషన్ రీడింగ్ రూం","పాఠశాల గ్రంథాలయం","దేవాలయం","పోస్టాఫీసు"],["వీర్రాజు తొలి బహుమతి ఎవరి చేతుల మీదుగా?","డా. గరికపాటి రాజారావు","దామెర్ల రామారావు","రామ్మూర్తి మాస్టారు","అతని నాన్న"],["తొలి బహుమతి అందుకున్నప్పుడు వయస్సు?","14 సంవత్సరాలు","10","18","21"],["వీర్రాజు పేటలో 95% కుటుంబాలు?","చేనేత కుటుంబాలు","రైతు కుటుంబాలు","మత్స్యకారులు","వ్యాపారులు"],["వీర్రాజు ఊరి పక్కన ప్రవహించే నది?","గోదావరి","కృష్ణా","పెన్నా","తుంగభద్ర"],["ఈ పాఠం ప్రక్రియ?","వ్యాసం (ఆత్మకథాత్మక)","ఖండకావ్యం","శతకం","కథానిక"],["\"నేను రాను\" అని రవి అన్నాడు – ఇది?","ప్రత్యక్ష అనుకృతి","పరోక్ష అనుకృతి","కర్మణి వాక్యం","సంయుక్త వాక్యం"],["అనుకృతి వాక్యాల్లో \"అని\" ని ఏమంటారు?","అనుకారకం","అవ్యయం","విభక్తి","క్రియ"],["ప్రతి + ఏకత = ప్రత్యేకత – సంధి?","యణాదేశ సంధి","గుణ సంధి","సవర్ణదీర్ఘ","వృద్ధి సంధి"],["\"ఈవాస్ డ్రీమ్\" కథ రాసిన బాలిక?","అన్నా ఫ్రాంక్","శాంతా సుందరి","హెలెన్ కెల్లర్","మలాలా"]],"wb":{"mis":"పరోక్ష అనుకృతిలో \"నేను\" → \"తాను\" అవుతుంది, ఉద్ధరణ చిహ్నాలు ఉండవు. లులనల సంధిలో \"ము\" లోపించి ముందు అచ్చు దీర్ఘమవుతుంది (దీపము + లు = దీపాలు).","qz":[["ప్రత్యేకత విడదీస్తే?","ప్రతి + ఏకత (యణాదేశ సంధి)","ప్రత్య + ఏకత","ప్రతి + యేకత","ప్రత్యే + కత"],["దశాబ్దం విడదీస్తే?","దశ + అబ్దం (సవర్ణదీర్ఘ సంధి)","దశా + బ్దం","దశ + ఆబ్దం","దశి + అబ్దం"],["ఎప్పుడైన విడదీస్తే?","ఎప్పుడు + ఐన (ఉకార సంధి)","ఎప్పుడై + న","ఎప్పు + డైన","ఎప్పుడ + ఐన"],["తల్లి + తండ్రి = ?","తల్లిదండ్రి (గసడదవాదేశ సంధి)","తల్లితండ్రి","తల్లండ్రి","తల్లీతండ్రి"],["పుస్తకము + లు = ?","పుస్తకాలు (లులనల సంధి)","పుస్తకములు మాత్రమే","పుస్తకలు","పుస్తకోలు"],["\"సాహిత్యాభిరుచి\" సమాసం?","సప్తమీ తత్పురుష (సాహిత్యము నందు అభిరుచి)","ద్వంద్వ","ద్విగు","బహువ్రీహి"],["\"నాలుగుదిక్కులు\" సమాసం?","ద్విగు సమాసం","ద్వంద్వ","అవ్యయీభావ","రూపక"],["\"శక్తియు సామర్థ్యమును\" – సమాస పదం?","శక్తిసామర్థ్యాలు (ద్వంద్వ)","శక్తిమంతుడు","సామర్థ్యశక్తి (ద్విగు)","శక్తిలేనిది"],["చిత్రం – వికృతి?","చిత్తరువు","తంతు","కండ","ఆసత్తి"],["\"చేయి తిరిగిన రచయిత\" – జాతీయం అర్థం?","నైపుణ్యం సాధించిన","చేయి విరిగిన","కొత్తగా రాసే","రాయలేని"]],"pg":"65–74","f":"books/10/Class10_Telugu_Textbook_Sem1.pdf","p":73,"lb":"పాఠ్యపుస్తకం","ws":["అవగాహన – ప్రతిస్పందన: అ) ప్రశ్నలు, ఆ) అపరిచిత గద్యం (పుట 69)","ఇ) అపరిచిత గద్యం, ఈ) అర్థసందర్భాలు, ఉ) ఏకవాక్య సమాధానాలు (పుట 70)","వ్యక్తీకరణ – సృజనాత్మకత; పదజాలం (పుట 71)","ఈ) జాతీయాలు; వ్యాకరణం: సంధులు, సమాసాలు (పుట 72)","ఈ) సమాస పదాలు, ఉ) ప్రత్యక్ష–పరోక్ష అనుకృతి, ప్రాజెక్టు (పుట 73)"]},"tg":[["అవగాహన – ప్రతిస్పందన: అ) ప్రశ్నలు, ఆ) అపరిచిత గద్యం (పుట 69)",["అ) 1) రైలు ప్రయాణం చేస్తున్నప్పుడు, సాయంత్రం వర్షం పడుతుంటే బయటకు వెళ్ళలేక గదిలో కూర్చుని కిటికీలోంచి వెనకవీధి చూస్తున్నప్పుడు, పుట్టినరోజు నాడు బాల్యం గుర్తొస్తుంది","2) రామ్మూర్తి గారు వీర్రాజు ఇంటి వెనకవీధిలో ఉండే ముసలాయన; ఒక రూపాయి ఫీజుతో సుమారు 20 మంది పిల్లలకు ప్రయివేటు చెప్పేవారు. బడి పాఠాలే కాక పెద్దబాలశిక్ష చదివించి, నీతి శతక పద్యాలు బట్టీ పట్టించి, ఎక్కాలు వల్లెవేయించి, పంచతంత్ర కథలు చెప్పేవారు; బొమ్మలు వేయించి ప్రోత్సహించేవారు","3) విమానం బొమ్మ, ఇల్లు బొమ్మ, కిరసనాయిలు బుడ్డి దీపం బొమ్మ","4) పెద్దమ్మ అక్క గదినిండా ప్లాస్టిక్, చెక్క, గాజు, పింగాణీ బొమ్మలు ఉండేవి; పిల్లలను లోపలికి రానిచ్చేది కాదు; కిటికీలోంచి, తలుపు సందులోంచి చూసి ఆశ్చర్యపడేవారు – ఆ ఆసక్తే కళాఖండాల సేకరణ అభిరుచికి కారణం","ఆ) 1) జర్నలిస్టు/రచయిత కావాలి; అందరికీ ఉపయోగపడాలి; చనిపోయాక కూడా తన రచనల ద్వారా బతకాలి 2) \"ఈవాస్ డ్రీమ్\" (Eva's Dream) 3) చాలామందిలా వృథాగా బతకకుండా, అందరికీ ఉపయోగపడుతూ, చావు తర్వాత కూడా బతికేలా (రచనల ద్వారా) జీవించాలని 4) ఉదా: అన్నా ఫ్రాంక్ రాసేటప్పుడు ఆమెకు ఏమి కలుగుతుంది? (విచారం పోయి ధైర్యం వస్తుంది)"]],["ఇ) అపరిచిత గద్యం, ఈ) అర్థసందర్భాలు, ఉ) ఏకవాక్య సమాధానాలు (పుట 70)",["ఇ) 1) తండ్రి (కొడవటిగంటి కుటుంబరావు) కలం, కాగితాలు పట్టుకుని ఎప్పుడూ రాసుకుంటూ ఉండటం 2) రాత్రుళ్ళు ఆకాశంలో నక్షత్రాలు, గ్రహాలు చూపించి పేర్లు చెప్పేవారు; సూర్య, చంద్ర గ్రహణాలు ఎలా ఏర్పడతాయో వివరించేవారు 3) ఎవరి మీదా మన అభిప్రాయాన్ని బలవంతంగా రుద్దకూడదు – రుద్దితే పిల్లల వ్యక్తిత్వం సమగ్రతను సాధించదు 4) ఉదా: శాంతా సుందరి తండ్రి ఇంట్లో ఏమి తయారు చేశారు? (చిన్న టెలిస్కోపు)","ఈ) 1) \"మాటిమాటికీ మారాం చేయడానికి నువ్వింకా చిన్నపిల్లాడివేననుకుంటున్నావా\" – శీలా వీర్రాజు రాసిన \"చేజారిన బాల్యం\" (కలానికి ఇటూ అటూ) పాఠంలోనిది. సందర్భం: రచయిత మారం చేసినప్పుడు తండ్రి కోప్పడి అన్న మాట – అప్పుడే తాను బాల్యం దాటిపోయానని రచయితకు అర్థమైంది","2) \"ఎంత అమాయకమైన రోజులవి\" – చేజారిన బాల్యం, శీలా వీర్రాజు. సందర్భం: ఆటపాటల్లో, ఏ చీకూచింతా లేకుండా హాయిగా గడిచిన బాల్యాన్ని గుర్తుచేసుకుంటూ రచయిత అన్న మాట","ఉ) 1) శీలా వీర్రాజు వ్యాస సంపుటి \"కలానికి ఇటూ అటూ\" 2) డాక్టర్ గరికపాటి రాజారావు గారి చేతుల మీదుగా 3) బాల్యమిత్రులు ప్రకాశరావు, అప్పారావు"]],["వ్యక్తీకరణ – సృజనాత్మకత; పదజాలం (పుట 71)",["అ) 1) వీర్రాజు పెద్దమ్మ అక్కకు చిన్నప్పుడే వైధవ్యం వచ్చి వారి ఇంట్లోనే ఉండేది. ఆమె గదినిండా ప్లాస్టిక్, చెక్క, గాజు, పింగాణీ బొమ్మలు అరడుగు ఖాళీ లేకుండా ఉండేవి. పిల్లలను లోపలికి రానివ్వకపోవడంతో కిటికీలోంచి చూసి ఆశ్చర్యపడేవారు. ఆ ఆసక్తే తర్వాత కళాఖండాల సేకరణ అభిరుచిగా మారింది","2) రామ్మూర్తి మాస్టారు బొమ్మలు వేయమన్నప్పుడు పలకపై విమానం, ఇల్లు, బుడ్డి దీపం వేసి ఫస్టు మార్కు, ప్రశంస పొందాడు. ఆ ఉత్సాహంతో పుస్తకాల్లోని బొమ్మలు కాపీ చేశాడు; పలక నుండి కాగితం–పెన్సిల్‌కు, తర్వాత వాటర్ కలర్స్‌కు ఎదిగాడు. రంగుటద్దాల కిటికీ, గోదావరి, పడవలు, రంగుల ఆకాశం, చెట్లు చిత్రకళాసక్తి పెంచాయి. దామెర్ల రామారావు ఆర్ట్ గేలరీ పోటీల్లో పాల్గొన్నాడు","3) ప్రకాశరావు, అప్పారావు, వీర్రాజు కలిసి నెలనెలా పిల్లల చేతివ్రాత పత్రిక తెచ్చారు. చందమామ, బాల, పాపాయి పత్రికల రచనలు మార్చి కొత్తవి తయారు చేయడం ప్రకాశరావు, వీర్రాజుల పని; ముత్యాల్లాంటి దస్తూరీ గల అప్పారావు చందమామ సైజు కాగితాలపై రాసేవాడు. వీర్రాజు బొమ్మలు, అట్టమీద రంగుబొమ్మ వేసేవాడు. పుస్తకంగా కుట్టి రామకృష్ణా మిషన్ రీడింగ్ రూంలో పెట్టేవారు; ఐదారు సంచికలు వచ్చాయి","ఆ) 1) రచయిత ఊరు విడిచి 36 ఏళ్ళయింది; బాల్యం అంటే అతనికి చాలా ఇష్టం. రైలు ప్రయాణంలో, వర్షం పడే సాయంత్రాల్లో, పుట్టినరోజున బాల్యం గుర్తొస్తుంది. ఆటపాటలతో, చీకూచింతా లేకుండా గడిచిన అమాయకమైన రోజులవి. నాన్న కోప్పడినప్పుడు బాల్యం దాటిందని గ్రహించాడు. రామ్మూర్తి మాస్టారి ప్రయివేటు, పలకపై బొమ్మలు, పెద్దమ్మ అక్క బొమ్మల గది, రంగుటద్దాల కిటికీ, గోదావరి, చేతివ్రాత పత్రిక, 14వ ఏట తొలి బహుమతి – అన్నీ గుర్తుచేసుకున్నాడు. బాల్య మిత్రులతో స్నేహం నేటికీ నిష్కల్మషంగా ఉంది. బాల్యం తిరిగి రాదు గనుక కనీసం ఆ మనసైనా రావాలని కోరుకున్నాడు","2) చేతివ్రాత పత్రిక కోసం చందమామ, బాల, పాపాయి పత్రికలు చదివాడు; \"పిచ్చిపుల్లయ్య\" కొట్టులో అర్ధణాకు, అణాకు పాత పిల్లల పత్రికలు కొని చదివాడు. ఇంట్లో పుస్తకాలు, పత్రికలు కొనే అలవాటు లేకపోయినా ప్రకాశరావు దగ్గర పుస్తకాలు తెచ్చుకుని, లైబ్రరీకి వెళ్ళి చదివేవాడు. ఆ చదివే గుణమే రాసే అభిరుచిగా మారి కథలు, కవితలు, నవలలు రాసే స్థాయికి ఎదిగించింది; \"మైనా\" నవలకు సాహిత్య అకాడమీ పురస్కారం వచ్చింది","3) వీర్రాజు చిత్రకారుడు, రచయిత – రెండు రంగాల్లోనూ సృజనాత్మకత చూపాడు. చిన్నప్పుడు చూసిన విమానాలు, వీధిదీపం ఆధారంగా బొమ్మలు వేశాడు; ప్రకృతి దృశ్యాలను మనసులో నిలుపుకున్నాడు; 14వ ఏటే ప్రథమ బహుమతి పొందాడు. పత్రికల రచనలను మార్చి కొత్త రచనలు చేశాడు. కథలు (సమాధి, రంగుటద్దాలు), కవితలు (కొడిగట్టిన సూర్యుడు), నవలలు (మైనా) రాశాడు. కళాఖండాలు సేకరించాడు. పరిశీలన, ఊహ, సాధన కలిసి అతని సృజనాత్మక శక్తిని పెంచాయి","ఇ) 1) నమూనా: నా అభిరుచులు – బొమ్మలు వేయడం, కథల పుస్తకాలు చదవడం, కబడ్డీ. మా తెలుగు ఉపాధ్యాయులు పద్యాలు చెప్పి ప్రోత్సహించారు; మా అమ్మ పాత క్యాలెండర్ల వెనుక బొమ్మలు వేయనిచ్చింది; మా నాన్న గ్రంథాలయ సభ్యత్వం ఇప్పించారు. వారి ప్రోత్సాహంతోనే మండల స్థాయి చిత్రలేఖన పోటీలో బహుమతి పొందాను","2) వ్యాసం: \"గూడూరులో ఆకట్టుకున్న చిత్రకళా ప్రదర్శన\" – జిల్లా విద్యాశాఖ ఆధ్వర్యంలో జరిగిన ప్రదర్శనలో 200 చిత్రాలు ఉన్నాయి. పల్లె జీవితం, రైతులు, పక్షులు, స్వాతంత్ర్య సమరయోధుల చిత్రాలు ఆకట్టుకున్నాయి. నీటిరంగులు, పెన్సిల్ స్కెచ్‌లు, ఆయిల్ పెయింటింగ్‌లు ఉన్నాయి. విద్యార్థుల చిత్రాలు కూడా ప్రదర్శించారు. ఇలాంటి ప్రదర్శనలు పిల్లల్లో కళాభిరుచి పెంచుతాయి","పదజాలం అ) 1) నిష్కల్మషం = స్వచ్ఛం, మాలిన్యం లేనిది – పిల్లల మనసు నిష్కల్మషంగా ఉంటుంది 2) బీజం = విత్తనం, మూలం – క్రమశిక్షణకు బీజం ఇంట్లోనే పడుతుంది 3) ఉత్తరోత్తరా = రాను రాను – సాధనతో ఉత్తరోత్తరా నైపుణ్యం పెరుగుతుంది","ఆ) 1) ఏడాది = అబ్దం, సంవత్సరం 2) హృదయం = డెందము, ఎద 3) వర్షం = వాన, వృష్టి 4) ఈప్సితము = కోరిక, ఆకాంక్ష","ఇ) 1) ఆసక్తి – ఆసత్తి 2) తంత్రం – తంతు 3) చిత్రం – చిత్తరువు 4) ఖండం – కండ (గండ్ర)"]],["ఈ) జాతీయాలు; వ్యాకరణం: సంధులు, సమాసాలు (పుట 72)",["ఈ) 1) చేయి తిరిగిన – బాగా నైపుణ్యం సాధించిన; అతడు అనుభవంతో నైపుణ్యం సాధించిన రచయిత 2) చేజారిపోవు – అవకాశం/కాలం దక్కకుండా పోవు; జీవితాన్ని వృథా కానీయకూడదు 3) చీకుచింతా లేని – ఏ బాధలు, ఆందోళనలు లేని 4) మూలబీజాలు – మూలాలు, పునాదులు; ఉన్నత జీవితానికి పునాదులు బాల్యంలోనే పడాలి","అ) 1) ప్రత్యేకత = ప్రతి + ఏకత (యణాదేశ సంధి) 2) దీపాలు = దీపము + లు (లులనల సంధి) 3) ఎప్పుడైన = ఎప్పుడు + ఐన (ఉకార సంధి) 4) దశాబ్దం = దశ + అబ్దం (సవర్ణదీర్ఘ సంధి)","ఆ) 1) తల్లి + తండ్రి = తల్లిదండ్రి (గసడదవాదేశ సంధి) 2) ఇన్ని + ఏళ్ళు = ఇన్నేళ్ళు (ఇకార సంధి) 3) పుస్తకము + లు = పుస్తకాలు (లులనల సంధి) 4) చిన్న + అప్పుడు = చిన్నప్పుడు (అకార సంధి) 5) సాహిత్య + అభిమానం = సాహిత్యాభిమానం (సవర్ణదీర్ఘ సంధి)","ఇ) 1) సాహిత్యాభిరుచి – సాహిత్యము నందు అభిరుచి (సప్తమీ తత్పురుష) 2) చేతిరాత – చేతితో రాత (తృతీయా తత్పురుష) 3) నిష్కల్మషము – కల్మషము లేనిది (నఞ్ తత్పురుష) 4) నాలుగుదిక్కులు – నాలుగు సంఖ్య గల దిక్కులు (ద్విగు సమాసం)"]],["ఈ) సమాస పదాలు, ఉ) ప్రత్యక్ష–పరోక్ష అనుకృతి, ప్రాజెక్టు (పుట 73)",["ఈ) 1) చిన్నదైన పిల్ల – చిన్నపిల్ల (విశేషణ పూర్వపద కర్మధారయ) 2) బద్ధం కానిది – అబద్ధం (నఞ్ తత్పురుష) 3) శక్తియు సామర్థ్యమును – శక్తిసామర్థ్యాలు (ద్వంద్వ) 4) మాయకము కానిది – అమాయకము (నఞ్ తత్పురుష) 5) బాల్యము నందలి మిత్రులు – బాల్యమిత్రులు (సప్తమీ తత్పురుష)","ఉ) ప్రత్యక్ష → పరోక్ష ఉదాహరణలు: \"నేను బొమ్మలు బాగా వేస్తాను\" అని వీర్రాజు అన్నాడు → తాను బొమ్మలు బాగా వేస్తానని వీర్రాజు అన్నాడు; \"చేతివ్రాత పత్రిక తెద్దాం\" అని మిత్రులు అన్నారు → చేతివ్రాత పత్రిక తెద్దామని మిత్రులు అన్నారు","ప్రాజెక్టు: ఉదా – \"ఒక విజేత ఆత్మకథ\" (ఎ.పి.జె. అబ్దుల్ కలాం): రామేశ్వరంలో పేపర్లు పంచడం, తండ్రి నుండి నిజాయితీ, తల్లి నుండి మంచితనం; \"సత్యశోధన\" (గాంధీ): హరిశ్చంద్ర నాటకం ప్రభావం, తప్పు ఒప్పుకున్న సంఘటన; అన్నా ఫ్రాంక్ డైరీ – బాల్య ఘట్టాలు సేకరించి పట్టికగా ప్రదర్శించండి"]]]},{"id":"te7","no":7,"t":"ప్రకృతి సందేశం","m":[9],"ty":"గేయకవిత","th":"ప్రకృతి – ఐకమత్యం, సమత","by":"వై.సి.వి. రెడ్డి","sum":"ప్రకృతిలోని ప్రతి దృశ్యం మనిషికి ఒక సందేశం ఇస్తుందని కవి వర్ణిస్తాడు. అద్దాల్లాంటి కొండ సరస్సుల్లో విచ్చిన తామరలు తుమ్మెదలకు, మామిడి చిగుళ్ళు కోకిలలకు ఆనందం పంచుతూ \"పరస్పర సహకారమే మన సంస్కృతి\" అని చెబుతాయి. కొండ శిఖరాలను కౌగిలించే మేఘాలు, చెట్లను అల్లుకునే తీగలు ఐక్యతను బోధిస్తాయి. రామచిలుకలు, లకుముకి పిట్టల జంట అనురాగ సందేశం; నెమళ్ళ నాట్యం, సెలయేళ్ళకు ఆటపాటలు నేర్పే తెమ్మెరలు స్వేచ్ఛ, సమత, మమతల సందేశం ఇస్తాయి. కలసికట్టుగా గింజలు తెచ్చే చీమలు, తేనె పంచే తేనెటీగలు క్రమశిక్షణ, సమష్టి కృషి నేర్పుతాయి. మతాలన్నీ మమత కోసమే పుట్టాయని, కుటిల బుద్ధులు వక్రభాష్యాలతో చిచ్చుపెట్టిన జిత్తులు ఇక సాగనీయమని, కార్మికులు, కర్షకులు సమత కోసం పోరాడి ఈ నేలను శాంతి సౌఖ్యాలతో నింపుతామని కవి ప్రకటిస్తాడు.","pts":["కవి: వై.సి.వి. రెడ్డి (యమ్మనూరు చినవెంకటరెడ్డి) – వైఎస్సార్ (కడప) జిల్లా బోనాల; తల్లిదండ్రులు లక్ష్మమ్మ, కొండారెడ్డి; అభ్యుదయ కవి; మరణం 08.10.1989.","రచనలు: తొలకరి చినుకులు, మేనక, రంభ, సింధూర రేఖ, దక్షిణానిలము, వైజయంతి, పారిజాతం (కావ్యాలు); \"గట్టిగింజలు\" (కథల సంపుటి). పాఠం వీరి సమగ్ర సాహిత్యం నుండి.","ప్రక్రియ: గేయకవిత – పాడడానికి, లయబద్ధంగా చదవడానికి వీలైనది; శబ్ద లయ; మాత్రాగణాలు; గానయోగ్యం.","సహకారం: తామరలు–తుమ్మెదలు, మామిడి చిగుళ్ళు–కోకిలలు.","ఐక్యత: మేఘాలు–కొండశిఖరాలు, తీగలు–చెట్లు.","అనురాగం: రామచిలుకలు, లకుముకి పిట్టల జంట; స్వేచ్ఛ–సమత–మమత: నెమళ్ళు, సెలయేళ్ళు, తెమ్మెరలు.","క్రమశిక్షణ: చీమలు, తేనెటీగలు.","సందేశం: మతాలు మమత కోసమే; కార్మికులు, కర్షకులు సమత కోసం పోరాటం – శాంతి సౌఖ్యాలు.","జూలై 28 – ప్రపంచ ప్రకృతి పరిరక్షణ దినం."],"w":[["ముకురం","అద్దం"],["పికము","కోకిల"],["నెమ్మి","నెమలి"],["సరోవరం","సరస్సు"],["నెత్తావి","మంచి సువాసన"],["దరి","గుహ, లోయ"],["కందరం","గుహ"],["సహకారం","మామిడి చెట్టు / సహాయం"],["మంజరి","పూల గుత్తి, చిగురు"],["వలరాజు","మన్మథుడు"],["తేజీలు","గుర్రాలు (ఇక్కడ వాహనాలు – చిలుకలు)"],["జరఠ","ముదిరిన, పండిన"],["తెమ్మెర","చిరుగాలి"],["కర్షకులు","రైతులు"],["సాకూతముల్","అభిప్రాయాలు, భావాలు"]],"gr":{"t":"భాషాంశాలు","p":["పడ్వాది సంధి: పడు, పాటు, పెట్టు, పట్టు, పరచు మొదలైనవి పరమైనప్పుడు \"ము\" వర్ణానికి లోపం, పూర్ణబిందువు విభాషగా వస్తాయి – భయము + పడు = భయపడు / భయంపడు / భయముపడు.","బహువ్రీహి సమాసం: అన్యపదార్థ ప్రాధాన్యం – ముక్కంటి (మూడు కన్నులు కలవాడు), చక్రపాణి (చక్రము పాణియందు కలవాడు), ఆజానుబాహుడు, పద్మాక్షి.","స్వభావోక్తి అలంకారం: జాతి, గుణ, క్రియల చేత స్వభావాన్ని ఉన్నది ఉన్నట్లు రమణీయంగా వర్ణించడం – \"గుసగుసలతో కొమ్మకొమ్మపై నివసించి ముక్కులానించు లకుముకిపిట్ట దంపతులు\".","గేయం మాత్రాగణాల్లో ఉంటుంది (పద్యం లాగా వృత్త గణాల్లో కాదు)."]},"qa":[["మానవుడికి సందేశమిచ్చినవి ఏవి?","తామరలు, తుమ్మెదలు, మామిడి, కోకిల, మేఘాలు, తీగలు, చిలుకలు, లకుముకి పిట్టలు, నెమళ్ళు, సెలయేళ్ళు, తెమ్మెరలు, చీమలు, తేనెటీగలు, పూల పరిమళం, పక్షులు."],["గిరిదరీ సరోవరాలను కవి దేనితో పోల్చాడు?","ముకురం (అద్దం) తో – అద్దాల వంటి నిర్మలమైన సరస్సులు."],["ఐక్యతను చెప్పేవి ఏవి?","కొండశిఖరాలను కౌగిలించే మేఘమాలికలు, చెట్లను అల్లుకునే పూలతీగలు."],["చీమల నుండి ఏం నేర్చుకోవాలి?","కష్టనష్టాలకు ఓర్చి కలసికట్టుగా, క్రమశిక్షణతో పనిచేయడం."],["మతాలన్నీ ఏమి బోధిస్తున్నాయి?","అందరికీ అనురాగం, మమత పంచడం."],["సమత మమతలు అనగా?","సమత = అందరూ సమానం అనే భావం; మమత = ప్రేమ, ఆప్యాయత."]],"act":"గేయాన్ని రాగయుక్తంగా బృందగానం చేయండి; మీ బడి ఆవరణలో \"ఒక విద్యార్థి – ఒక మొక్క\" కార్యక్రమం చేపట్టి మొక్కల సంరక్షణ పట్టిక నిర్వహించండి.","kn":"పేరిణి శివతాండవం – కాకతీయుల కాలపు యోధుల నృత్యం; రామప్ప శిల్పాల ఆధారంగా నటరాజ రామకృష్ణ పునరుద్ధరించారు. మొలకల పున్నమి – కదిరి, వేంపల్లి ప్రాంతాల రైతుల పండుగ (చిన్నమ్మ దేవత).","qz":[["\"ప్రకృతి సందేశం\" కవి?","వై.సి.వి. రెడ్డి","గుర్రం జాషువా","ఉమర్ ఆలీషా","శీలా వీర్రాజు"],["వై.సి.వి. రెడ్డి పూర్తి పేరు?","యమ్మనూరు చినవెంకటరెడ్డి","యర్రంరెడ్డి చిన్నవెంకటరెడ్డి","యలమంచి చంద్రవెంకటరెడ్డి","యనమల చినవీరారెడ్డి"],["ఈ పాఠం ప్రక్రియ?","గేయకవిత","శతకం","ఖండకావ్యం","వ్యాసం"],["వై.సి.వి. రెడ్డి కథల సంపుటి?","గట్టిగింజలు","మట్టి మనిషి","రంగుటద్దాలు","బతుకు గంప"],["కవి సరస్సులను దేనితో పోల్చాడు?","అద్దం (ముకురం)","ఆకాశం","వెన్నెల","ముత్యం"],["కోకిలకు మామిడి చిగుళ్ళు ఇవ్వడం దేనికి సందేశం?","సహకారం","యుద్ధం","ఒంటరితనం","విశ్రాంతి"],["ఐక్యతను బోధించేవి?","మేఘాలు, తీగలు","చీమలు మాత్రమే","నెమళ్ళు","కోకిలలు"],["క్రమశిక్షణ, సమష్టి కృషి నేర్పేవి?","చీమలు, తేనెటీగలు","చిలుకలు","మేఘాలు","నెమళ్ళు"],["పొరుగువారికి పంచిపోయేవి?","తేనెటీగలు","చీమలు","తుమ్మెదలు","కోకిలలు"],["మతాలన్నీ దేనికోసం పుట్టాయని కవి అన్నాడు?","ఒక్క మమత కోసం","యుద్ధం కోసం","అధికారం కోసం","ధనం కోసం"],["సమత కోసం పోరాడతామని పలికినవారు?","కార్మికులు, కర్షకులు","రాజులు","పండితులు","వ్యాపారులు"],["ప్రపంచ ప్రకృతి పరిరక్షణ దినం?","జూలై 28","జూన్ 5","మార్చి 22","ఏప్రిల్ 22"],["\"ముక్కంటి\" సమాసం?","బహువ్రీహి","ద్విగు","ద్వంద్వ","తత్పురుష"],["భయము + పడు = భయపడు – సంధి?","పడ్వాది సంధి","ప్రాతాది సంధి","లులనల సంధి","గసడదవాదేశ"],["\"లకుముకిపిట్ట దంపతులు\" వర్ణన – అలంకారం?","స్వభావోక్తి","రూపకం","ఉపమ","అతిశయోక్తి"],["\"వృక్షో రక్షతి రక్షితః\" అర్థం?","చెట్లను కాపాడితే అవి మనల్ని కాపాడతాయి","చెట్లు నరకాలి","చెట్లు పూజించాలి","చెట్లు అమ్మాలి"]],"wb":{"mis":"పడ్వాది సంధిలో మూడు రూపాలూ సరైనవే (భయపడు, భయంపడు, భయముపడు) – విభాష. బహువ్రీహిలో సమాసంలోని పదాలకు కాక వేరే వ్యక్తి/వస్తువుకు ప్రాధాన్యం.","qz":[["మతములన్ని విడదీస్తే?","మతములు + అన్ని (ఉకార సంధి)","మతము + లన్ని","మతముల + అన్ని","మత + ములన్ని"],["పూందేనె విడదీస్తే?","పూవు + తేనె (ప్రాతాది సంధి)","పూ + దేనె","పూం + తేనె","పూవు + దేనె"],["కొలువైన విడదీస్తే?","కొలువు + ఐన (ఉకార సంధి)","కొలు + వైన","కొలువ + ఐన","కొలువై + న"],["అవమానము + పెట్టు = ?","అవమానపెట్టు / అవమానంపెట్టు (పడ్వాది)","అవమానుపెట్టు","అవమానాపెట్టు","అవమానెపెట్టు"],["\"గగనకాంత\" సమాసం?","రూపక సమాసం (గగనము అనెడి కాంత)","ద్వంద్వ","ద్విగు","షష్ఠీ తత్పురుష"],["\"సమతామమతలు\" సమాసం?","ద్వంద్వ సమాసం","బహువ్రీహి","ద్విగు","రూపక"],["\"చక్రపాణి\" విగ్రహవాక్యం?","చక్రము పాణియందు కలవాడు (బహువ్రీహి)","చక్రము మరియు పాణి","చక్రము యొక్క పాణి","చక్రమైన పాణి"],["అరుణం – నానార్థాలు?","ఎరుపు, కుష్టువ్యాధి, బంగారం","శాఖ, స్త్రీ, బురుజు","ఆకాశం, శూన్యం","ప్రేమ, నెమలి"],["పికం – వ్యుత్పత్త్యర్థం?","చాటు నుండి కూయునది (కోయిల)","చలనము లేనిది","భూమిని తడుపునది","మరణంతో కూడినది"],["మేఘం – వికృతి?","మొగులు","మేగం","మెగము","మోఘం"]],"pg":"75–85","f":"books/10/Class10_Telugu_Textbook_Sem1.pdf","p":83,"lb":"పాఠ్యపుస్తకం","ws":["అవగాహన – ప్రతిస్పందన: అ) ప్రశ్నలు, ఆ) అపరిచిత గద్యం (పుట 79)","ఇ) వచన కవిత, ఈ) అర్థసందర్భాలు, ఉ) ఏకవాక్య; వ్యక్తీకరణ అ) (పుట 80)","వ్యక్తీకరణ ఆ, ఇ); పదజాలం (పుట 81)","నానార్థాలు, వ్యుత్పత్త్యర్థాలు, ప్రకృతి–వికృతులు; సంధులు (పుట 82)","పడ్వాది సూత్రం; ఆ) సమాసాలు; బహువ్రీహి; ఇ, ఈ) స్వభావోక్తి (పుట 83)","ప్రాజెక్టుపని (పుట 84)"]},"tg":[["అవగాహన – ప్రతిస్పందన: అ) ప్రశ్నలు, ఆ) అపరిచిత గద్యం (పుట 79)",["అ) 1) గేయకవితను ఉపాధ్యాయుని సహాయంతో రాగయుక్తంగా, లయబద్ధంగా పాడండి","2) తామరలు, తుమ్మెదలు, మామిడి చిగుళ్ళు, కోకిలలు, మేఘమాలికలు, పూలతీగలు, రామచిలుకలు, లకుముకి పిట్టల జంట, నెమళ్ళు, సెలయేళ్ళు, తెమ్మెరలు, చీమలు, తేనెటీగలు, అరవిరుల పరిమళం, పక్షులు మానవుడికి సందేశమిచ్చాయి","3) కవి గిరిదరీ సరోవరాలను ముకురం (అద్దం) తో పోల్చాడు – అద్దం లాంటి నిర్మలమైన సరస్సులు","ఆ) 1) \"ప్రకృతిని కనుగొనడం, ప్రకృతి ద్వారా నేర్చుకోవడమంటే మనల్ని మనం కనుగొనడమే\" అన్నారు 2) వాతావరణం, వృక్షజాలం, నదీప్రవాహాలు, ఆకాశాన్ని తాకే పర్వతాలు, లోయలు, జలపాతాలు, సూర్యోదయం, సూర్యాస్తమయం, చీకటి, వెన్నెల 3) \"వృక్షో రక్షతి రక్షితః\" 4) ఉదా: ప్రకృతికి వెన్నెముక ఏవి? (వృక్షాలు)"]],["ఇ) వచన కవిత, ఈ) అర్థసందర్భాలు, ఉ) ఏకవాక్య; వ్యక్తీకరణ అ) (పుట 80)",["ఇ) 1) సెలయేళ్ళు, కడలి కెరటాలు, వర్షాలు, జలపాతాలు 2) సెలయేళ్ళు, తారకలు, పూదోటలు, పిల్లతెమ్మెరలు, కడలి కెరటాలు, నీలిమేఘాలు, వసంతాలు, వర్షాలు, జలపాతాలు, కోనల అందాలు 3) మనిషి కోరికల వల్ల ప్రకృతి వినాశనం జరుగుతోంది 4) ఉదా: ప్రకృతిని రక్షించకపోతే ఏమవుతుంది?","ఈ) 1) \"పొరుగు వారికి పంచిపోవు తేనీగలు\" – కవి: వై.సి.వి. రెడ్డి, \"ప్రకృతి సందేశం\" గేయకవిత. సందర్భం: చీమలు, తేనెటీగలు క్రమశిక్షణ, సమష్టి కృషి నేర్పుతాయని చెప్పే సందర్భం. అర్థం: పువ్వుపువ్వు నుండి తేనె సేకరించి పొరుగువారికి పంచిపెట్టే తేనెటీగలు","2) \"సమతకై పోరాడగా ఈ నేల శాంతి సౌఖ్యము నింపగా\" – వై.సి.వి. రెడ్డి, ప్రకృతి సందేశం. సందర్భం: పక్షులతో పాటు కార్మికులు, కర్షకులు కలిసి పలికిన మాట. అర్థం: సమానత్వం కోసం పోరాడి ఈ నేలను శాంతి సౌఖ్యాలతో నింపుదాం","ఉ) 1) కష్టనష్టాలకు ఓర్చి కలసికట్టుగా, క్రమశిక్షణతో పనిచేయడం 2) రాత్రనక పగలనక కాయకష్టం చేస్తున్నారు 3) అందరికీ అనురాగం, మమత పంచాలని బోధిస్తున్నాయి","అ) 1) కొండ సరస్సుల్లో విచ్చుకున్న తామరలు తుమ్మెదలకు తేనె పంచుతున్నాయి; వసంతంలో మామిడి చెట్లు కోకిలలకు లేత చిగుళ్ళు ఇస్తున్నాయి. తేనెటీగలు సేకరించిన తేనెను పొరుగువారికి పంచుతున్నాయి. ఒకరికొకరు సహకరించుకోవడమే మన సంస్కృతి అని ఇవి సందేశమిస్తున్నాయి","2) కొండల లోయల్లో పుట్టి కొమ్మల్లో, రెమ్మల్లో వ్యాపించిన ఎర్రని కాంతి, అరవిరిసిన పువ్వుల సువాసన కవితలై మానవుల ప్రగతికి చక్కని బాటలు వేశాయి. చీమలు, తేనెటీగల క్రమశిక్షణ, మేఘాలు–తీగల ఐక్యత కూడా ప్రగతికి దారి చూపుతాయి","3) రామచిలుకలు ఆకాశంలో ఎగురుతూ వింతకాంతి నింపుతున్నాయి; లకుముకి పిట్టల జంట గుసగుసలాడుతూ అనురాగంతో జీవిస్తోంది – ప్రేమానురాగాలతో జీవించాలని సందేశం. నీలిమేఘాల కింద ఎగిరే పక్షులు కార్మికులు, కర్షకులతో కలిసి సమత, శాంతి కోసం పిలుపునిస్తున్నాయి"]],["వ్యక్తీకరణ ఆ, ఇ); పదజాలం (పుట 81)",["ఆ) 1) సారాంశం: ప్రకృతిలోని ప్రతిదీ మనిషికి ఒక పాఠం. కొండ సరస్సుల తామరలు, తుమ్మెదలు, మామిడి, కోకిలలు సహకారాన్ని; కొండలను కౌగిలించే మేఘాలు, చెట్లను అల్లుకునే తీగలు ఐక్యతను; చిలుకలు, లకుముకి పిట్టలు అనురాగాన్ని; నెమళ్ళ నాట్యం, సెలయేళ్ళు, తెమ్మెరలు స్వేచ్ఛ, సమత, మమతలను; చీమలు, తేనెటీగలు క్రమశిక్షణను నేర్పుతాయి. పూల పరిమళం కవితగా మానవ గతికి బాట వేస్తుంది. మతాలన్నీ మమత కోసమే పుట్టినా కుటిలబుద్ధులు చిచ్చుపెట్టారు – ఆ జిత్తులు ఇక సాగవు. కార్మికులు, కర్షకులు సమత కోసం పోరాడి నేలను శాంతి సౌఖ్యాలతో నింపుతారని కవి సందేశం","2) మేఘమాలికలు కొండశిఖరాలను ఆలింగనం చేసుకుంటాయి; పూలతీగలు లల్లిబిల్లిగా చెట్లను అల్లుకుంటాయి – కలిసి ఉండాలని అనుశాసనం. చీమలు కష్టనష్టాలకు ఓర్చి కలసికట్టుగా తిండిగింజలు తెస్తాయి; తేనెటీగలు కలిసి తేనె సేకరించి పంచుతాయి – కలసి నడవాలని చెబుతాయి. లకుముకి పిట్టల జంట అన్యోన్యత, మతాల మూలమైన మమత, కార్మికులు–కర్షకులు–పక్షులు కలిసి సమత కోసం పలకడం – ఇవన్నీ ఐకమత్యమే బలమని బోధిస్తాయి","ఇ) 1) ప్రసంగ వ్యాసం: \"అందరికీ నమస్కారం. చెట్లు నరకడం, ప్లాస్టిక్ వాడకం, వాహనాల పొగ, పరిశ్రమల వ్యర్థాలతో గాలి, నీరు, నేల కలుషితమవుతున్నాయి. భూతాపం పెరిగి అకాల వర్షాలు, కరువులు, తుపానులు వస్తున్నాయి. ఇప్పుడే మేల్కోకపోతే భవిష్యత్ తరాలకు స్వచ్ఛమైన గాలి, నీరు ఉండవు. మనం ప్రతి ఒక్కరం మొక్కలు నాటి పెంచాలి, ప్లాస్టిక్ మానాలి, నీరు, విద్యుత్ పొదుపు చేయాలి, చెత్తను వేరుచేయాలి. ప్రకృతిని కాపాడితే అది మనల్ని కాపాడుతుంది – వృక్షో రక్షతి రక్షితః. ధన్యవాదాలు\"","2) నమూనా: నేలపట్టు పక్షుల కేంద్రం (నెల్లూరు జిల్లా) – చెరువులోని చెట్లపై వేలాది విదేశీ పక్షులు, గూడబాతులు (పెలికాన్లు), తెల్లని కొంగలు గూళ్ళు కట్టుకుంటాయి. ఉదయం చెరువు నీటిపై సూర్యకిరణాలు మెరుస్తూ, పక్షుల కిలకిలారావాలతో ఆ ప్రదేశం స్వర్గంలా ఉంటుంది. గ్రామస్తులు పక్షులను కాపాడటం మనసుకు హత్తుకుంది","పదజాలం అ) 1) ముకురం = అద్దం – అద్దం ముందు నిలబడి తల దువ్వుకున్నాను 2) పికము = కోకిల – వసంతంలో కోకిల కూస్తుంది 3) నెమ్మి = నెమలి – నెమలి మన జాతీయ పక్షి 4) సరోవరం = సరస్సు – సరస్సులో తామరలు ఉన్నాయి 5) నెత్తావి = సువాసన – మల్లెల సువాసన హాయినిస్తుంది","ఆ) 1) పుష్పాలు, కుసుమాలు, విరులు 2) రజని, రాత్రి, రేయి 3) కొండలు, పర్వతాలు, గిరులు 4) అడవులు, అరణ్యాలు, విపినాలు 5) ఆట, నటన, లాస్యము"]],["నానార్థాలు, వ్యుత్పత్త్యర్థాలు, ప్రకృతి–వికృతులు; సంధులు (పుట 82)",["ఇ) 1) అరుణం – ఇ (ఎరుపు, కుష్టువ్యాధి, బంగారం) 2) మతం – ఉ (అభిప్రాయం, శాస్త్రం, సమ్మతి) 3) కొమ్మ – అ (శాఖ, స్త్రీ, కోటబురుజు) 4) నెమ్మి – ఈ (ప్రేమ, నెమ్మది, నెమలి) 5) గగనం – ఆ (ఆకాశం, శూన్యం, దుర్లభం)","ఈ) 1) పికం – ఈ (చాటు నుండి కూయునది – కోయిల) 2) అచలము – అ (చలనము లేనిది – పర్వతము) 3) మేఘం – ఆ (వర్షములచే భూమిని తడుపునది – మబ్బు) 4) సమరం – ఇ (మరణంతో కూడినది – యుద్ధం)","ఉ) 1) మేఘం – మొగులు 2) నాట్యం – నట్టువ 3) కవిత – కయిత 4) సంభ్రమము – సంబరము","అ) 1) మతములన్ని = మతములు + అన్ని (ఉకార సంధి) 2) పూందేనె = పూవు + తేనె (ప్రాతాది సంధి) 3) లతాలి = లత + ఆలి (సవర్ణదీర్ఘ సంధి) 4) కొలువైన = కొలువు + ఐన (ఉకార సంధి)"]],["పడ్వాది సూత్రం; ఆ) సమాసాలు; బహువ్రీహి; ఇ, ఈ) స్వభావోక్తి (పుట 83)",["పడ్వాది సూత్రం: పడ్వాదులు (పడు, పాటు, పెట్టు, పట్టు, పరచు) పరమైనప్పుడు \"ము\" వర్ణానికి లోప, పూర్ణబిందువులు విభాషగా వస్తాయి","ఆ) 1) గగనకాంత – గగనము అనెడి కాంత (రూపక సమాసం) 2) సమతామమతలు – సమతయు, మమతయు (ద్వంద్వ సమాసం) 3) మేఘమాలికలు – మేఘముల యొక్క మాలికలు (షష్ఠీ తత్పురుష) 4) సుందరమేఘాలు – సుందరమైన మేఘాలు (విశేషణ పూర్వపద కర్మధారయ) 5) కుటిలబుద్ధి – కుటిలమైన బుద్ధి (విశేషణ పూర్వపద కర్మధారయ) 6) తిండిగింజలు – తిండి కొరకు గింజలు (చతుర్థీ తత్పురుష) 7) అనురాగసారం – అనురాగము యొక్క సారం (షష్ఠీ తత్పురుష)","ఇ) స్వభావోక్తి అలంకారం – లకుముకి పిట్టల సహజ స్వభావాన్ని ఉన్నది ఉన్నట్లు రమణీయంగా వర్ణించారు","ఈ) స్వభావోక్తి ఉదాహరణలు: 1) \"పురివిప్పి నాట్యముల్ పోహలించెడి నెమ్మి\" 2) \"కష్టపడి నష్టపడి కలసికట్టుగ నడచి తిండిగింజల తెచ్చితీరు చీమలబారు\" 3) లేగదూడ తోక ఎత్తి చెంగుచెంగున గెంతుతూ తల్లి దగ్గరకు పరుగెత్తింది 4) కోడి కుంపటి దింపుకుని పిల్లలకు గింజలు ఏరుకోవడం నేర్పుతోంది"]],["ప్రాజెక్టుపని (పుట 84)",["ప్రకృతి సౌందర్య గేయాలు/పద్యాలు సేకరించండి – ఉదా: \"కోడికుంపటి దింపుకొని…\" (గుర్రం జాషువా), \"చల్లనివైన రాత్రుల…\" (వేంకట కాళిదాస కవులు – మబ్బుతునక), దేవులపల్లి కృష్ణశాస్త్రి ప్రకృతి గీతాలు, \"ఎంత చక్కనిదోయి ఈ తెలుగు తోట\" వంటి పాటలు; తరగతిలో పాడి, ప్రతి గేయంలోని ప్రకృతి సందేశాన్ని చర్చించండి"]]]},{"id":"te8","no":8,"t":"జీవని","m":[9],"ty":"కథ","th":"ప్రత్యేక అవసరాల పిల్లలు – మాతృప్రేమ, సహానుభూతి","by":"డా. వి. చంద్రశేఖరరావు","sum":"ముప్పై ఏళ్ళ నిరీక్షణ తర్వాత లలితకు గర్భం రాగా, పుట్టబోయే బిడ్డకు మెదడు పెరగకపోవచ్చని డాక్టర్లు చెబుతారు. అయినా బిడ్డను కనాలని నిర్ణయించుకుంటుంది. ప్రత్యేక అవసరాలున్న పాప పుట్టగా భర్త, అత్త, ఆడబిడ్డ ఎవరూ పట్టించుకోరు; భర్త ఆశ్రమంలో చేర్చుదామన్నా లలిత ఒప్పుకోదు. వీధిలో గారడీ చేసే ఐదేళ్ళ జీవమ్మను చూసి శిక్షణ, పట్టుదలతో ఏదైనా సాధ్యమని స్ఫూర్తి పొంది తన పాపకు \"జీవని\" అని పేరు పెడుతుంది. బస్సులో పరిచయమైన మనస్తత్వ శాస్త్రవేత్త విశ్వనాథం (తానూ అలాంటి కూతురు ప్రమోదినిని పెంచినవాడు) సూచనలతో జీవని నాలుగేళ్ళకు నడక నేర్చుకుంటుంది. పిల్లలు ముందు గేలిచేసినా తర్వాత ఆటల్లో కలుపుకుంటారు. బడిలో వర్ణమాల రాకపోయినా ఆకాశం, మబ్బులు, పక్షుల బొమ్మలు గీసే జీవని ప్రత్యేకతను గుర్తించమని లలిత టీచర్లను అర్థిస్తుంది; ఆర్ట్ టీచర్ మణిభూషణ్ శిక్షణలో జీవని \"అమ్మ\" చిత్రానికి సోవియట్ లాండ్ చిల్డ్రన్స్ పెయింటింగ్స్ అవార్డు (దక్షిణ భారతంలో ఒక్కరికే) వస్తుంది. టీవీ ఇంటర్వ్యూలో ప్రతి ప్రశ్నకూ జీవని \"అమ్మ\" అనే జవాబిస్తుంది.","pts":["రచయిత: డా. వి. చంద్రశేఖరరావు (13.04.1959 – 08.07.2017) – ప్రకాశం జిల్లా; తల్లిదండ్రులు మహాలక్ష్మి, దేవసహాయం.","రచనలు: జీవని, మాయాలాంతరు, ద్రోహవృక్షం, లెనిన్ ప్లేస్ (కథా సంపుటాలు); నల్లమిరియం చెట్టు, ఐదు హంసలు, ఆకుపచ్చని దేశం (నవలలు). \"జీవని\" కథ నాటకంగా 1991లో ఆకాశవాణి జాతీయ ఉత్తమ నాటక బహుమతి పొందింది.","ప్రక్రియ: కథ – జీవితంలోని ఒక ముఖ్య సన్నివేశాన్ని కళాత్మకంగా, క్లుప్తంగా చిత్రించేది; పాత్రలు, నేపథ్యం, కథనం, వాస్తవిక చిత్రణ ముఖ్యం.","పాత్రలు: లలిత (తల్లి), జీవని (పాప), జీవమ్మ (\"జీవని సీనియర్\" – గారడీ పాప), విశ్వనాథం (మనస్తత్వ శాస్త్రవేత్త), మణిభూషణ్ (ఆర్ట్ టీచర్), మాలినీ రావు (క్లాస్ టీచర్).","జీవని పెయింటింగ్ \"అమ్మ\" కు సోవియట్ లాండ్ చిల్డ్రన్స్ పెయింటింగ్స్ అవార్డు; జనవరి 10న మాస్కో ప్రయాణం.","సందేశం: ప్రత్యేక అవసరాల పిల్లలకు ఓపిక, అనురాగం, చేయూత ఇస్తే వారూ మామూలు మనుషుల్లా బతకగలరు, అద్భుతాలు సాధించగలరు.","డిసెంబర్ 3 – అంతర్జాతీయ దివ్యాంగుల దినోత్సవం. అవని లేఖరా – టోక్యో పారా ఒలింపిక్స్ (2021) లో స్వర్ణం, కాంస్యం."],"w":[["విన్యాసం","ప్రదర్శన, విధానం"],["అంధకారం","చీకటి"],["జన్మాంధుడు","పుట్టుకతో చూపు లేనివాడు"],["వేణువు","మురళి, పిల్లనగ్రోవి"],["లేశము","కొంచెం"],["సుధ","అమృతం"],["పీయూషం","అమృతం"],["క్షుత్తు","ఆకలి"],["భానుడు","సూర్యుడు"],["తర్ఫీదు","శిక్షణ"],["కాంక్ష","కోరిక"],["మస్తిష్కం","మెదడు"],["స్నిగ్ధహాసం","ఆప్యాయమైన చిరునవ్వు"],["ఆత్మస్థైర్యం","మనోధైర్యం"],["సహానుభూతి","ఇతరుల బాధను తనదిగా భావించడం"]],"gr":{"t":"భాషాంశాలు","p":["విసర్గ సంధి (6 విధాలు): 1) అకారాంత విసర్గకు వర్గ ప్రథమ, ద్వితీయ, శ ష స లు కాక మిగతావి పరమైతే విసర్గ లోపించి \"ఓ\" – శిరః + రత్నం = శిరోరత్నం 2) శ ష స పరమైతే ద్విత్వం – మనః + శాంతి = మనశ్శాంతి 3) క ఖ ప ఫ పరమైతే మార్పు లేదు – యశఃకాయము 4) అంతః, దుః, చతుః, పునః విసర్గ \"ర్\" – అంతరాత్మ, ధనుర్విద్య 5) ఇస్, ఉస్ విసర్గకు క ఖ ప ఫ పరమైతే \"ష\" – దుష్కరము 6) చ ఛ → శ, ట ఠ → ష, త థ → స – దుశ్చేష్టితం, ధనుష్టంకారం, నిస్తేజం.","క్రమాలంకారం (యథాసంఖ్యం): వస్తువుల క్రమాన్ని పాటిస్తూ అదే క్రమంలో అన్వయం – \"శత్రువుని మిత్రుని విపత్తుని జయింపుము రంజింపుము భంజింపుము\".","సంశ్లిష్ట వాక్యం: ఒకే కర్త గల రెండు వాక్యాలను అసమాపక క్రియతో కలపడం – \"రేష్మ ఆసుపత్రికి వెళ్ళి పరీక్షలు చేయించుకుంది\".","టుగాగమ సంధి: ఎండు + ఆకు = ఎండుటాకు."]},"qa":[["లలిత ఎలాంటి నిర్ణయం తీసుకుంది?","బిడ్డ మెదడు పెరగకుండా పుట్టవచ్చని తెలిసినా, బిడ్డలు లేకపోవడం కంటే ఎలాంటి బిడ్డైనా కనాలని."],["లలితకు ఒంటరిని అని ఎందుకు అనిపించింది?","అత్త, ఆడబిడ్డ, భర్త అందరూ ఉన్నా ఎవరూ ఆమెనూ పాపనూ పట్టించుకోలేదు."],["గారడీ ఆట ద్వారా లలిత పొందిన స్ఫూర్తి?","ఏదైనా సాధించాలంటే శిక్షణ, తపస్సులాంటి పట్టుదల కావాలి – కష్టపడి నేర్పితే తన పాపా అవసరమైన పనులు నేర్చుకుంటుంది."],["విశ్వనాథం ఎవరు?","మనస్తత్వ శాస్త్రవేత్త; తానూ ప్రత్యేక అవసరాల కూతురు ప్రమోదినిని పెంచి పదో తరగతి చదివించినవాడు; జీవని ఎదుగుదలకు సూచనలు, ప్రయోగాలు చేశాడు."],["జీవనిలో వచ్చిన మార్పులు?","అమాయకత్వం పోయి ఆలోచన స్థిరపడింది; వెకిలి నవ్వు బదులు స్నిగ్ధహాసం; పరిమిత మాటలు స్వేచ్ఛగా మాట్లాడటం; బొమ్మలు గీయడంలో అభివృద్ధి."],["టీవీ ఇంటర్వ్యూలో జీవని ఏం చెప్పింది?","ఇష్టమైనవారు, స్ఫూర్తి, ఇంట్లో సహాయం – అన్నిటికీ \"అమ్మ\" అనే జవాబిచ్చింది."]],"act":"మీ పాఠశాల/ఊరిలోని ప్రత్యేక అవసరాలు గల పిల్లలతో ఒక రోజు ఆటలు, బొమ్మలు గీయడం నిర్వహించండి; \"నేను ఎలా తోడ్పడగలను\" అనే అంశంపై చర్చించండి.","kn":"గొరవయ్యల నృత్యం – కర్నూలు, అనంతపురం; ఎలుగుబంటి చర్మపు టోపీ. తప్పెటగుళ్ళు – ఉత్తరాంధ్ర జానపద కళ. ఫిరంగిపురం (గుంటూరు) బాలయేసు కేథెడ్రల్ – 1891లో ఫాదర్ థియోడర్ నిర్మించారు.","qz":[["\"జీవని\" కథ రచయిత?","డా. వి. చంద్రశేఖరరావు","శీలా వీర్రాజు","వాసిరెడ్డి సీతాదేవి","మూలింటి చంద్రకళ"],["చంద్రశేఖరరావు జిల్లా?","ప్రకాశం","నెల్లూరు","కడప","రాజమండ్రి"],["ఈ పాఠం ప్రక్రియ?","కథ","వ్యాసం","గేయకవిత","శతకం"],["లలిత తన పాపకు \"జీవని\" అని ఎవరిని చూసి పేరు పెట్టింది?","గారడీ ఆడే పాప జీవమ్మ","డాక్టర్ సరళ","విశ్వనాథం భార్య","ఆర్ట్ టీచర్"],["భర్త పాపను ఎక్కడ చేర్చుదామన్నాడు?","బెంగుళూరు ఆశ్రమంలో","హైదరాబాద్ ఆసుపత్రిలో","అత్తగారింట్లో","హాస్టల్‌లో"],["విశ్వనాథం ఎవరు?","మనస్తత్వ శాస్త్రవేత్త","డాక్టర్","ఉపాధ్యాయుడు","గారడీవాడు"],["విశ్వనాథం కూతురి పేరు?","ప్రమోదిని","జీవని","మాలిని","సరళ"],["జీవని ఎన్నేళ్ళకు నడక నేర్చుకుంది?","నాలుగేళ్ళకు","రెండేళ్ళకు","ఏడేళ్ళకు","ఒక ఏడాదికి"],["జీవనికి చిత్రలేఖనం నేర్పిన టీచర్?","మణిభూషణ్","మాలినీ రావు","సరళ","లలిత"],["జీవనికి అవార్డు తెచ్చిన చిత్రం పేరు?","అమ్మ","ఆకాశం","పక్షులు","బడి"],["జీవనికి వచ్చిన అవార్డు?","సోవియట్ లాండ్ చిల్డ్రన్స్ పెయింటింగ్స్ అవార్డు","పద్మశ్రీ","రాజీవ్ ఖేల్‌రత్న","నంది అవార్డు"],["జీవనికి ఇష్టమైనవి?","ఆకాశం, నీలిమబ్బు, పక్షుల గుంపులు","టీవీ","వర్ణమాల","లెక్కలు"],["అంతర్జాతీయ దివ్యాంగుల దినోత్సవం?","డిసెంబర్ 3","డిసెంబర్ 10","నవంబర్ 14","జూన్ 5"],["మనః + శాంతి = ?","మనశ్శాంతి (విసర్గ సంధి)","మనోశాంతి","మనస్శాంతి","మనఃశాంతి మాత్రమే"],["\"శత్రువుని మిత్రుని విపత్తుని జయింపుము రంజింపుము భంజింపుము\" – అలంకారం?","క్రమాలంకారం","స్వభావోక్తి","రూపకం","ఉపమ"],["ఎండు + ఆకు = ఎండుటాకు – సంధి?","టుగాగమ సంధి","ఉకార సంధి","ప్రాతాది","లులనల"]],"wb":{"mis":"విసర్గ సంధిలో పరపదం మొదటి అక్షరాన్ని బట్టి రూపం మారుతుంది: శిరః + రత్నం = శిరోరత్నం (ఓ), అంతః + ఆత్మ = అంతరాత్మ (ర్), దుః + కరము = దుష్కరము (ష్). సంశ్లిష్ట వాక్యంలో మొదటి క్రియ అసమాపక క్రియ (\"వెళ్ళి\") అవుతుంది.","qz":[["తపోబలం విడదీస్తే?","తపః + బలం (విసర్గ సంధి)","తపో + బలం","తప + ఓబలం","తపు + బలం"],["అంతః + అంగం = ?","అంతరంగం","అంతోంగం","అంతఃఅంగం","అంతాంగం"],["ధనుః + విద్య = ?","ధనుర్విద్య","ధనుర్ద్విద్య","ధనోవిద్య","ధనుష్విద్య"],["దుష్కరము విడదీస్తే?","దుః + కరము","దుష్ + కరము (గుణ)","దు + ష్కరము","దుస్ + కరము (ఉకార)"],["అప్పుడు + అప్పుడు = ?","అప్పుడప్పుడు (ఆమ్రేడిత సంధి)","అప్పుడుప్పుడు","అప్పుడాప్పుడు","అప్పప్పుడు"],["కుటుంబమంతా విడదీస్తే?","కుటుంబము + అంతా (ఉకార సంధి)","కుటుంబ + మంతా","కుటుంబం + అంత","కుటుం + బమంతా"],["\"జ్ఞానదీపం\" సమాసం?","రూపక సమాసం (జ్ఞానము అనెడి దీపం)","ద్వంద్వ","ద్విగు","బహువ్రీహి"],["\"ఐదునెలలు\" సమాసం?","ద్విగు సమాసం","ద్వంద్వ","షష్ఠీ తత్పురుష","రూపక"],["\"పిల్లలూ! మీరందరూ ఆడుకోవచ్చు\" – వాక్యం?","అనుమత్యర్థక వాక్యం","సామర్థ్యార్థక","నిషేధార్థక","సందేహార్థక"],["వైద్యులు – వికృతి?","వెజ్జులు","అబ్బురం","పక్కి","అచ్చెరువు"]],"pg":"86–99","f":"books/10/Class10_Telugu_Textbook_Sem1.pdf","p":94,"lb":"పాఠ్యపుస్తకం","ws":["అవగాహన – ప్రతిస్పందన: అ) చర్చ, ఆ) పద్యం (పుట 91)","ఇ) అపరిచిత గద్యం, ఈ) అర్థసందర్భాలు, ఉ) ఏకవాక్య; వ్యక్తీకరణ అ) (పుట 92)","వ్యక్తీకరణ అ3), ఆ), ఇ); పదజాలం (పుట 93)","పర్యాయపదాలు, నానార్థాలు, వ్యుత్పత్త్యర్థాలు, ప్రకృతి–వికృతి, జాతీయాలు (పుట 94)","వ్యాకరణం: సంధులు విడదీయడం, కలపడం, విసర్గ సంధి (పుట 95)","విసర్గ సంధి – మిగతా రూపాలు (పుట 96)","ఇ) సమాసాలు, క్రమాలంకారం, ఈ) సంశ్లిష్ట వాక్యాలు (పుట 97)","ఉ) వాక్యాల రకాలు; ప్రాజెక్టుపని (పుట 98)"]},"tg":[["అవగాహన – ప్రతిస్పందన: అ) చర్చ, ఆ) పద్యం (పుట 91)",["అ) 1) నమూనా: నాకు నచ్చిన సన్నివేశం – టీవీ ఇంటర్వ్యూలో ఎవరు ఏ ప్రశ్న అడిగినా జీవని \"అమ్మ\" అని చెప్పడం. అందరూ వదిలేసినా తల్లి ఒక్కతే పట్టుదలతో పెంచి ప్రపంచస్థాయి గుర్తింపు తెచ్చింది – అమ్మ ప్రేమ గొప్పతనం తెలుస్తుంది. లలిత గారడీ పాప జీవమ్మను చూసి స్ఫూర్తి పొందిన సన్నివేశం కూడా నచ్చింది","2) పిల్లలకు కులం, మతం, ధనం, అంగవైకల్యం వంటి భేదభావాలు ఉండవు. మొదట జీవనిని గేలిచేసినా తర్వాత ఆప్యాయంగా ఆటల్లో కలుపుకున్నారు – పెళ్ళి ఆటలో జీవనినే పెళ్ళికూతురిని చేశారు. పెద్దలు నేర్పకపోతే పిల్లల మనసు నిష్కల్మషంగానే ఉంటుంది – ఈ వాక్యం నిజమే","ఆ) 1) పరస్త్రీలను సోదరిలా భావించాలి 2) పరుల ధనానికి ఆశపడకూడదు 3) పరస్త్రీలను సోదరిలా చూస్తూ, పరధనానికి ఆశపడకుండా, ఇతరులకు మేలు చేస్తూ, పొగిడితే పొంగిపోక, తిడితే కోపగించనివాడు ఉత్తముడు 4) ఉదా: ఈ పద్యం ఏ శతకంలోనిది? (సుమతీ శతకం – బద్దెన)"]],["ఇ) అపరిచిత గద్యం, ఈ) అర్థసందర్భాలు, ఉ) ఏకవాక్య; వ్యక్తీకరణ అ) (పుట 92)",["ఇ) 1) రెండేళ్ళ వయస్సులో వచ్చిన భయంకరమైన జ్వరం 2) పాప చురుకైనది, ప్రోత్సహిస్తే తెలివితేటలు పెంచుకోగలదు; మంచి డాక్టర్‌ను సంప్రదిస్తే మాట్లాడగలదు; ఎల్లవేళలా అంటిపెట్టుకునే టీచర్ ఉంటే మంచిది 3) బ్రెయిలీ లిపి ద్వారా ఎన్నో సంగతులు, లోకవ్యవహారాలు తెలుసుకుని విజ్ఞానం సంపాదించేది 4) అంధుల శ్రేయస్సు కోసం ప్రజల్లోకి వెళ్లి ప్రసంగాలు చేసింది; అంధులకు జీవితంపై విశ్వాసం కలిగించింది","ఈ) 1) \"ఈ ఒక్క కలను సఫలం చెయ్యి తండ్రీ!\" – డా. వి. చంద్రశేఖరరావు రాసిన \"జీవని\" కథలోనిది. సందర్భం: ఎన్నో ఏళ్ళ నిరీక్షణ తర్వాత డాక్టర్ సరళ పరీక్ష చేస్తున్నప్పుడు తల్లి కావాలనే తన కల నెరవేరాలని లలిత దేవుణ్ణి వేడుకున్న సందర్భం","2) \"వారు కూడా మామూలు మనిషిలా బతకగలరు\" – జీవని కథ. సందర్భం: తన కూతురు ప్రమోదినిని పెంచిన అనుభవం చెబుతూ, ప్రత్యేక అవసరాల పిల్లలకు చేయూతనిస్తే వారు మామూలుగా బతకగలరని నిరూపించాలన్నదే తమ ఆరాటం అని విశ్వనాథం లలితతో అన్న మాట","3) \"ఈ శుభాకాంక్షలు మీకే, ఇది మీ విజయమే!\" – జీవని కథ. సందర్భం: జీవని \"అమ్మ\" పెయింటింగ్‌కు అంతర్జాతీయ అవార్డు వచ్చిందని చెప్పడానికి ప్రధానోపాధ్యాయురాలు, టీచర్లు ఇంటికి వచ్చి లలితను అభినందించిన సందర్భం","ఉ) 1) సోవియట్ లాండ్ చిల్డ్రన్స్ పెయింటింగ్స్ అవార్డు 2) జీవని వ్యక్తిత్వ వికాసానికి ప్రయోగాలు చేసి, పెంపకానికి సూచనలు ఇచ్చారు; బడిలో చేర్పించమని సూచించారు 3) బొమ్మలు గీయడంలో (చిత్రలేఖనం)","అ) 1) జీవనికి ఆకాశం, నీలిమబ్బులు, పక్షుల గుంపులు ఇష్టం – ఆకాశం వైపు చేతులు చాచి \"ఓ…ఓ…\" అని పాడుతుంది. రోడ్డుపై చిన్న అలికిడైనా బయటకు వచ్చి చూస్తుంది. కాన్వెంటుకు వెళ్ళే నీలిగౌనుల పిల్లలను చూసి \"ఏ..ఏ..\" అని అరుస్తూ ఆనందిస్తుంది. ఆడుకునే పిల్లల వైపు చేతులూపి తనకూ ఆట పంచమన్నట్లు చూస్తుంది. వర్ణమాల బదులు ఆకాశం, మబ్బులు, పక్షుల బొమ్మలు గీస్తుంది","2) జీవని లాంటి పిల్లలకు ప్రపంచంలో కొదవ లేదు – కానీ లలిత లాంటి తల్లులే అరుదు. ఇలాంటి పిల్లలకు చేయూతనిస్తే వారు కూడా మామూలు మనుషుల్లా బతకగలరు. జీవితం అంటే కాస్త వెలుగు, కాస్త చీకటి. ఓపికతో, ప్రయోగాలతో, సరైన సూచనలతో వారి వ్యక్తిత్వాన్ని వికసింపజేయవచ్చు; పాఠశాలలో చేర్పించాలి"]],["వ్యక్తీకరణ అ3), ఆ), ఇ); పదజాలం (పుట 93)",["అ) 3) \"ఎంత నేర్చుకుంది అని కాక నేర్చుకోవడానికి ఎంత పెనుగులాడుతోందో గమనించండి. జీవనిని ఒక ఛాలెంజిగా తీసుకోండి. సామాజికంగా వెనకబడిన వారికి ప్రత్యేక శిక్షణ ఇచ్చినట్లే మానసికంగా వెనకబడిన పిల్లలనూ ఓపికతో, అనురాగంతో, ఆత్మస్థైర్యం నింపి ముందుకు నడిపిద్దాం. జీవని తల్లిగా కాదు, మార్పును కోరే మహిళగా అర్థిస్తున్నాను – ప్రత్యేక శ్రద్ధ చూపండి, నిరుత్సాహపరచకండి\" అని అర్థించింది","ఆ) 1) గ్రహించినవి: ప్రత్యేక అవసరాల పిల్లలు భారం కాదు – వారికీ ప్రతిభ ఉంటుంది. తల్లి ప్రేమ, పట్టుదల అద్భుతాలు చేస్తాయి. శిక్షణ, సాధనతో ఏదైనా సాధ్యం (గారడీ పాప). విశ్వనాథం లాంటి సహృదయుల చేయూత అవసరం. పిల్లల మనసులో భేదభావం ఉండదు – వారిని కలుపుకుని పోవాలి. ఉపాధ్యాయులు ఓపికతో, పిల్లల ఆసక్తిని గుర్తించి ప్రోత్సహించాలి. కుటుంబం నిర్లక్ష్యం చేసినా ధైర్యం వీడకూడదు. చివరకు భర్త కూడా \"షీ ఈజ్ మై చైల్డ్\" అని గర్వపడ్డాడు – విజయం అందరినీ మారుస్తుంది. వారిపట్ల సహానుభూతితో ఉండాలి","2) జీవని ఉన్నతికి తల్లి లలితే మూలం. ప్రమాదం తెలిసినా బిడ్డను కనాలని నిర్ణయించింది. కుటుంబం పట్టించుకోకపోయినా ఒంటరిగా పెంచింది. భర్త ఆశ్రమంలో చేర్చుదామంటే తిరస్కరించింది – \"ఈ పాప నా ప్రాణం\". గారడీ పాపను చూసి శిక్షణతో నేర్పవచ్చని ధైర్యం తెచ్చుకుంది. విశ్వనాథం సూచనలు పాటించింది; నాలుగేళ్ళ మహాపోరాటంతో నడక నేర్పింది. బడిలో చేర్పించి, టీచర్ ఫిర్యాదు చేస్తే ఉద్వేగంగా జీవని తరఫున అర్థించింది; చిత్రలేఖనంలో ప్రోత్సహించింది. అందుకే అవార్డు \"అమ్మ\" చిత్రానికి, ఇంటర్వ్యూలో ప్రతి జవాబు \"అమ్మ\"","ఇ) 1) సంభాషణ: లలిత – \"నమస్కారం టీచర్, పిలిచారట.\" టీచర్ – \"అవునండీ. జీవని ఏడాదైనా వర్ణమాల రాయడం లేదు, బొమ్మలే గీస్తోంది.\" లలిత – \"ఎంత నేర్చుకుంది అని కాక ఎంత ప్రయత్నిస్తోందో చూడండి టీచర్. ఆమె బొమ్మల్లోనే ఆమె భాష ఉంది.\" టీచర్ – \"నిజమే… ఆకాశం, పక్షులు చాలా బాగా గీస్తుంది.\" లలిత – \"జీవనిని ఒక ఛాలెంజ్‌గా తీసుకోండి. ప్రత్యేక శ్రద్ధ చూపండి.\" టీచర్ – \"తప్పకుండా. మా ఆర్ట్ టీచర్ మణిభూషణ్ గారికి అప్పగిస్తాం. మేమూ కృషి చేస్తాం.\"","2) ప్రత్యేక అవసరాల పిల్లలను ఎగతాళి చేయను, ఇతరులను చేయనివ్వను; ఆటల్లో, బృంద కార్యక్రమాల్లో కలుపుకుంటాను; నోట్సు రాయడంలో, పాఠాలు అర్థం చేసుకోవడంలో సహాయం చేస్తాను; వీల్‌చైర్/నడకకు సహాయం చేస్తాను; వారి ప్రతిభను (పాట, బొమ్మలు) గుర్తించి ఉపాధ్యాయులకు చెబుతాను; స్నేహితుడిగా ధైర్యం ఇస్తాను","పదజాలం అ) 1) విన్యాసాలు = ప్రదర్శనలు – సర్కస్‌లో విన్యాసాలు అబ్బురపరిచాయి 2) అంధకారం = చీకటి – దీపం అంధకారాన్ని పోగొడుతుంది 3) జన్మాంధుడు = పుట్టుకతో చూపు లేనివాడు – జన్మాంధుడైనా సంజీవరాయ శర్మ గణితంలో అద్భుతాలు చేశారు 4) వేణువు = పిల్లనగ్రోవి – కృష్ణుడు వేణువు ఊదేవాడు 5) లేశము = కొంచెం – అతనిలో లేశమైనా గర్వం లేదు","ఆ) 1) సుధ, పీయూషం, అమృతం 2) ఆకలి, క్షుత్తు 3) రవి, భానుడు, సూర్యుడు"]],["పర్యాయపదాలు, నానార్థాలు, వ్యుత్పత్త్యర్థాలు, ప్రకృతి–వికృతి, జాతీయాలు (పుట 94)",["ఆ) 4) శిక్షణ, అభ్యాసం, తర్ఫీదు 5) కోరికలు, కాంక్షలు, ఆశలు","ఇ) 1) ఉదరము – ఆ (పొట్ట, యుద్ధం, నడుము) 2) విన్యాసము – ఇ (ఉంచుట, చక్కని ప్రదర్శన, రచన) 3) అమృతం – ఈ (సుధ, పాలు, ముక్తి) 4) మబ్బు – అ (మేఘము, చీకటి, అజ్ఞానం)","ఈ) 1) ఆకాశం – ఆ (దీనియందంతట సూర్యచంద్రులు ప్రకాశించుదురు) 2) అమృతం – ఇ (మరణాన్ని కలిగింపనిది) 3) విశ్వనాథుడు – ఈ (విశ్వానికి నాథుడు – శివుడు) 4) గురువు – అ (అజ్ఞానాంధకారాన్ని తొలగించేవాడు)","ఉ) ప్రకృతి – వికృతి: అపూర్వం – అబ్బురం; పక్షి – పక్కి; వైద్యులు – వెజ్జులు; ఆశ్చర్యం – అచ్చెరువు; అర్ధరాత్రి – అద్దమరేయి","ఊ) గుసగుసలు – రహస్యంగా మెల్లగా మాట్లాడుకోవడం; మారుమ్రోగుట – శబ్దం అంతటా ప్రతిధ్వనించడం/విషయం అంతటా వ్యాపించడం; మనసులో ముల్లు – ఎప్పుడూ బాధ కలిగించే విషయం; చేజారిపోవు – దక్కకుండా పోవడం"]],["వ్యాకరణం: సంధులు విడదీయడం, కలపడం, విసర్గ సంధి (పుట 95)",["అ) 1) సైనికురాలు = సైనిక + ఉరాలు (అకార సంధి) 2) ప్రత్యేకం = ప్రతి + ఏకం (యణాదేశ సంధి) 3) కుటుంబమంతా = కుటుంబము + అంతా (ఉకార సంధి) 4) ఎండుటాకు = ఎండు + ఆకు (టుగాగమ సంధి) 5) అవయవాలు = అవయవము + లు (లులనల సంధి)","ఆ) 1) మరి + ఒక = మరొక (ఇకార సంధి) 2) అప్పుడు + అప్పుడు = అప్పుడప్పుడు (ఆమ్రేడిత సంధి) 3) అవసరము + ఐన = అవసరమైన (ఉకార సంధి) 4) తగిలిన + అంత = తగిలినంత (అకార సంధి)","విసర్గ: శిరోరత్నం = శిరః + రత్నం; తపోబలం = తపః + బలం; పయోనిధి = పయః + నిధి; వచోనిచయం = వచః + నిచయం; మనః + శాంతి = మనశ్శాంతి; చతుః + షష్టి = చతుష్షష్టి; నభః + సుమం = నభస్సుమం"]],["విసర్గ సంధి – మిగతా రూపాలు (పుట 96)",["యశఃకాయము = యశః + కాయము; తపఃఫలము = తపః + ఫలము (మార్పు లేదు)","ధనుః + విద్య = ధనుర్విద్య; చతుః + భుజుడు = చతుర్భుజుడు; ఆశీః + వాదం = ఆశీర్వాదం; పునః + ఆగమనం = పునరాగమనం; అంతః + అంగం = అంతరంగం (విసర్గ \"ర్\")","నిష్ఫలం = నిః + ఫలం; దుష్కరము = దుః + కరము (విసర్గ \"ష\")","దుశ్చేష్టితం = దుః + చేష్టితం (శ); మనస్తాపం = మనః + తాపం (స); ధనుష్టంకారం = ధనుః + టంకారం (ష)"]],["ఇ) సమాసాలు, క్రమాలంకారం, ఈ) సంశ్లిష్ట వాక్యాలు (పుట 97)",["ఇ) 1) ఐదునెలలు – ఐదు సంఖ్య గల నెలలు (ద్విగు సమాసం) 2) మృదుమధురం – మృదువైనదీ, మధురమైనదీ (విశేషణ ఉభయపద కర్మధారయ) 3) జ్ఞానదీపం – జ్ఞానము అనెడి దీపం (రూపక సమాసం) 4) అనూహ్యం – ఊహ్యం కానిది (నఞ్ తత్పురుష) 5) పిల్లల ప్రపంచం – పిల్లల యొక్క ప్రపంచం (షష్ఠీ తత్పురుష)","అలంకారం: 1) క్రమాలంకారం – గజ (ఏనుగు) వనంలోకి, కచ్ఛపం (తాబేలు) జలంలోకి, మూషికం (ఎలుక) బిలంలోకి – వరుసగా అన్వయం 2) క్రమాలంకారం – సూర్యుడు దివానికి (పగలుకు), చంద్రుడు రాత్రికి అధిపతి","ఈ) 1) రేష్మ ఆసుపత్రికి వెళ్ళి పరీక్షలు చేయించుకుంది 2) విశ్వనాథం జీవని ఇంటికి వచ్చి జీవనికి సహాయం చేశాడు 3) పిల్లలందరూ ఒకచోట చేరి బొమ్మలతో ఆడుకుంటున్నారు 4) ఆమె పాపకు చేయూతనిచ్చి చక్కగా పెంచింది 5) జీవని చిత్రాలెన్నో గీసి ప్రథమ బహుమతి పొందింది"]],["ఉ) వాక్యాల రకాలు; ప్రాజెక్టుపని (పుట 98)",["ఉ) 1) సామర్థ్యార్థక వాక్యం 2) అనుమత్యర్థక వాక్యం 3) సందేహార్థక వాక్యం 4) ఆశ్చర్యార్థక వాక్యం 5) హేత్వర్థక వాక్యం","ప్రాజెక్టు: రాగతి పండరి (కార్టూనిస్టు – పోలియోతో చక్రాల కుర్చీపైనే ఉన్నా ప్రసిద్ధ కార్టూనిస్టు); లక్కోజు సంజీవరాయ శర్మ (జన్మాంధుడైన గణితావధాని); లూయీ బ్రెయిలీ (అంధుల లిపి సృష్టికర్త); హెలెన్ కెల్లర్ (అంధురాలు, బధిరురాలు – రచయిత్రి, ఉద్యమకారిణి); సుధాచంద్రన్ (కాలు కోల్పోయి కృత్రిమ కాలుతో నాట్యకారిణి) – వివరాలు సేకరించి తరగతిలో చర్చించండి"]]]},{"id":"te9","no":9,"t":"రాజధర్మం","m":[10],"ty":"ప్రబంధం (పద్యాలు)","th":"నాయకత్వం – పరిపాలన","by":"శ్రీకృష్ణదేవరాయలు (ఆముక్తమాల్యద)","sum":"యామునాచార్యులు శాస్త్రపాండిత్యంతో పాండ్యరాజును జయించి అర్ధరాజ్యం పొంది పాలించాడు. గురువు శ్రీరామమిశ్రుని ఉపదేశంతో రాజ్యాన్ని కుమారునికి అప్పగిస్తూ రాజధర్మాలు బోధిస్తాడు: విసుగు లేకుండా ప్రజలను కాపాడాలి, ఆపన్నుల మొర విని తీర్చాలి, ముఖ్యమైన పనులు చెడ్డవారికి అప్పగించకూడదు; ఒకరిని పెద్దపదవిలో పెట్టి తర్వాత తగ్గించకూడదు – క్రమంగా పెంచాలి; గుణహీనుడైన మంత్రి \"గుమ్మడికాయంత ముత్యం\" లాంటివాడు – మంత్రి లేకపోయినా మేలు; ధనం ఒక్కటే చాలదు, అధికారులకు తగిన జీతం, మిత్రత్వం కావాలి; చాడీలను పరీక్షించాలి; దేశం చిన్నదైతే చెరువులు, కాలువలు తవ్వించి పేదల పన్నులు తగ్గించాలి; కరువుతో వలస వెళ్ళిన ప్రజలను తిరిగి రప్పించి ఆదుకోవాలి – వారి ఆస్తులను దోచుకునే అధికారి యుద్ధభూమి నక్క లాంటివాడు; విషయాల్లో ముప్పాతిక స్వయంగా, పావు ఆప్తుల ద్వారా తెలుసుకోవాలి; ఎలుగుబంటిలా ఒక కన్ను తెరిచి జాగ్రత్తగా ఉండాలి; విలుకాడు గురి చూసి బాణం విడిచినట్లు సమయం చూసి దోషిని శిక్షించాలి; అనుచరులు హితులు, హితాహితులు, అహితులు అని మూడు రకాలు; నిజాయితీగల హితుడికి పనసపండ్లు దిగినట్లు అకస్మాత్తుగా భారీ బహుమానం ఇవ్వాలి.","pts":["కవి: శ్రీకృష్ణదేవరాయలు – 16వ శతాబ్దం; విజయనగర సామ్రాజ్యం, తుళువ వంశం; సంస్కృత, ఆంధ్ర, కన్నడ పండితుడు.","సంస్కృత రచనలు: మదాలస చరిత్ర, సత్యవధూప్రీణనము, జ్ఞానచింతామణి, రసమంజరి. తెలుగులో \"ఆముక్తమాల్యద\" ప్రబంధం.","బిరుదులు: సాహితీ సమరాంగణ సార్వభౌముడు, మూరురాయరగండ, ఆంధ్రభోజుడు; అష్టదిగ్గజ కవుల పోషకుడు; ఈ యుగం \"ప్రబంధ యుగం\".","పాఠం ఆముక్తమాల్యద చతుర్థాశ్వాసం నుండి – యామునాచార్యుడు కుమారునికి చేసిన రాజనీతి బోధ.","ప్రక్రియ: ప్రబంధం – ప్రకృష్టమైన బంధం కలది; పురాణేతిహాసాల నుండి చిన్న కథను తీసుకుని అష్టాదశ వర్ణనలతో పెంచిన స్వతంత్ర కావ్యం.","పోలికలు: గుణహీన మంత్రి = గుమ్మడికాయంత ముత్యం; దోచుకునే అధికారి = యుద్ధభూమి నక్క; జాగరూకత = ఎలుగుబంటి (అచ్ఛభల్లం); సమయానికి శిక్ష = విలుకాడు; హితునికి బహుమతి = పనసపండ్లు దిగినట్లు.","అనుచరులు 3 రకాలు: హితులు (వైద్యులు, జ్యోతిష్కులు, పండితులు, కవులు, పురోహితులు), హితాహితులు (ధనార్జన అధికారులు), అహితులు.","సప్త ద్వీపాలు: జంబూ, ప్లక్ష, శాల్మల, కుశ, క్రౌంచ, శాక, పుష్కర."],"w":[["కాపురుషుడు","చెడ్డవాడు, దుష్టుడు"],["స్వప్నం","కల"],["ఆస్థ","శ్రద్ధ, నమ్మకం"],["భిషక్కు","వైద్యుడు"],["హితుడు","మేలు కోరేవాడు"],["మృష","అబద్ధం"],["బృందం","గుంపు, సమూహం"],["క్షితి","భూమి"],["వ్రాతము","సమూహం"],["విపన్నులు","ఆపదలో ఉన్నవారు"],["అచ్ఛభల్లం","ఎలుగుబంటి"],["భూరుహం","చెట్టు"],["శరం","బాణం"],["నృశంస్యం","క్రూరత్వం"],["అదను","తగిన సమయం"]],"gr":{"t":"భాషాంశాలు","p":["శ్లేషాలంకారం: నానార్థాలు కలిగిన పదాలను ప్రయోగించి రెండు అర్థాలు స్ఫురింపజేయడం – \"రాజు కువలయానందకరుడు\" (చంద్రుడు కలువలకు / ప్రభువు భూమికి ఆనందం కలిగిస్తాడు).","కంద పద్యం: చతుర్మాత్రా గణాలు (భ, జ, స, నల, గగ); 1–2 పాదాల్లో 3+5 = 8 గణాలు, 3–4 పాదాల్లో 3+5 = 8 గణాలు; ప్రాస ఉంటుంది; 2, 4 పాదాల చివర గురువు; 2, 4 పాదాల్లో 1–4 గణాల మొదటి అక్షరాలకు యతి; 6వ గణం జ లేదా నల; బేసి గణాలలో జ గణం రాకూడదు.","యడాగమ సంధి: మృష + ఏని = మృషయేని. త్రిక సంధి: ఏ + వాడు = ఎవ్వాడు.","లోకోక్తి: లోకంలో ప్రసిద్ధమైన సామెత/పోలికను ప్రయోగించడం – యుద్ధభూమి నక్క."]},"qa":[["ముఖ్యమైన పనులు ఎవరికి అప్పగించకూడదు?","కాపురుషులకు (చెడ్డవారికి)."],["గుణహీనుడైన మంత్రిని దేనితో పోల్చాడు?","గుమ్మడికాయంత ముత్యంతో – ధరించలేనంత భారం; రాజే అతనికి లోబడాల్సి వస్తుంది."],["రాజు ఏ జంతువులా జాగరూకుడై ఉండాలి?","చెట్టుకొమ్మపై ఒక కన్ను మూసి, ఒక కన్ను తెరిచి నిద్రించే ఎలుగుబంటిలా."],["దోషిని ఎలా శిక్షించాలి?","వెంటనే కాకుండా, విలుకాడు గురి కుదిరేదాకా బాణం ఆపినట్లు, తగిన సమయం వచ్చేదాకా కోపం అదుపులో ఉంచి శిక్షించాలి."],["దేశం చిన్నదైతే రాజు ఏం చేయాలి?","చెరువులు, కాలువలు తవ్వించాలి; పేదల పన్నులు తగ్గించాలి."],["విషయాలను రాజు ఎలా తెలుసుకోవాలి?","ముప్పాతిక భాగం స్వయంగా, మిగిలిన పావు భాగం ఆప్తమిత్రుల ద్వారా."],["నిజాయితీగల హితుడిని ఎలా గౌరవించాలి?","అతడు అడగకుండానే, ఎవరూ చెప్పకుండానే, పనసపండ్లు దిగినట్లు ఊహించనంత బహుమతి ఒక్కసారిగా ఇవ్వాలి."]],"act":"తరగతి నాయకుని ఎన్నిక నిర్వహించి, ఎన్నికైనవారు పాఠంలోని రాజధర్మాల ఆధారంగా \"తరగతి నాయకుని 10 బాధ్యతలు\" చార్టు తయారు చేసి ప్రదర్శించండి.","kn":"ఒగ్గుకథ – శివుని ఢమరుకం (ఒగ్గు) తో చెప్పే మల్లన్న, వీరప్ప కథలు. పెదఅవుటపల్లి (గన్నవరం) జోసఫ్ తంబి తిరునాళ్లు – జనవరి 13–15.","qz":[["\"రాజధర్మం\" పాఠం ఏ కావ్యం నుండి?","ఆముక్తమాల్యద","మనుచరిత్ర","పాండురంగ మాహాత్మ్యం","విజయవిలాసం"],["ఆముక్తమాల్యద రచయిత?","శ్రీకృష్ణదేవరాయలు","అల్లసాని పెద్దన","తెనాలి రామకృష్ణుడు","ధూర్జటి"],["ఈ పాఠం ప్రక్రియ?","ప్రబంధం","శతకం","ఖండకావ్యం","గేయకవిత"],["రాయల బిరుదు కానిది?","కవిత్రయం","సాహితీ సమరాంగణ సార్వభౌముడు","ఆంధ్రభోజుడు","మూరురాయరగండ"],["రాజధర్మాలు బోధించినది?","యామునాచార్యులు","శ్రీరామమిశ్రుడు","పాండ్యరాజు","విష్ణుచిత్తుడు"],["గుణహీనుడైన మంత్రి దేనితో సమానం?","గుమ్మడికాయంత ముత్యం","బంగారు కిరీటం","పనసపండు","నిండుకుండ"],["ప్రజల ఆస్తులు దోచుకునే అధికారి దేనితో సమానం?","యుద్ధభూమి నక్క","ఎలుగుబంటి","విలుకాడు","సింహం"],["రాజు జాగరూకతకు పోలిక?","ఎలుగుబంటి","నక్క","ఏనుగు","తాబేలు"],["విషయాలను రాజు స్వయంగా ఎంత భాగం తెలుసుకోవాలి?","ముప్పాతిక (మూడు పాళ్ళు)","సగం","పావు","అంతా మంత్రుల ద్వారా"],["రాజు అనుచరులు ఎన్ని రకాలు?","మూడు","రెండు","నాలుగు","ఏడు"],["వైద్యులు, కవులు, పురోహితులు – ఏ రకం అనుచరులు?","హితులు","హితాహితులు","అహితులు","శత్రువులు"],["హితునికి బహుమతి ఎలా ఇవ్వాలి?","పనసపండ్లు దిగినట్లు అకస్మాత్తుగా, భారీగా","కొద్దికొద్దిగా","అడిగితేనే","ఇవ్వకూడదు"],["\"రాజు కువలయానందకరుడు\" – అలంకారం?","శ్లేష","ఉపమ","క్రమాలంకారం","స్వభావోక్తి"],["కంద పద్యంలో 6వ గణం?","జ లేదా నల","భ","గగ","స"],["ప్రబంధంలో వర్ణనలు?","అష్టాదశ (18) వర్ణనలు","ఏడు","నూరు","మూడు"],["తెలుగు సాహిత్యంలో రాయల యుగం పేరు?","ప్రబంధ యుగం","కవిత్రయ యుగం","ఆధునిక యుగం","శతక యుగం"]],"wb":{"mis":"కంద పద్యం బేసి గణాల్లో (1,3,5,7) జ గణం రాకూడదు; 2, 4 పాదాల చివర గురువు తప్పనిసరి. శ్లేషలో ఒకే పదానికి రెండు అర్థాలు ఒకేసారి సరిపోవాలి.","qz":[["ఎవ్వాడు విడదీస్తే?","ఏ + వాడు (త్రిక సంధి)","ఎవ్వ + ఆడు","ఎవ + వాడు","ఏ + ఎవ్వాడు"],["గుణాతీతుడు విడదీస్తే?","గుణ + అతీతుడు (సవర్ణదీర్ఘ)","గుణా + తీతుడు","గుణ + ఆతీతుడు (గుణ)","గుణి + అతీతుడు"],["మృషయేని విడదీస్తే?","మృష + ఏని (యడాగమ సంధి)","మృషయ + ఏని","మృష + యేని (త్రిక)","మృషే + ఏని"],["దీవులుగొన్న విడదీస్తే?","దీవులు + కొన్న (గసడదవాదేశ)","దీవులు + గొన్న","దీవుల + ఉగొన్న","దీవి + ఉలుగొన్న"],["తదంతరము విడదీస్తే?","తత్ + అంతరము (జశ్త్వ సంధి)","తద + అంతరము","త + దంతరము","తదా + అంతరము"],["\"హితాహితులు\" సమాసం?","ద్వంద్వ సమాసం","ద్విగు","బహువ్రీహి","రూపక"],["\"ఏడుదీవులు\" సమాసం?","ద్విగు సమాసం","ద్వంద్వ","షష్ఠీ","కర్మధారయ"],["\"లోభము కానిది\" – సమాస పదం?","అలోభము (నఞ్ తత్పురుష)","లోభరహితం (ద్విగు)","నిర్లోభం (ద్వంద్వ)","లోభహీనం (బహువ్రీహి)"],["మౌక్తికం – వికృతి?","ముత్యము","సత్తువ","పసరము","దీవి"],["\"శరం\" నానార్థాలు?","రెల్లు, బాణం, నీరు","తొడిమ, బాణం","నీతి, అందం","సత్యం, నీరు"]],"pg":"100–111","f":"books/10/Class10_Telugu_Textbook_Sem1.pdf","p":108,"lb":"పాఠ్యపుస్తకం","ws":["అవగాహన – ప్రతిస్పందన: అ) ప్రశ్నలు, ఆ) పద్యం (పుట 104)","ఇ) అపరిచిత గద్యం, ఈ) అర్థసందర్భాలు, ఉ) ఏకవాక్య; వ్యక్తీకరణ అ) (పుట 105)","వ్యక్తీకరణ అ3), ఆ), ఇ); పదజాలం (పుట 106)","వ్యుత్పత్త్యర్థాలు, వికృతులు; సంధులు (పుట 107)","ఇ, ఈ) సమాసాలు; శ్లేషాలంకారం (పుట 108)","కంద పద్య లక్షణాలు; ప్రాజెక్టుపని (పుట 109)"]},"tg":[["అవగాహన – ప్రతిస్పందన: అ) ప్రశ్నలు, ఆ) పద్యం (పుట 104)",["అ) 1) \"కన్నొకటి…\" భావం: ఎలుగుబంటి చెట్టుకొమ్మ మీద పడుకుని ఒక కన్ను మూసి నిద్రపోతున్నా రెండో కన్ను తెరిచి మెలకువగా ఉంటుంది. అలాగే రాజు భోగాలు అనుభవిస్తూనే లోపలి, బయటి శత్రువులపై ఎప్పుడూ ఒక కన్ను వేసి జాగ్రత్తగా ఉండాలి","2) పాలకుడు ప్రజలను విసుగు లేకుండా కాపాడాలి; వారి మొరలు శ్రద్ధగా విని తీర్చాలి; పేదలపై పన్నుల భారం తగ్గించాలి; కరువులో ఆదుకోవాలి; చెరువులు, కాలువలతో జీవనోపాధి కల్పించాలి. ప్రజలు కూడా పాలకునిపై నమ్మకంతో, చట్టాలను గౌరవిస్తూ సహకరించాలి – తల్లిదండ్రులు–పిల్లల్లాంటి నమ్మకం, ప్రేమ ఉండాలి","ఆ) 1) తనకంటే గొప్పవాళ్ళ పట్ల ఎంతో భక్తి (గౌరవం) తో ఉండాలి 2) సమానుల పట్ల మనసులో స్నేహభావంతో ఉండాలి 3) తనకంటే తక్కువవారి పట్ల దయతో ఉండాలి 4) శీర్షిక: \"మనిషి నడవడి\" / \"ఎవరితో ఎలా ఉండాలి\""]],["ఇ) అపరిచిత గద్యం, ఈ) అర్థసందర్భాలు, ఉ) ఏకవాక్య; వ్యక్తీకరణ అ) (పుట 105)",["ఇ) 1) శ్రీకృష్ణదేవరాయలతో 2) ముఖప్రీతి కోసం ఎవరినీ పొగడడు; మంచిచెడులు గుర్తించి ఉద్యోగులను గౌరవిస్తాడు; సహాయం కోరితే సంపూర్ణంగా సహాయం చేస్తాడు 3) సత్రాలు కట్టించి ప్రతిరోజూ వేలమందికి అన్నదానం చేయించాడు 4) ఒకరి సలహా లేకుండానే చిత్తశుద్ధితో పనిచేసే ఉద్యోగులను సమృద్ధిగా ఆదరించేవాడు 5) ప్రభువుల గుణగణాలు, వైరాలు, వైషమ్యాలను దగ్గర నుండి సునిశితంగా పరిశీలించగలిగాడు","ఈ) 1) \"శరమాఁగి కాఁడ విడుచు వింటివాఁడు వోలె\" – శ్రీకృష్ణదేవరాయలు, ఆముక్తమాల్యద చతుర్థాశ్వాసం, రాజధర్మం పాఠం. సందర్భం: అపరాధిని శిక్షించే విధానం గురించి యామునాచార్యుడు కుమారునికి చెప్పిన సందర్భం. అర్థం: విలుకాడు గురి కుదిరేదాకా బాణం ఆపి సరైన సమయంలో విడిచినట్లు","2) \"ఏడు దీవులు గొన్న సమృద్ధి లేదు\" – రాజధర్మం (ఆముక్తమాల్యద). సందర్భం: వలస వెళ్ళిన ప్రజల ఆస్తులను దోచుకునే నక్కలాంటి అధికారులు గల రాజు గురించి చెప్పిన సందర్భం. అర్థం: అలాంటి రాజు ఏడు ద్వీపాలు జయించినా సంపద నిలవదు","3) \"చతురవృత్తి జరించుట నీతి జేనికిన్\" – రాజధర్మం. సందర్భం: హితులు, హితాహితులు, అహితులు అనే మూడు రకాల అనుచరుల పట్ల రాజు ఎలా ఉండాలో చెప్పిన సందర్భం. అర్థం: నేర్పుగా ప్రవర్తించడమే రాజుకు నీతి","4) \"బహిరంతరరులపై దృష్టి వలయు\" – రాజధర్మం. సందర్భం: ఎలుగుబంటి లాగా రాజు జాగరూకుడై ఉండాలని చెప్పిన సందర్భం. అర్థం: బయటి, లోపలి శత్రువులపై రాజు దృష్టి ఉంచాలి","ఉ) 1) శ్రీకృష్ణదేవరాయల \"ఆముక్తమాల్యద\" చతుర్థాశ్వాసం నుండి 2) కాపురుషులకు (చెడ్డవారికి) 3) విసుగు లేకుండా, ఎలుగుబంటిలా జాగరూకతతో, ప్రజలను కన్నబిడ్డల్లా కాపాడాలి","అ) 1) చెడ్డవారిపై ముఖ్యమైన పనులు, బాధ్యతలు (కార్యభారం) పెట్టకూడదు. వారు అధికారాన్ని దుర్వినియోగం చేసి ప్రజలను బాధిస్తారు, రాజ్యానికి చెడ్డపేరు తెస్తారు. గుణహీనుణ్ణి మంత్రిగా చేస్తే గుమ్మడికాయంత ముత్యంలా భారమై రాజే అతనికి లోబడాల్సి వస్తుంది","2) తప్పు చేసినవారిని వెంటనే కోపంతో దండించకూడదు. సమయం వచ్చేదాకా కోపాన్ని అదుపులో ఉంచుకోవాలి. విలుకాడు గురి కుదిరేదాకా బాణాన్ని ఆపి సరైన సమయంలో విడిచినట్లు, రాజు తగిన సమయం చూసి దోషిని శిక్షించాలి. చాడీలు చెప్పేవారి మాటలను పరీక్షించి, అబద్ధమైనా వెంటనే తొలగించక ప్రమాదం లేని చోట నియమించి కనిపెట్టాలి"]],["వ్యక్తీకరణ అ3), ఆ), ఇ); పదజాలం (పుట 106)",["అ) 3) చిత్తశుద్ధితో పనిచేసి రాజ్యానికి మేలు చేసే హితుడిని గుర్తించాలి. అతడు అడగకుండా, ఇంకొకరు చెప్పకుండానే, అతని ఊహకు అందనంత సొమ్ము ఒక్కసారిగా ఇవ్వాలి – పూత లేకుండానే ఒక్కసారిగా పుష్కలంగా కాసే పనసచెట్టులా. అది అతనికి కల నిజమైనట్లు సంభ్రమాశ్చర్యాలు కలిగించాలి","ఆ) 1) రాజు విసుగు లేకుండా ప్రజలను కాపాడాలి, ఆపన్నుల మొర తీర్చాలి; చెడ్డవారికి బాధ్యతలు ఇవ్వకూడదు. ఉద్యోగుల స్థాయిని క్రమంగా పెంచాలి, తగ్గించకూడదు. గుణహీనుణ్ణి మంత్రిగా చేయకూడదు. ధనంతో పాటు అధికారులకు తగిన జీతం, మిత్రత్వం ఇవ్వాలి; లోభం, క్రూరత్వం వద్దు. చాడీలు పరీక్షించాలి. చెరువులు, కాలువలు తవ్వించి పేదల పన్నులు తగ్గించాలి. కరువుతో వలస పోయిన ప్రజలను ఆదుకోవాలి. ముప్పాతిక విషయాలు స్వయంగా తెలుసుకోవాలి. ఎలుగుబంటిలా జాగ్రత్తగా ఉండాలి. సమయం చూసి శిక్షించాలి. హితులను గుర్తించి అనూహ్యంగా సత్కరించాలి","2) అనుచరులు మూడు రకాలు: 1) హితులు – వైద్యులు, జ్యోతిష్కులు, పండితులు, కవులు, పురోహితులు; వీరు ఎప్పుడూ రాజు మేలే కోరతారు 2) హితాహితులు – ధనం సమీకరించే అధికారులు; రాజుకు మేలు చేస్తూనే ధనం దొంగిలించి, దొరికితే శిక్షిస్తాడేమోనన్న భయంతో అహితులుగా మారతారు 3) అహితులు – ఎప్పుడూ తప్పు చేసి దొరికిపోయి, ఆస్తులు రాజ్యపరం కాగా అదును చూసి రాజును దెబ్బతీయాలనుకుంటారు. రాజు ముగ్గురితో వారికి తగినట్లు ప్రవర్తిస్తూ, పైకి అందరికీ హితునిగా కనిపిస్తూ నేర్పుగా ఉండాలి","3) కరువు కాటకాలతో పంటలు పోయి ప్రజలు ఊరు విడిచి వెళ్తే పాలకులు, అధికారులు వారిని తిరిగి రప్పించాలి; విత్తనాలు, నీటి వసతి, రుణాలు ఇచ్చి సాగుకు వసతులు కల్పించాలి; పన్నులు తగ్గించాలి/మాఫీ చేయాలి; ఆహారం, పశుగ్రాసం అందించాలి. వారు వదిలి వెళ్ళిన పశువులు, ధాన్యం అమ్ముకుని, ఇళ్ళ కలపను వంటచెరకుగా వాడుకునే అధికారులు యుద్ధభూమిలో శవాలను పీక్కుతినే నక్కల్లాంటివారు – అలాంటివారిని తొలగించాలి. నేటి కాలంలో పంటబీమా, ఉపాధి హామీ, నష్టపరిహారం వంటివి ఇవ్వాలి","ఇ) 1) వ్యాసం: నేను పాఠశాల నాయకుడినైతే – ప్రతి తరగతి నుండి ప్రతినిధులతో కమిటీ వేస్తాను; పరిశుభ్రత దినం (ప్రతి శనివారం), మొక్కల పెంపకం, గ్రంథాలయ వారం, క్రీడా పోటీలు, సాంస్కృతిక కార్యక్రమాలు నిర్వహిస్తాను; చదువులో వెనుకబడినవారికి \"మిత్ర బోధన\"; ప్రత్యేక అవసరాల పిల్లలకు సహాయ బృందం; ఫిర్యాదుల పెట్టె పెట్టి వారానికొకసారి ఉపాధ్యాయులతో చర్చిస్తాను. అందరి సలహాలు తీసుకుని, నిష్పక్షపాతంగా, బాధ్యతగా పనిచేస్తాను","2) అభినందన పత్రం: \"గౌరవనీయులైన మా గ్రామ సర్పంచ్ గారికి – మా టి.వి. పల్లిలో సిమెంటు రోడ్లు, తాగునీటి ట్యాంకు, వీధిదీపాలు, పాఠశాలకు ప్రహరీగోడ నిర్మించి గ్రామ రూపురేఖలు మార్చారు. కరోనా సమయంలో పేదలకు సరుకులు అందించారు. మీ సేవలకు గ్రామ ప్రజలు, విద్యార్థులు హృదయపూర్వక అభినందనలు తెలుపుతున్నారు.\"","పదజాలం అ) 1) స్వప్నం = కల – నా కల నిజమైంది 2) ఆస్థ = శ్రద్ధ – శ్రద్ధగా చదివితే మార్కులు వస్తాయి 3) భిషక్కులు = వైద్యులు – వైద్యులు ప్రాణదాతలు 4) హితులు = మేలుకోరేవారు – మేలుకోరేవారి మాట వినాలి 5) మృషలు = అబద్ధాలు – అబద్ధాలు చెప్పకూడదు","ఆ) 1) కల = స్వప్నం, కలలు 2) బృందం = గుంపు, సమూహం 3) క్షితి = భూమి, ధరణి 4) వ్రాతము = సమూహం, సముదాయం","ఇ) 1) వృద్ధి – అ (అభివృద్ధి, వడ్డీ, సంతోషం) 2) నయం – ఈ (నీతి, మృదువు, అందం) 3) ఋతం – ఆ (సత్యం, నీరు, సత్ప్రవర్తన) 4) కాడ – ఉ (తొడిమ, బాణం) 5) శరం – ఇ (రెల్లు, బాణం, నీరు)"]],["వ్యుత్పత్త్యర్థాలు, వికృతులు; సంధులు (పుట 107)",["ఈ) 1) పురోహితుడు – ముందుండి హితమును కోరువాడు 2) మంత్రి – మంత్రము (ఆలోచన) చేయువాడు 3) నృశంస్యము – నరులను హింసించుట (క్రూరత్వం) 4) భూరుహము – భూమి నుండి పుట్టునది (చెట్టు)","ఉ) 1) మౌక్తికం – ముత్తెము 2) పశువు – పసరము 3) ద్వీపం – దీవి 4) సత్త్వం – సత్తువ 5) నిద్ర – నిదుర","అ) 1) ఎవ్వాడు = ఏ + వాడు (త్రిక సంధి) 2) గుణాతీతుడు = గుణ + అతీతుడు (సవర్ణదీర్ఘ సంధి) 3) ఒకింత = ఒక + ఇంత (అకార సంధి) 4) దీవులుగొన్న = దీవులు + కొన్న (గసడదవాదేశ సంధి) 5) మృషయేని = మృష + ఏని (యడాగమ సంధి)","ఆ) పట్టిక: ఎదఁగోరు = ఎదన్ + కోరు (సరళాదేశ సంధి); ఎత్తటి = ఏ + తటి (త్రిక సంధి); తదంతరము = తత్ + అంతరము (జశ్త్వ సంధి); కన్నొకటి = కన్ను + ఒకటి (ఉకార సంధి); వాడువోలె = వాడు + పోలె (గసడదవాదేశ సంధి)"]],["ఇ, ఈ) సమాసాలు; శ్లేషాలంకారం (పుట 108)",["ఇ) 1) హితాహితులు – హితులును, అహితులును (ద్వంద్వ సమాసం) 2) అర్థధర్మాలు – అర్థమును, ధర్మమును (ద్వంద్వ సమాసం) 3) గుమ్మడికాయ – గుమ్మడి అను పేరుగల కాయ (సంభావనా పూర్వపద కర్మధారయ) 4) ఏడుదీవులు – ఏడు సంఖ్య గల దీవులు (ద్విగు సమాసం) 5) చతురవృత్తి – చతురమైన వృత్తి (విశేషణ పూర్వపద కర్మధారయ)","ఈ) పట్టిక: కలని నక్క – కలని యందు నక్క (సప్తమీ తత్పురుష); పెలుకన్ను – పెలుయైన కన్ను (విశేషణ పూర్వపద కర్మధారయ); దేశవైశాల్యం – దేశము యొక్క వైశాల్యం (షష్ఠీ తత్పురుష); అలోభము – లోభము కానిది (నఞ్ తత్పురుష); దుష్టప్రవర్తకుడు – దుష్టమైన ప్రవర్తన కలవాడు (బహువ్రీహి సమాసం)","ఉ) 1) యమకాలంకారం – \"లేమా\" అనే అక్షరాల సముదాయం రెండుసార్లు వేర్వేరు అర్థాల్లో వచ్చింది: లేమా = ఓ స్త్రీ! / లేమా = మేము (గెలువ)లేమా? 2) యమకాలంకారం – \"ప్రాయము\" రెండుసార్లు: మొదటిది = వయస్సు (యౌవనం), రెండోది = సమానం (నీటి అలలతో సమానం – చంచలం). (ఒకే పదానికి రెండు అర్థాలు స్ఫురిస్తే శ్లేష; అక్షరాల సముదాయం అర్థభేదంతో మళ్ళీ మళ్ళీ వస్తే యమకం.)"]],["కంద పద్య లక్షణాలు; ప్రాజెక్టుపని (పుట 109)",["కంద పద్యం \"ధనముఖ్యము కేవల మే…\" గణవిభజన: ధనము (నల)","ఖ్యముకే (స)","వలమే (స) || పనికిం (స)","గాదా (గగ)","గలిగి (నల)","పలువురు (నల)","ప్రభువుల్ (స) – 1వ పాదం 3 గణాలు, 2వ పాదం 5 గణాలు; ప్రాస \"న\"; 2వ పాదం చివర గురువు; 6వ గణం నల","లక్షణాలు: భ, జ, స, నల, గగ చతుర్మాత్రా గణాలు; 1, 3 పాదాల్లో 3 గణాలు, 2, 4 పాదాల్లో 5 గణాలు; ప్రాస నియమం; 2, 4 పాదాల చివర గురువు; 2, 4 పాదాల్లో 1వ, 4వ గణాల మొదటి అక్షరాలకు యతి; 6వ గణం జ లేదా నల; బేసి గణాల్లో జ గణం రాదు","ప్రాజెక్టు – అష్టదిగ్గజ కవులు: అల్లసాని పెద్దన (మనుచరిత్ర), నంది తిమ్మన (పారిజాతాపహరణం), ధూర్జటి (శ్రీకాళహస్తి మాహాత్మ్యం), మాదయగారి మల్లన (రాజశేఖర చరిత్ర), అయ్యలరాజు రామభద్రుడు (రామాభ్యుదయం), పింగళి సూరన (కళాపూర్ణోదయం, రాఘవపాండవీయం), రామరాజభూషణుడు (వసుచరిత్ర), తెనాలి రామకృష్ణుడు (పాండురంగ మాహాత్మ్యం)"]]]},{"id":"te10","no":10,"t":"కన్యాశుల్కం","m":[10],"ty":"నాటకం (సాంఘిక)","th":"సంఘసంస్కరణ – ఆధునిక విద్య","by":"గురజాడ అప్పారావు","sum":"కృష్ణారాయపురం అగ్రహారంలో అగ్నిహోత్రావధానులు ఇంట్లో జరిగే సన్నివేశం (ద్వితీయాంకం). కొడుకు వెంకటేశం శెలవులకు వస్తున్నాడని తల్లి వెంకమ్మ సంబరపడుతుంది. ఇంగ్లీషు చదువు వల్ల ఏటా డబ్బు ఖర్చవుతోందని, పరీక్ష తప్పాడని అగ్నిహోత్రావధానులు విసుక్కుంటాడు; \"నాలుగష్టాలు చెప్పేద్దును\" అంటాడు. డబ్బుకు బెంగపడకుండా పిల్లవాడిని చదివించాలని, అవసరమైతే తన పుట్టింటి భూమి అమ్మి చదివిస్తానని, మునసబీ, పోలీసు ఉద్యోగాలు ఇంగ్లీషు చదువుతోనే వస్తాయని వెంకమ్మ పట్టుపడుతుంది. వెంకటేశంతో పాటు వచ్చిన గిరీశం తాను మేష్టరునని, డిప్టీ కలెక్టరు గారి పిల్లలకు చదువు చెప్పానని గొప్పలు చెప్పుకుంటూ ఇంగ్లీషు మాటలతో అందరినీ బోల్తా కొట్టిస్తాడు; వెంకటేశాన్ని ప్రశ్నలు అడిగి తన ప్రతిభ చూపుతాడు. తన చిన్న కూతురిని అరవయ్యేళ్ళు దాటిన లుబ్ధావధానులకు కన్యాశుల్కానికి ఇచ్చే సంబంధం ఖాయం చేశానని, \"తాంబూలం ఇచ్చేశాను, ఇహ తన్నుకు చావండి\" అని అగ్నిహోత్రావధానులు మొండిగా అంటాడు; బావమరిది కరటకశాస్త్రి దానిని వ్యతిరేకిస్తాడు. కన్యాశుల్కం, బాల్యవివాహాల వంటి దురాచారాలను, మేకవన్నె పులుల్లాంటి గిరీశం వంటి వారిని గురజాడ వ్యంగ్యంగా చూపించారు.","pts":["రచయిత: గురజాడ అప్పారావు – విశాఖపట్నం దగ్గర రాయవరం; తల్లిదండ్రులు కౌసల్యమ్మ, వెంకటరామదాసు; \"ఆధునిక సాహిత్యానికి వేగుచుక్క\".","రచనలు: కన్యాశుల్కం; కొండుభట్టీయం, బిల్హణీయం (అసంపూర్ణ నాటకాలు); ముత్యాలసరాలు (కవిత); దిద్దుబాటు, పెద్ద మసీదు, మీ పేరేమిటి?, సంస్కర్త హృదయం, మెటిల్డా (కథలు).","కన్యాశుల్కం మొదటి ప్రదర్శన: 1892 ఆగస్టు 13, విజయనగరం; ముద్రణ 1897; రెండో కూర్పు 1909; వ్యావహారిక భాషలో (ఉత్తరాంధ్ర/విజయనగరం మాండలికం) రాసిన మొదటి సాంఘిక నాటకం.","పాఠం: కన్యాశుల్కం ద్వితీయాంకం, మొదటి సన్నివేశం (కృష్ణారాయపురం అగ్రహారం).","ప్రక్రియ: నాటకం – దశవిధ రూపకాల్లో ఉత్తమం; \"కావ్యేషు నాటకం రమ్యం\"; సమస్త సాహితీ ప్రక్రియల సమాహారం.","పాత్రలు: అగ్నిహోత్రావధానులు (మొండి, పాతకాలపు ఛాందసుడు, డబ్బాశ), వెంకమ్మ (ఆధునిక విద్య విలువ తెలిసిన తల్లి), వెంకటేశం (కొడుకు), గిరీశం (మోసగాడు, గొప్పలు చెప్పేవాడు), కరటకశాస్త్రి (వెంకమ్మ అన్న, విదూషకుడు).","కన్యాశుల్కం = పెళ్ళికూతురు తండ్రి వరుడి నుండి తీసుకునే డబ్బు (ముసలివాళ్ళు చిన్నపిల్లలను పెళ్ళాడేవారు).","\"ఆధునిక తెలుగు సాహిత్యానికి కన్యాశుల్కం అమ్మ.\""],"w":[["శిస్తు","పన్ను"],["వూష్టం","జ్వరం"],["ఖాయిలా","దివాళా"],["గొట్టికాయలు","గోలీకాయలు"],["తర్జుమా","అనువాదం"],["చప్పన్న భాషలు","56 భాషలు"],["విదూషకుడు","నాటకంలో హాస్యం పంచే నాయకుని సచివుడు"],["శషభిషలు","గొప్పలు / సందేహాలు"],["గణించు","లెక్కలోకి తీసుకొను"],["దమ్మిడి","పాతకాలపు చిన్న నాణెం"],["భోగట్టా","సమాచారం, విచారణ"],["విధాయకం","ఆచరించదగ్గది"],["గళగ్రాహి","తడబడకుండా చెప్పేవాడు"],["తోవ పెట్టడం","సాగనంపడం"],["ఖాయిదా","కట్టడి, అదుపు"]],"gr":{"t":"భాషాంశాలు","p":["పుంప్వాదేశ సంధి: కర్మధారయంలో \"ము\" వర్ణానికి \"పు\", \"ంపు\" ఆదేశం – ఆదరము + మాట = ఆదరపుమాట / ఆదరంపుమాట; నీలము + కండ్లు = నీలపుకండ్లు.","ఉత్ప్రేక్షాలంకారం: ధర్మసామ్యం వల్ల ఉపమేయాన్ని ఉపమానంగా ఊహించడం – \"ఈ వెన్నెల పాలవెల్లియో అన్నట్లున్నది\", \"ఆ ఏనుగు నడుస్తున్న కొండా అన్నట్లుంది\".","వ్యతిరేకార్థక వాక్యం: క్రియను వ్యతిరేకంగా మార్చడం – \"నాటక ప్రదర్శన జరిగింది\" → \"నాటక ప్రదర్శన జరగలేదు\".","వ్యావహారిక (మాండలిక) రూపాలు: వోఘాయిత్తం = అఘాయిత్యం; అగ్గురారం = అగ్రహారం; అంచూవుంఛారు = అంటూ ఉంటారు."]},"qa":[["కన్యాశుల్కం అంటే?","పెళ్ళికూతురి తండ్రి వరుడి నుండి డబ్బు తీసుకుని పిల్లను ఇవ్వడం (ఎక్కువగా ముసలివారికి)."],["అగ్నిహోత్రావధానులు ఇంగ్లీషు చదువు ఎందుకు వద్దన్నాడు?","ఏటా డబ్బు ఖర్చవుతుంది, భూమి కరిగిపోతుంది, వెంకటేశం పరీక్ష తప్పాడు; ఇంటి దగ్గరే వేదం (అష్టాలు) నేర్పవచ్చని."],["వెంకమ్మ ఇంగ్లీషు చదువు ఎందుకు కోరింది?","మునసబీ, పోలీసు వంటి కొత్త కొలువులు ఇంగ్లీషు చదువుతోనే వస్తాయి; గొట్టికాయలాడిన నేమానివారి అబ్బాయికి కూడా మునసబీ వచ్చింది."],["గిరీశం ఎలాంటివాడు?","మాటకారి, మోసగాడు; డిప్టీ కలెక్టరు పేరు చెప్పి గొప్పలు చెప్పుకుంటూ ఇంగ్లీషు మాటలతో అమాయకులను బోల్తా కొట్టించేవాడు."],["అగ్నిహోత్రావధానుల స్వభావం?","మొండివాడు, కోపిష్ఠి, డబ్బాశ గలవాడు, ఛాందసుడు; కన్యాశుల్కానికి కూతుర్ని ముసలివాడికి ఇవ్వడానికి సిద్ధపడ్డాడు."],["\"పుచ్చకాయల దొంగంటే భుజాలు తడుముకున్నట్టు\" అన్నది ఎవరు?","కరటకశాస్త్రి (అగ్నిహోత్రావధానులతో)."]],"act":"పాఠంలోని సన్నివేశాన్ని పాత్రలు పంచుకుని తరగతిలో నాటకంగా ప్రదర్శించండి; నేటి సమాజంలోని వరకట్నం దురాచారంపై చిన్న నాటిక రాయండి.","kn":"బాల్య వివాహ నిషేధ చట్టం, వరకట్న నిషేధ చట్టం (1961) – వరకట్నం ఇవ్వడం, తీసుకోవడం నేరం. చిలకమర్తి లక్ష్మీనరసింహం ప్రహసనాల్లో \"అల్లుడు గ్రహం\" (దశమగ్రహం) వ్యంగ్యం.","qz":[["కన్యాశుల్కం రచయిత?","గురజాడ అప్పారావు","కందుకూరి వీరేశలింగం","చిలకమర్తి లక్ష్మీనరసింహం","గుర్రం జాషువా"],["గురజాడ జన్మస్థలం?","రాయవరం (విశాఖ దగ్గర)","విజయనగరం","రాజమండ్రి","గుంటూరు"],["కన్యాశుల్కం మొదటి ప్రదర్శన?","1892, విజయనగరం","1909, విశాఖ","1897, మద్రాసు","1919, అమృత్‌సర్"],["ఈ పాఠం ప్రక్రియ?","నాటకం","కథ","ప్రబంధం","శతకం"],["గురజాడ కవితా సంపుటి?","ముత్యాలసరాలు","తొలకరి చినుకులు","ఖండ కావ్యములు","మట్టి మనిషి"],["వెంకటేశం తల్లి?","వెంకమ్మ","బుచ్చమ్మ","మధురవాణి","సుబ్బి"],["వెంకటేశానికి చదువు చెప్పే మేష్టరునని చెప్పుకున్నది?","గిరీశం","కరటకశాస్త్రి","సౌజన్యరావు","లుబ్ధావధానులు"],["\"నాటకంలో విదూషకుడు\" అని గిరీశం ఎవరిని పొగిడాడు?","కరటకశాస్త్రి","అగ్నిహోత్రావధానులు","వెంకటేశం","డిప్టీ కలెక్టరు"],["\"తాంబోలం యిచ్చేశాను, యిహ తన్నుకు చావండి\" అన్నది?","అగ్నిహోత్రావధానులు","వెంకమ్మ","గిరీశం","కరటకశాస్త్రి"],["వెంకమ్మ కొడుకు చదువుకు ఏం అమ్ముతానంది?","పుట్టింటివారు ఇచ్చిన భూమి","నగలు","ఇల్లు","ఆవులు"],["కన్యాశుల్కం ఏ భాషలో రచించారు?","వ్యావహారిక (విజయనగరం మాండలికం)","గ్రాంథిక భాష","సంస్కృతం","ఆంగ్లం"],["\"కావ్యేషు నాటకం రమ్యం\" అర్థం?","కావ్యాలన్నిటిలో నాటకం రమణీయం","నాటకం కష్టం","కావ్యాలు వద్దు","నాటకం పాతది"],["\"ఆధునిక తెలుగు సాహిత్యానికి అమ్మ\" ఏది?","కన్యాశుల్కం","ఆముక్తమాల్యద","మనుచరిత్ర","వేమన శతకం"],["\"ఓవర్‌కోట్\" కథ రచయిత?","నికొలాయ్ గొగోల్","మార్క్ ట్వయిన్","దాస్తోయవిస్కీ","షేక్‌స్పియర్"],["ఆదరము + మాట = ఆదరపుమాట – సంధి?","పుంప్వాదేశ సంధి","పడ్వాది సంధి","ప్రాతాది సంధి","లులనల సంధి"],["\"ఈ వెన్నెల పాలవెల్లియో అన్నట్లున్నది\" – అలంకారం?","ఉత్ప్రేక్ష","ఉపమ","రూపకం","శ్లేష"]],"wb":{"mis":"పుంప్వాదేశం కర్మధారయ సమాసంలోనే జరుగుతుంది (\"ము\" → \"పు/ంపు\"). వ్యతిరేకార్థకంలో క్రియనే మార్చాలి (\"జరిగింది\" → \"జరగలేదు\"); అర్థం మార్చే పదాలు చేర్చకూడదు.","qz":[["అభ్యంతరం విడదీస్తే?","అభి + అంతరం (యణాదేశ సంధి)","అభ్య + అంతరం","అ + భ్యంతరం","అభ + అంతరం"],["సావకాశం విడదీస్తే?","స + అవకాశం (సవర్ణదీర్ఘ)","సా + వకాశం","సవ + అకాశం","సా + అవకాశం"],["కళ్ళెదుట విడదీస్తే?","కళ్ళు + ఎదుట (ఉకార సంధి)","కళ్ళె + దుట","కళ్ళ + ఎదుట","కళ్ + ఎదుట"],["సరసము + మాట = ?","సరసపుమాట (పుంప్వాదేశ)","సరసమాట","సరసంమాట","సరసుమాట"],["\"కలిమిలేములు\" సమాసం?","ద్వంద్వ సమాసం","ద్విగు","బహువ్రీహి","షష్ఠీ"],["\"నూరురూపాయలు\" సమాసం?","ద్విగు సమాసం","ద్వంద్వ","రూపక","కర్మధారయ"],["\"లక్షాధికారి\" విగ్రహవాక్యం?","లక్షకు అధికారి (షష్ఠీ తత్పురుష)","లక్ష మరియు అధికారి","లక్షయైన అధికారి","లక్ష లేనివాడు"],["\"నాటక ప్రదర్శన జరిగింది\" – వ్యతిరేకార్థకం?","నాటక ప్రదర్శన జరగలేదు","నాటక ప్రదర్శన జరుగుతుంది","నాటకం బాగుంది","ప్రదర్శన జరిగిందా?"],["పద్యం – వికృతి?","పద్దెం","ప్రోలు","దరిసెనము","నీరు"],["\"కళ్ళు కాయలు కాచు\" అర్థం?","ఎంతో కాలంగా ఎదురుచూచు","కళ్ళు నొప్పి","నిద్రపోవు","ఏడ్చు"]],"pg":"112–127","f":"books/10/Class10_Telugu_Textbook_Sem1.pdf","p":120,"lb":"పాఠ్యపుస్తకం","ws":["అవగాహన – ప్రతిస్పందన: అ) ప్రశ్నలు (పుట 119)","ఆ) ప్రహసనం, ఇ) అపరిచిత గద్యం (పుట 120)","ఇ) గద్యం (మిగతా), ఈ) అర్థసందర్భాలు, ఉ) ఏకవాక్య; వ్యక్తీకరణ (పుట 121)","అర్థాలు, పర్యాయపదాలు, నానార్థాలు, ప్రకృతి–వికృతి (పుట 122)","జాతీయాలు, వ్యవహార రూపాలు; సంధులు, పుంప్వాదేశ సంధి (పుట 123)","పుంప్వాదేశ ఉదాహరణలు; ఆ) సమాసాలు; ఇ) ఉత్ప్రేక్ష; ఈ) వ్యతిరేకార్థక వాక్యాలు (పుట 124)","ప్రాజెక్టుపని (పుట 125)"]},"tg":[["అవగాహన – ప్రతిస్పందన: అ) ప్రశ్నలు (పుట 119)",["అ) 1) ప్రధాన ఇతివృత్తం: కన్యాశుల్కం అనే దురాచారం – డబ్బుకు ఆశపడి చిన్నపిల్లలను ముసలివాళ్ళకు ఇచ్చి పెళ్ళి చేయడం (బాల్య వివాహాలు, వృద్ధ వివాహాలు). దానితో పాటు ఆంగ్లవిద్య పట్ల ఆనాటి ఆలోచనలు, గిరీశం వంటి మోసగాళ్ళు, వేశ్యా సమస్య, కోర్టు వ్యవహారాలు – సమకాలీన సమాజాన్ని వ్యంగ్యంగా చిత్రించడం","2) ఆనాటి విజయనగరం ప్రాంతంలో వృద్ధులు డబ్బిచ్చి పసిపిల్లలను పెళ్ళాడడం, ఆ పిల్లలు చిన్న వయసులోనే వితంతువులై బాధపడడం గురజాడను కదిలించాయి. ఇలాంటి సంఘటనలు, సంఘసంస్కర్తల (వీరేశలింగం) ఉద్యమం, ప్రజలకు అర్థమయ్యే భాషలో దురాచారాన్ని ఎత్తి చూపాలనే తపన ఈ నాటక రచనకు ప్రేరణ"]],["ఆ) ప్రహసనం, ఇ) అపరిచిత గద్యం (పుట 120)",["ఆ) 1) ఇంద్రుడు, నారదుడు 2) వరకట్నం (అల్లుళ్ళు కట్నకానుకల కోసం ఆడపిల్లల తండ్రులను పీడించడం) 3) దశమగ్రహం – అల్లుడు గ్రహం (జామాత గ్రహం); ఎప్పుడూ వక్రంగా, క్రూరంగా ఉంటుంది; ఆడపిల్లల తల్లిదండ్రులను జీవితాంతం బాధిస్తుంది 4) ఉదా: శని గ్రహం కంటే అల్లుడు గ్రహం ఎందుకు చెడ్డది?","ఇ) 1) నికొలాయ్ గొగోల్ 2) గొగోల్, మార్క్ ట్వయిన్ (ప్రాంతీయ జీవిత చిత్రణ) రచయితల ప్రభావం"]],["ఇ) గద్యం (మిగతా), ఈ) అర్థసందర్భాలు, ఉ) ఏకవాక్య; వ్యక్తీకరణ (పుట 121)",["ఇ) 3) గురజాడ అప్పారావు \"కన్యాశుల్కం\" 4) ఉదా: ఆధునిక రష్యన్ సాహిత్యం ఏ కథ నుండి పుట్టిందని దాస్తోయవిస్కీ అన్నాడు?","ఈ) 1) \"డబ్బు ఖర్చయిపోతుందని మీకు బెంగా…\" – గురజాడ అప్పారావు, కన్యాశుల్కం నాటకం ద్వితీయాంకం. సందర్భం: ఇంగ్లీషు చదువుకు ఏటా డబ్బు ఖర్చవుతోందని విసుక్కుంటున్న భర్త అగ్నిహోత్రావధానులతో వెంకమ్మ అన్న మాట","2) \"పుస్తకం చేతబడితే వేళ్ళకి అంటుకుపోవాలి\" – కన్యాశుల్కం. సందర్భం: గొట్టికాయలాడకుండా తమ అబ్బాయిని కట్టడి చేయమని అగ్నిహోత్రావధానులు అనగా, తన దగ్గర ఆటలు పనికిరావని, పుస్తకం చేతబడితే వదలకుండా చదివిస్తానని గిరీశం గొప్పగా చెప్పిన సందర్భం","3) \"తాంబోలం యిచ్చేశాను, యిహ తన్నుకు చావండి\" – కన్యాశుల్కం. సందర్భం: చిన్న కూతుర్ని అరవయ్యేళ్ళు దాటిన లుబ్ధావధానులకు ఇచ్చే సంబంధాన్ని కరటకశాస్త్రి, వెంకమ్మ వ్యతిరేకించగా అగ్నిహోత్రావధానులు మొండిగా అన్న మాట","ఉ) 1) విజయనగరం (ఉత్తరాంధ్ర) వ్యావహారిక మాండలికంలో 2) \"నల దమయంతులిద్దరు మనఃప్రభవానల…\" (ఆంధ్ర మహాభారతం, అరణ్యపర్వం) 3) కరటకశాస్త్రి","అ) 1) కరటకశాస్త్రి గిరీశాన్ని తొందరగా తోవ పెట్టాలనుకున్నాడు. గిరీశం మాటకారి, మోసగాడు; వెంకటేశానికి సరైన చదువు చెప్పకుండా గొప్పలు చెప్పుకుంటున్నాడు; ఆ ఇంట్లో ఎక్కువకాలం ఉంటే తన పథకం (సంబంధం చెడగొట్టే ఆలోచన) బయటపడి మోసం వస్తుందని భయపడ్డాడు","2) అగ్నిహోత్రావధానులు మొండివాడు, కోపిష్ఠి, ఛాందసుడు. ఇంగ్లీషు చదువును వ్యతిరేకిస్తాడు; డబ్బు ఖర్చంటే భయపడతాడు; ఇంటికి వచ్చిన గిరీశంపై \"గూబ గలగొడతాను\" అని విరుచుకుపడతాడు. డబ్బుకు ఆశపడి చిన్న కూతుర్ని ముసలివాడికి ఇవ్వడానికి తాంబూలం పుచ్చుకున్నాడు; ఎవరి మాటా వినడు","3) గిరీశం మాటకారి, మోసగాడు, అవకాశవాది. డిప్టీ కలెక్టరు పేరు చెప్పుకుని గొప్పలు పోతాడు; ఇంగ్లీషు ముక్కలు (\"డామిట్\") విసిరి అమాయకులను బోల్తా కొట్టిస్తాడు; కరటకశాస్త్రిని పొగిడి దగ్గరవుతాడు; భోజనం, డబ్బుల కోసం కాదని చెబుతూనే ఆ ఇంట్లో తిష్ట వేయాలని చూస్తాడు. \"మేకవన్నె పులి\" లాంటివాడు","ఆ) 1) గురజాడ ఉద్దేశం: కన్యాశుల్కం వంటి దురాచారాలను రూపుమాపాలి; ఆడపిల్లలను డబ్బుకు అమ్మడం పాపం. ఆధునిక (ఇంగ్లీషు) విద్య కొత్త ఉద్యోగాలకు, సమాజ పురోగతికి అవసరం – వెంకమ్మ వంటి సామాన్య గృహిణి కూడా దాన్ని గ్రహించింది. ఛాందసత్వం, మొండితనం (అగ్నిహోత్రావధానులు) సమాజాన్ని వెనక్కి లాగుతాయి. గిరీశం వంటి మోసగాళ్ళ పట్ల జాగ్రత్తగా ఉండాలి – పైపై మెరుగులకు మోసపోకూడదు. ప్రజల భాషలోనే సాహిత్యం ఉండాలి. హాస్యం, వ్యంగ్యం ద్వారా సంఘసంస్కరణ సందేశాన్ని అందించారు","2) వెంకమ్మ కాలం మారుతోందని గ్రహించింది. మునసబీ, పోలీసు వంటి కొలువులు ఇంగ్లీషు చదువుతోనే వస్తాయని, గొట్టికాయలాడిన నేమానివారి అబ్బాయి కూడా మునసబు అయ్యాడని ఉదాహరణ చెప్పింది. కొడుకు పెద్ద ఉద్యోగం చేసి అప్పులిచ్చి అగ్రహారం భూములన్నీ కొనాలని, తండ్రిలా వేదం వల్లించుకుంటూ పేదరికంలో బతకకూడదని ఆశించింది. డబ్బుకు వెనుకాడితే తన పుట్టింటి భూమి అమ్మి చదివిస్తానంది. కొడుకుకు దూరంగా ఉండే బాధనూ భరించింది. ఇది తల్లి ముందుచూపు, ఆధునిక విద్యపై నమ్మకానికి నిదర్శనం","3) ఆధునిక విద్య వల్ల శాస్త్రీయ దృక్పథం పెరుగుతుంది; మూఢనమ్మకాలు, దురాచారాలు తొలగుతాయి; ఉద్యోగ, ఉపాధి అవకాశాలు పెరుగుతాయి; ఆర్థిక స్వావలంబన వస్తుంది; ప్రపంచ జ్ఞానం, సాంకేతికత, వైద్యం అందుతాయి; స్త్రీ విద్యతో కుటుంబాలు బాగుపడతాయి; ప్రజాస్వామ్య విలువలు, హక్కులపై అవగాహన కలుగుతుంది; దేశ ప్రగతికి నిపుణులు తయారవుతారు. అయితే మన భాష, సంస్కృతి, విలువలను కూడా కాపాడుకోవాలి","ఇ) 1) కథ: కృష్ణారాయపురం అగ్రహారంలో అగ్నిహోత్రావధానులు, వెంకమ్మ దంపతులు ఉండేవారు. కొడుకు వెంకటేశం పట్నంలో ఇంగ్లీషు చదువుతున్నాడు. శెలవులకు వస్తున్న కొడుకు కోసం తల్లి ఎదురుచూస్తుంటే, తండ్రి చదువుకు డబ్బు దండుగని గొణుగుతున్నాడు. వెంకమ్మ కొడుకు చదువు కోసం తన భూమి అమ్ముతానంది. ఇంతలో వెంకటేశం తన మేష్టరు గిరీశంతో వచ్చాడు. గిరీశం గొప్పలు, ఇంగ్లీషు మాటలు చూసి తండ్రి మండిపడ్డాడు, తల్లి మురిసిపోయింది. తండ్రి చిన్న కూతుర్ని అరవయ్యేళ్ళ ముసలివాడికి ఇచ్చే సంబంధం ఖాయం చేశానన్నాడు; కరటకశాస్త్రి అడ్డు చెప్పినా వినలేదు. ఇలా డబ్బాశ, ఛాందసత్వం ఆడపిల్లల జీవితాలను ఎలా పాడుచేస్తాయో ఈ కథ చెబుతుంది","2) కరపత్రం: \"ప్రేక్షక మహాశయులకు ఆహ్వానం! జి.ప.ఉ.పా., టి.వి. పల్లి విద్యార్థులు ప్రదర్శించే సాంఘిక నాటకం \"కన్యాశుల్కం\" (గురజాడ అప్పారావు) – తేదీ: ___, సాయంత్రం 6 గంటలకు, పాఠశాల ఆవరణలో. ముఖ్య అతిథి: మండల విద్యాశాఖాధికారి. హాస్యం, సందేశం కలగలిసిన ఈ నాటకాన్ని కుటుంబ సమేతంగా వచ్చి తిలకించి ప్రోత్సహించగోర్తాం. ప్రవేశం ఉచితం. – నిర్వాహకులు\"","పదజాలం అ) 1) శిస్తు = పన్ను – సకాలంలో పన్ను చెల్లించాలి"]],["అర్థాలు, పర్యాయపదాలు, నానార్థాలు, ప్రకృతి–వికృతి (పుట 122)",["అ) 2) వూష్టం = జ్వరం – జ్వరం వస్తే విశ్రాంతి తీసుకోవాలి 3) ఖాయిలా = దివాళా – దివాళా తీసిన కంపెనీలు మూతపడతాయి 4) గొట్టికాయలు = గోలీకాయలు – పిల్లలు గోలీలు ఆడుతున్నారు 5) తర్జుమా = అనువాదం – ఈ కథను తెలుగులోకి అనువదించు","ఆ) 1) ఉత్తరం = జాబు, లేఖ 2) జీతం = వేతనం, భృతి 3) సొమ్ము = ధనం, ద్రవ్యం","ఇ) 1) తల్లి – ఆ (మాత, పెద్దది, పూజ్యురాలు) 2) పెద్ద – ఈ (వృద్ధుడు, గొప్పవాడు, జ్యేష్ఠుడు) 3) అధికారం – అ (దొరతనం, అధ్యక్షత, ఆశ్రయం) 4) అర్థము – ఉ (ధనము, కారణం, శబ్దార్థం) 5) సంతోషం – ఇ (ఆనందం, తృప్తి, ధైర్యం)","ఈ) ప్రకృతి – వికృతి: పద్యం – పద్దెం; పురము – ప్రోలు; దర్శనం – దరిసెనము; నీరము – నీరు; ఛాత్రుడు – చట్టు"]],["జాతీయాలు, వ్యవహార రూపాలు; సంధులు, పుంప్వాదేశ సంధి (పుట 123)",["ఉ) 1) కళ్ళు కాయలు కాచు – ఎంతో కాలం ఎదురుచూడడం; కొడుకు కోసం తల్లి కళ్ళు కాయలు కాచేలా ఎదురుచూసింది 2) చెవి కోసుకొను – అమితంగా ఇష్టపడటం; మా తాతయ్య హరికథ అంటే చెవి కోసుకుంటాడు 3) కడుపులో పెట్టుకొను – ఆప్యాయంగా చూసుకోవడం; గురువు శిష్యుల్ని కడుపులో పెట్టుకుని చదువు చెప్పాడు 4) చర్మం చెప్పులు కుట్టించు – ఎంతో కృతజ్ఞత చూపడం (ప్రాణమిచ్చినంత); ఆయన చేసిన సాయానికి నా చర్మం వలిచి చెప్పులు కుట్టించినా రుణం తీరదు","ఊ) 1) వోఘాయిత్తం – అఘాయిత్యం 2) అంచూవుంఛారు – అంటూ ఉంటారు 3) అగ్గురారం – అగ్రహారం 4) అప్పచ్చము – అపభ్రంశం (అపశబ్దం – ఉపాధ్యాయునితో సరిచూడండి) 5) వచ్చావషోయ్ – వచ్చావా ఓయ్ 6) రాజమహేంద్రంషండీ – రాజమహేంద్రవరం అండీ","అ) 1) అభ్యంతరం = అభి + అంతరం (యణాదేశ సంధి) 2) రవ్వంత = రవ్వ + అంత (అకార సంధి) 3) సావకాశం = స + అవకాశం (సవర్ణదీర్ఘ సంధి) 4) కళ్ళెదుట = కళ్ళు + ఎదుట (ఉకార సంధి)"]],["పుంప్వాదేశ ఉదాహరణలు; ఆ) సమాసాలు; ఇ) ఉత్ప్రేక్ష; ఈ) వ్యతిరేకార్థక వాక్యాలు (పుట 124)",["పుంప్వాదేశం: 1) అప్పచ్చపుమాటలు = అప్పచ్చము + మాటలు 3) ఉన్నతపుగొడుగు = ఉన్నతము + గొడుగు 4) కోమలపుజ్ఞానం = కోమలము + జ్ఞానం 5) సరసపుమాట = సరసము + మాట – సూత్రం: కర్మధారయమునందు \"ము\" వర్ణకమునకు పు, ంపులగు","ఆ) 1) నూరురూపాయలు – నూరు సంఖ్య గల రూపాయలు (ద్విగు) 2) దొడ్డప్రభువు – దొడ్డవాడైన ప్రభువు (విశేషణ పూర్వపద కర్మధారయ) 3) కలిమిలేములు – కలిమియు, లేమియు (ద్వంద్వ) 4) లక్షాధికారి – లక్షకు అధికారి (షష్ఠీ తత్పురుష)","ఇ) మూడూ ఉత్ప్రేక్షాలంకారాలు: 1) వెన్నెలను పాలసముద్రంగా 2) ఆకాశం కాటుక కురిపిస్తున్నట్లుగా (చీకటి) 3) ఏనుగును నడిచే కొండగా ఊహించారు","ఈ) 1) ఆ కప్పు ఖాళీగా లేదు 2) వానలు ఎక్కువగా పడలేదు 3) ఆ చిత్రాన్ని చూసి అందరూ మెచ్చుకోలేదు 4) నాటక ప్రదర్శన జరగలేదు 5) ఆలోచింపజేసే ప్రక్రియ నాటకం అని భావించలేదు"]],["ప్రాజెక్టుపని (పుట 125)",["1) మీ ప్రాంత (గూడూరు/నెల్లూరు) నటులు, నాటక సమాజాల వివరాలు – పేరు, ప్రదర్శించిన నాటకాలు, పురస్కారాలు – పట్టికగా సేకరించండి (ఉదా: సురభి నాటక సమాజం, ఊరి భజన/నాటక మండళ్ళు) లేదా 2) వరకట్నం / బాల్య వివాహం / బాలకార్మికత్వం వంటి దురాచారంపై 3–4 పాత్రలతో నాటిక రాసి ప్రదర్శించండి"]]]},{"id":"te11","no":11,"t":"యుద్ధ విజేత","m":[11],"ty":"వచన కవిత","th":"శాంతి – యుద్ధ వ్యతిరేకత","by":"నేతల ప్రతాప్ కుమార్","sum":"రోహిణీ నది జలాల వివాదంలో యుద్ధం చేయాలన్న శాక్యుల తీర్మానాన్ని సిద్ధార్థుడు వ్యతిరేకించి, యుద్ధాన్ని నివారించడానికి ఇల్లు వదిలి వెళ్ళిపోయిన నేపథ్యంలో రాసిన కవిత ఇది. యుద్ధంలో ఎవరో ఒకరు గెలుస్తారు, ఎవరో ఓడతారు; దద్దమ్మ కూడా గెలవవచ్చు. కానీ యుద్ధంలో గెలిచినవాడి కంటే యుద్ధాన్నే గెలిచినవాడే నిజమైన విజేత – అతడు ఎప్పటికీ మానవాళి హృదయ విజేత. బలవంతుడు బలహీనుడిపై గెలవడం గెలుపు కాదు; రెండు పశువులు కుమ్ముకున్నాక బలమైనది కొమ్ములెగరేసినట్లే. రాజ్యం, రమణి, పదవి, పౌరుషం కోసం సాటిమనిషిని శత్రువన్నారు; పచ్చని నేలకు నెత్తుటి తిలకం దిద్దారు. బాణాలతో అప్పుడు, బాంబులతో ఇప్పుడు చంపుకోవడం, పసిపిల్లల చిరునవ్వులు చెరిపేయడం, పూలు, పక్షులు, నెమళ్ళు, జింకలు – సకల ప్రకృతిని ధ్వంసం చేయడమే యుద్ధం. అలాంటి యుద్ధంలో గెలుపు వీరత్వం కాదు, పశుత్వం. అందుకే అశోకుడు యుద్ధంలో గెలిచి పశ్చాత్తాపపడ్డాడు; బుద్ధుడు రాజ్యభోగాలు త్యజించి అసలు యుద్ధాన్నే గెలిచాడు.","pts":["కవి: నేతల ప్రతాప్ కుమార్ (12.08.1965 – 05.05.2021) – నిడదవోలు మండలం విఘ్నేశ్వరం; తల్లిదండ్రులు శాంతకుమారి, సత్యం.","రచనలు: పాలకంకి, దళితనానీలు, బౌద్ధభాషితాలు, బుద్ధిజం–శాస్త్రీయత, నా భూమికి నేనే, సమతావసంత గానం, పిల్లల కోసం అంబేడ్కర్ కథ; విమల శాంతి జాతీయ కవితా పురస్కారం.","పాఠం \"సమతా వసంత గానం\" కవితా సంపుటి నుండి.","ప్రక్రియ: వచన కవిత – ఛందో నియమాలు లేకుండా లయాత్మకంగా సాగే కవిత; విషయ ప్రధానం; నిత్యజీవిత పదాలు; అంత్యానుప్రాసల సొబగు.","నేపథ్యం: రోహిణీ నది జలవివాదం – శాక్యుల యుద్ధ తీర్మానాన్ని సిద్ధార్థుడు వ్యతిరేకించి గృహత్యాగం చేశాడు.","కేంద్ర భావం: \"యుద్ధంలో గెలిచినవాడికంటే యుద్ధాన్ని గెలిచినవాడే నిజమైన విజేత\".","అశోకుడు – యుద్ధంలో గెలిచి పశ్చాత్తాపం; బుద్ధుడు – యుద్ధాన్నే గెలిచాడు.","సెప్టెంబర్ 21 – అంతర్జాతీయ శాంతి దినోత్సవం."],"w":[["తథ్యం","నిజం, తప్పనిసరి"],["దరహాసం","చిరునవ్వు"],["వ్యూహం","యుద్ధ ప్రణాళిక"],["త్యజించు","విడిచిపెట్టు"],["దద్దమ్మ","ఎందుకూ పనికిరానివాడు"],["అంగబలం","సైన్యబలం"],["అర్థబలం","ధనబలం"],["ఉన్మాది","పిచ్చివాడు"],["రమణి","స్త్రీ"],["మోము","ముఖం"],["పశ్చాత్తాపం","చేసిన తప్పుకు బాధపడటం"],["సమరం","యుద్ధం"],["సంగ్రామం","యుద్ధం"],["యశస్సు","కీర్తి"],["చవటతనం","పనికిమాలినతనం"]],"gr":{"t":"భాషాంశాలు","p":["అతిశయోక్తి అలంకారం: వస్తువు ఆకారం, స్వభావం, గుణాన్ని ఉన్నదానికంటే ఎక్కువ చేసి చెప్పడం (గోరంతను కొండంత) – \"మా నూతిలో నీళ్ళు పాతాళానికి చేరాయి\".","లాటానుప్రాసం: ఒకే పదం తాత్పర్యభేదంతో మళ్ళీ రావడం – \"అమ్మ చూపించే ప్రేమ ప్రేమ\", \"మలయగిరి నుండి వచ్చే గాలి గాలి\".","ఆమ్రేడిత సంధి: ఒక్క + ఒక్క = ఒక్కొక్క. పుంప్వాదేశం: మాంసము + ముద్ద = మాంసపుముద్ద. గుణ సంధి: యుద్ధ + ఉన్మాది = యుద్ధోన్మాది.","వచన కవితలో అంత్యానుప్రాసం: \"…గెలవడం / …గెలవడం\", \"…యుద్ధం / …యుద్ధం\"."]},"qa":[["నిజమైన విజేత ఎవరు?","యుద్ధంలో గెలిచినవాడు కాదు, యుద్ధాన్నే గెలిచినవాడు (యుద్ధం జరగకుండా చేసినవాడు)."],["యుద్ధాలు ఎందుకు జరుగుతాయి?","రాజ్యం, రమణి, పదవి, పౌరుషం, రాజ్యవిస్తరణ, జాతి అహంకారం కోసం."],["యుద్ధాల వల్ల ప్రకృతికి నష్టం?","పూలు, పక్షులు, నెమళ్ళు, జింకలు – సకల చరాచర ప్రకృతి ధ్వంసమవుతుంది; పచ్చని నేల రక్తసిక్తమవుతుంది."],["వీరత్వం కానిదేది?","నిస్సహాయులను, ప్రకృతిని నాశనం చేసే యుద్ధంలో గెలవడం – అది పశుత్వం, చవటతనం."],["పశ్చాత్తాపం ప్రకటించిన రాజు?","అశోకుడు (కళింగ యుద్ధం తర్వాత)."],["రాజ్యసుఖాలు వదిలి వెళ్ళింది ఎవరు?","సిద్ధార్థుడు (బుద్ధుడు)."]],"act":"\"యుద్ధం వద్దు – శాంతి ముద్దు\" అనే అంశంపై పోస్టర్లు తయారు చేసి సెప్టెంబర్ 21 (అంతర్జాతీయ శాంతి దినోత్సవం) న పాఠశాలలో ప్రదర్శించండి.","kn":"థింసా నృత్యం – విశాఖ ఏజెన్సీ (అరకు) గిరిజన బృంద నృత్యం. అమీన్ పీర్ దర్గా – కడప; నవంబర్‌లో ఉర్సు. శాలిహుండం – శ్రీకాకుళం జిల్లా బౌద్ధ క్షేత్రం (గిడుగు రామ్మూర్తి 1919లో కనుగొన్నారు).","qz":[["\"యుద్ధ విజేత\" కవి?","నేతల ప్రతాప్ కుమార్","వై.సి.వి. రెడ్డి","గుర్రం జాషువా","శ్రీశ్రీ"],["ఈ పాఠం ప్రక్రియ?","వచన కవిత","గేయకవిత","శతకం","నాటకం"],["ఈ పాఠం ఏ సంపుటి నుండి?","సమతా వసంత గానం","పాలకంకి","బౌద్ధభాషితాలు","ఖండ కావ్యములు"],["కవిత నేపథ్యం – ఏ నది జలవివాదం?","రోహిణీ నది","గంగా నది","గోదావరి","కృష్ణా నది"],["యుద్ధ తీర్మానం చేసినవారు?","శాక్యులు","మౌర్యులు","కాకతీయులు","గుప్తులు"],["నిజమైన విజేత ఎవరని కవి అన్నాడు?","యుద్ధాన్ని గెలిచినవాడు","యుద్ధంలో గెలిచినవాడు","ఎక్కువ సైన్యం ఉన్నవాడు","ధనవంతుడు"],["యుద్ధంలో గెలిచి పశ్చాత్తాపపడిన రాజు?","అశోకుడు","శ్రీకృష్ణదేవరాయలు","అక్బర్","చంద్రగుప్తుడు"],["యుద్ధాన్నే గెలిచినవాడు?","బుద్ధుడు","అశోకుడు","అలెగ్జాండర్","నెపోలియన్"],["\"పచ్చని నేలకు నెత్తుటి తిలకం\" – భావం?","యుద్ధంతో నేల రక్తసిక్తమవడం","పండుగ","పంటలు పండటం","పూజ"],["యుద్ధంలో గెలుపును కవి ఏమన్నాడు?","పశుత్వం, చవటతనం","వీరత్వం","పౌరుషం","గొప్పతనం"],["రెడ్‌క్రాస్ స్థాపకుడు?","జీన్ హెన్రీ డ్యూనాంట్","మదర్ థెరిసా","గాంధీ","నైటింగేల్"],["అంతర్జాతీయ శాంతి దినోత్సవం?","సెప్టెంబర్ 21","అక్టోబర్ 2","జనవరి 30","డిసెంబర్ 10"],["\"మా నూతిలో నీళ్ళు పాతాళానికి చేరాయి\" – అలంకారం?","అతిశయోక్తి","ఉపమ","రూపకం","శ్లేష"],["\"అమ్మ చూపించే ప్రేమ ప్రేమ\" – అలంకారం?","లాటానుప్రాసం","అతిశయోక్తి","వృత్త్యనుప్రాసం","క్రమాలంకారం"],["యుద్ధ + ఉన్మాది = ?","యుద్ధోన్మాది (గుణ సంధి)","యుద్ధున్మాది","యుద్ధాన్మాది","యుద్ధేన్మాది"],["\"అంగబలం, అర్థబలం\" లో అర్థబలం అంటే?","ధనబలం","అర్థం తెలియడం","శరీరబలం","మాటబలం"]],"wb":{"mis":"అతిశయోక్తిలో గుణాన్ని పెంచి చెబుతారు (తాటిచెట్టంత పొడవు); లాటానుప్రాసంలో ఒకే పదం రెండుసార్లు వచ్చి రెండోది విశిష్టార్థం ఇస్తుంది (\"గాలి గాలి\" = మంచి గాలి).","qz":[["సంవత్సరాలు విడదీస్తే?","సంవత్సరము + లు (లులనల సంధి)","సంవత్సర + ఆలు","సంవత్స + రాలు","సంవత్సరా + లు"],["చరాచర విడదీస్తే?","చర + అచర (సవర్ణదీర్ఘ)","చరా + చర","చర + ఆచర","చరి + అచర"],["మానవాళి విడదీస్తే?","మానవ + ఆళి (సవర్ణదీర్ఘ)","మానవా + ళి","మాన + వాళి","మానవు + ఆళి"],["ఒక్క + ఒక్క = ?","ఒక్కొక్క (ఆమ్రేడిత)","ఒక్కోక్క","ఒక్కక్క","ఒక్కఒక్క"],["మాంసము + ముద్ద = ?","మాంసపుముద్ద (పుంప్వాదేశ)","మాంసముద్ద","మాంసంముద్ద మాత్రమే","మాంసాముద్ద"],["\"భార్యాభర్తలు\" సమాసం?","ద్వంద్వ సమాసం","ద్విగు","షష్ఠీ","బహువ్రీహి"],["\"మరణము అనెడి మృదంగం\" – సమాస పదం?","మరణమృదంగం (రూపక సమాసం)","మృదంగమరణం (షష్ఠీ)","మరణంమృదంగం (ద్వంద్వ)","మరణపుమృదంగం (ద్విగు)"],["\"పసివారైన పిల్లలు\" – సమాస పదం?","పసిపిల్లలు (విశేషణ పూర్వపద కర్మధారయ)","పిల్లపసి (షష్ఠీ)","పసులపిల్లలు (ద్వంద్వ)","పసిపిల్ల (ద్విగు)"],["పుణ్యం – వికృతి?","పున్నెం","పగిది","బోగము","గరువము"],["\"అతడు తాటిచెట్టంత పొడవున్నాడు\" – అలంకారం?","అతిశయోక్తి","ఉపమ","రూపకం","స్వభావోక్తి"]],"pg":"128–137","f":"books/10/Class10_Telugu_Textbook_Sem1.pdf","p":136,"lb":"పాఠ్యపుస్తకం","ws":["అవగాహన – ప్రతిస్పందన: అ) ప్రశ్నలు, ఆ) పద్యం, ఇ) గద్యం (పుట 132)","ఇ) గద్యం, ఈ) అర్థసందర్భాలు, ఉ) ఏకవాక్య; వ్యక్తీకరణ (పుట 133)","కవిత పొడిగింపు; పదజాలం (పుట 134)","సంధులు, సమాసాలు, అతిశయోక్తి (పుట 135)","అలంకారాలు (మిగతా); ప్రాజెక్టుపని (పుట 136)"]},"tg":[["అవగాహన – ప్రతిస్పందన: అ) ప్రశ్నలు, ఆ) పద్యం, ఇ) గద్యం (పుట 132)",["అ) 1) యుద్ధంలో అమాయకులు, పసిపిల్లలు చనిపోతారు; ప్రకృతి ధ్వంసమవుతుంది; బలవంతుడు బలహీనుడిని ఓడించడంలో గొప్పతనం లేదు – రెండు పశువులు కుమ్ముకున్నట్లే. అందుకే అది వీరత్వం కాదు, పశుత్వం అని కవి ఉద్దేశం. యుద్ధం జరగకుండా చూడడమే నిజమైన వీరత్వం","2) బుద్ధుడు – యుద్ధాన్ని నివారించడానికి రాజ్యం వదిలి అహింస బోధించాడు; అశోకుడు – కళింగ యుద్ధం తర్వాత పశ్చాత్తాపంతో ధర్మప్రచారం చేశాడు; మహాత్మా గాంధీ – సత్యం, అహింసలతో స్వాతంత్ర్యం సాధించాడు; మదర్ థెరిసా, మార్టిన్ లూథర్ కింగ్, నెల్సన్ మండేలా – శాంతి కోసం కృషి చేశారు","ఆ) 1) మహితమైన (గొప్ప) స్వతంత్ర భారతదేశాన్ని 2) దుస్సహమైన కష్టాలను భరించి స్వచ్ఛందంగా పోరాడి ప్రాణత్యాగం చేసిన వీరుల (నిత్యుల) ఆశీస్సులు 3) వారు భరించలేని కష్టాలకు ఓర్చి, ఎవరూ బలవంతం చేయకుండా స్వచ్ఛందంగా పోరాడి దేశం కోసం ప్రాణాలర్పించిన త్యాగశీలురు, వీరులు 4) ఉదా: ఈ పద్యం ఏ కావ్యంలోనిది? (సిపాయిపితూరి – పుట్టపర్తి నారాయణాచార్యులు)"]],["ఇ) గద్యం, ఈ) అర్థసందర్భాలు, ఉ) ఏకవాక్య; వ్యక్తీకరణ (పుట 133)",["ఇ) 1) యుద్ధ గాయాలకు, భూకంపం, తుపాను, అగ్నిప్రమాదం, అంటువ్యాధుల బాధితులకు ఔషధాలు, ఆహారం, దుస్తులు సరఫరా చేసి రక్షణ బాధ్యత చూస్తుంది 2) స్విట్జర్లాండ్‌కు చెందిన జీన్ హెన్రీ డ్యూనాంట్ ఐదుగురు స్నేహితులతో 9 ఫిబ్రవరి 1863న స్థాపించారు 3) జెనీవాలో (1863–64 లో) అధికారికంగా ఆమోదించారు 4) ఉదా: రెడ్‌క్రాస్ సంస్థ ప్రాథమిక సూత్రాలు ఏవి?","ఈ) 1) \"పచ్చని నేలకు నెత్తుటి తిలకం దిద్దవలసి వచ్చింది\" – నేతల ప్రతాప్ కుమార్, \"యుద్ధ విజేత\" వచన కవిత (సమతా వసంత గానం). సందర్భం: మనిషికి మనిషికి మధ్య యుద్ధం మొదలై సాటిమనిషిని శత్రువన్న సందర్భం. అర్థం: యుద్ధం వల్ల పచ్చని భూమి రక్తంతో తడిసిపోయింది","2) \"చిరుదరహాసాలను చెరిపేయడమే యుద్ధం\" – యుద్ధ విజేత. సందర్భం: యుద్ధం అంటే ఏమిటో వర్ణించే సందర్భం. అర్థం: అన్నెం పున్నెం ఎరుగని పసిపిల్లల ముఖాలపై చిరునవ్వులను చెరిపివేయడమే యుద్ధం","ఉ) 1) రాజ్యం, రమణి, పదవి, పౌరుషం కోసం 2) అశోకుడు 3) సిద్ధార్థుడు (బుద్ధుడు) 4) యుద్ధమే జరగకుండా నివారించడం, శాంతితో సమస్యను పరిష్కరించడం","అ) 1) యుద్ధాన్ని నివారించి, సకల రాజ్యభోగాలు త్యజించి, శాంతి, అహింస బోధించిన బుద్ధుడి లాంటివారు ప్రజల హృదయాల్లో విజేతలుగా నిలుస్తారు 2) ప్రకృతి సకల జీవులకు నివాసం; పూలు, పక్షులు, నెమళ్ళు, జింకలు ఏ తప్పూ చేయవు. యుద్ధం వాటన్నిటినీ నాశనం చేస్తుంది – అందుకే అది ఉన్మాద చర్య 3) యుద్ధంలో గెలిచినవాడు ఎంతోమంది ప్రాణాలు తీసి గెలుస్తాడు; యుద్ధాన్నే గెలిచినవాడు ఎవరి ప్రాణమూ పోకుండా శాంతిని కాపాడతాడు; అతడు శాశ్వతంగా ప్రజల హృదయాల్లో నిలుస్తాడు","ఆ) 1) సారాంశం: యుద్ధంలో ఒకరు గెలుస్తారు, ఒకరు ఓడతారు; దద్దమ్మా గెలవవచ్చు. కానీ యుద్ధాన్ని గెలిచినవాడే నిజమైన విజేత. బలం, ధనం, వ్యూహం ఉన్నవాడు లేనివాడిపై గెలవడం గెలుపు కాదు – పశువుల కుమ్ములాట వంటిదే. రాజ్యం, పదవి, పౌరుషం, జాతి అహంకారం కోసం సాటిమనిషిని శత్రువన్నారు; బాణాలతో అప్పుడు, బాంబులతో ఇప్పుడు చంపుకుంటున్నారు. భూమిని మాంసపు ముద్దగా, పిల్లల చిరునవ్వులను మాయం చేశారు; ప్రకృతిని ధ్వంసం చేశారు. అలాంటి గెలుపు పశుత్వం. అశోకుడు గెలిచి పశ్చాత్తాపపడ్డాడు; బుద్ధుడు యుద్ధాన్నే గెలిచాడు","2) దేశాల మధ్య వివాదాలను చర్చలు, ఐక్యరాజ్యసమితి వంటి సంస్థల ద్వారా పరిష్కరించాలి; ఆయుధ పోటీ, అణ్వాయుధాలు తగ్గించాలి; జాతి, మత, ప్రాంత ద్వేషాలు రెచ్చగొట్టకూడదు; పిల్లలకు బాల్యం నుండే శాంతి, సహనం, సోదరభావం నేర్పాలి; పేదరికం, నిరుద్యోగం, అన్యాయం తగ్గిస్తే ఘర్షణలు తగ్గుతాయి; సాంస్కృతిక, క్రీడా, విద్యా మార్పిడితో దేశాల మధ్య స్నేహం పెంచాలి; బుద్ధుడు, గాంధీ బోధించిన అహింస మార్గం అనుసరించాలి","ఇ) 1) పట్టిక – యుద్ధ నష్టాలు: ప్రాణనష్టం, అనాథలు, ఆస్తి నష్టం, ప్రకృతి విధ్వంసం, కరువు, అంటువ్యాధులు, ఆర్థిక పతనం, ద్వేషం","శాంతి ప్రయోజనాలు: ప్రాణ రక్షణ, అభివృద్ధి, విద్య–వైద్యం, పంటలు, వ్యాపారం, స్నేహం, సంతోషం, ప్రకృతి సంరక్షణ"]],["కవిత పొడిగింపు; పదజాలం (పుట 134)",["ఇ) 2) నేనే సైనికుడనైతే… సరిహద్దుల్లో కాపలా కాస్తాను / వరదల్లో, భూకంపాల్లో ప్రజలను కాపాడతాను / శత్రువు దాడిచేస్తే ధైర్యంగా ఎదుర్కొంటాను / కానీ శాంతినే కోరుకుంటాను / నా తుపాకీ దేశాన్ని రక్షించాలి గానీ / ఏ తల్లి కడుపూ కొట్టకూడదు / నేనే సైనికుడనైతే… శాంతికి కాపలాదారుడినవుతాను","అ) 1) తథ్యం = నిజం, తప్పనిసరి – కష్టపడితే విజయం తప్పనిసరి 2) దరహాసం = చిరునవ్వు – అమ్మ ముఖంపై చిరునవ్వు 3) వ్యూహం = ప్రణాళిక – ఆటలో మంచి ప్రణాళిక వేశాం 4) త్యజించు = విడిచిపెట్టు – చెడు అలవాట్లను విడిచిపెట్టాలి","ఆ) 1) యుద్ధం = సమరం, సంగ్రామం 2) విజయం = గెలుపు, జయం 3) కీర్తి = యశస్సు, పేరు","ఇ) 1) పశువు – ఇ (గొడ్డు, ఆత్మ, ప్రమథ గణం) 2) కాలం – అ (సమయం, నలుపు, చావు) 3) రాజ్యం – ఆ (రాష్ట్రం, ఏలుబడి, దొరతనం)","ఈ) 1) ప్రకృతి – పగిది 2) భోగము – బోగము 3) పుణ్యం – పున్నెం 4) గర్వము – గరువము","సంధి అ) 1) సంవత్సరాలు = సంవత్సరము + లు (లులనల సంధి) 2) కొమ్ములెగరేసిన = కొమ్ములు + ఎగరేసిన (ఉకార సంధి) 3) చరాచర = చర + అచర (సవర్ణదీర్ఘ సంధి)"]],["సంధులు, సమాసాలు, అతిశయోక్తి (పుట 135)",["అ) 4) గెలిచినంత = గెలిచిన + అంత (అకార సంధి) 5) మానవాళి = మానవ + ఆళి (సవర్ణదీర్ఘ సంధి)","ఆ) 1) ఒక్క + ఒక్క = ఒక్కొక్క (ఆమ్రేడిత సంధి) 2) ఎందుకు + అవుతుంది = ఎందుకవుతుంది (ఉకార సంధి) 3) అతను + ఎప్పటికి = అతనెప్పటికి (ఉకార సంధి) 4) మాంసము + ముద్ద = మాంసపుముద్ద (పుంప్వాదేశ సంధి) 5) యుద్ధ + ఉన్మాది = యుద్ధోన్మాది (గుణ సంధి)","ఇ) 1) శత్రురాజ్యం – శత్రువు యొక్క రాజ్యం (షష్ఠీ తత్పురుష) 2) భార్యాభర్తలు – భార్యయు, భర్తయు (ద్వంద్వ) 3) చరాచరములు – చరములును, అచరములును (ద్వంద్వ) 4) యుద్ధవ్యూహం – యుద్ధము యొక్క వ్యూహం (షష్ఠీ తత్పురుష)","ఈ) 1) మరణమృదంగం (రూపక సమాసం) 2) అర్థబలం (తృతీయా తత్పురుష) 3) పసిపిల్లలు (విశేషణ పూర్వపద కర్మధారయ) 4) చిరుదరహాసం (విశేషణ పూర్వపద కర్మధారయ)","ఉ) 1) అతిశయోక్తి 2) అతిశయోక్తి 3) అతిశయోక్తి"]],["అలంకారాలు (మిగతా); ప్రాజెక్టుపని (పుట 136)",["ఉ) 4) లాటానుప్రాసం (\"గాలి గాలి\" – రెండో గాలి = మంచి, చల్లని గాలి) 5) లాటానుప్రాసం (\"ప్రేమ ప్రేమ\" – రెండో ప్రేమ = నిజమైన, నిస్వార్థ ప్రేమ)","ప్రాజెక్టు – నోబెల్ శాంతి బహుమతి: మదర్ థెరిసా (1979 – పేదలు, రోగుల సేవ); నెల్సన్ మండేలా (1993 – దక్షిణాఫ్రికా వర్ణవివక్ష అంతం); కైలాస్ సత్యార్థి, మలాలా యూసఫ్‌జాయ్ (2014 – బాలల హక్కులు, బాలికా విద్య); మార్టిన్ లూథర్ కింగ్ జూనియర్ (1964 – అహింసా పౌరహక్కుల ఉద్యమం)"]]]},{"id":"te12","no":12,"t":"సూక్తి సుధ","m":[11],"ty":"వ్యాసం","th":"అన్నమయ్య సంకీర్తనలలో నీతి","by":"ఎస్. గంగప్ప","sum":"తెలుగులో పదకవితకు ఆద్యుడు తాళ్ళపాక అన్నమాచార్యుడు. యోగ, వైరాగ్య, శృంగార, ఆధ్యాత్మిక సంకీర్తనలతో పాటు ప్రజల మేలు కోసం నీతి సంకీర్తనలు రచించాడు. ఎంత చదివినా పరనింద, మనసు చంచలత్వం మానినప్పుడే సద్గతి; పరధనాపేక్ష, నిందలు, విరసవర్తనం విడిచినప్పుడే జీవితం సుఖమయం. కులం, మతం కంటే నిజం తెలిసినవాడే మహాత్ముడు (\"తనకేడ చదువులు\"). పరులను యాచించి, ఊడిగం చేయడం కంటే అడవిలో మృగమైనా మేలు (\"చీచీ నరులదేటి జీవనము\"). రాజుకు, బంటుకు నిద్ర ఒకటే; ధనవంతుడికి, నిరుపేదకు పగలు రాత్రి ఒకటే – భగవంతుడి సృష్టిలో అందరూ సమానమే (\"నిండార రాజు\"). ఇతరులను దూషించకుండా ఆత్మపరిశీలన చేసుకోవాలి; సోమరులను, పరుల సొమ్ముతో గొప్పవారు కావాలనుకునేవారిని గర్హించాడు. అరిషడ్వర్గాలను (కామ, క్రోధ, లోభ, మోహ, మద, మాత్సర్యాలు) ఆత్మనిగ్రహంతో జయించాలి. పుట్టుక, చావు నిజం – నడుమ బతుకంతా నాటకం (\"నానాటి బతుకు నాటకము\"); కాలం వృథా చేయరాదు.","pts":["రచయిత: ఎస్. గంగప్ప (శ్రీరామప్పగారి గంగప్ప; జననం 08.11.1936) – ఉమ్మడి అనంతపురం జిల్లా పెనుగొండ తాలూకా నల్లగొండ్రాయని పల్లి; తల్లిదండ్రులు వెంకటప్ప, కృష్ణమ్మ.","100కు పైగా గ్రంథాలు: సాహిత్యసుధ, సాహిత్యానుశీలన, తెలుగులో పదకవిత, క్షేత్రయ్య పదసాహిత్యం, జానపద సాహిత్యం మొ.; 1972, 1981లో ఆంధ్రప్రదేశ్ సాహిత్య అకాడమీ అవార్డులు.","పాఠం \"సాహిత్యానుశీలన\" గ్రంథం నుండి. ప్రక్రియ: వ్యాసం – ఉపోద్ఘాతం, విషయ విస్తరణ, ముగింపు ప్రధానాంగాలు.","అన్నమయ్య – దాక్షిణాత్య భాషల్లో ప్రథమ వాగ్గేయకారుడు; పదకవితా పితామహుడు, సంకీర్తనాచార్యుడు; 32 వేల కీర్తనలు.","వాగ్గేయకారుడు = స్వయంగా గీతం రాసి, స్వరాలు కూర్చి, పాడేవాడు (ధాతువు = సంగీతం, మాతువు = సాహిత్యం).","అరిషడ్వర్గాలు: కామ, క్రోధ, లోభ, మోహ, మద, మాత్సర్యాలు (అంతశ్శత్రువులు).","ఏడుగడలు (సప్త రక్షకాలు): గురువు, తల్లి, తండ్రి, పురుషుడు, విద్య, దైవం, దాత.","వేమన: \"కులము కన్నా గుణము మిన్న\"; \"నానాటి బతుకు నాటకము – పుట్టుటయు నిజము పోవుటయు నిజము\"."],"w":[["ఆద్యుడు","మొదటివాడు"],["అనవద్యుడు","దోషం లేనివాడు"],["అపేక్ష","కోరిక"],["సద్గతి","మంచి గతి, మోక్షం"],["ఆరడి","బాధ, వేధింపు"],["విరసవర్తనం","కటువైన, చెడు ప్రవర్తన"],["నిక్కం","నిజం"],["ఊడిగం","సేవ, చాకిరీ"],["గర్హించు","నిందించు"],["హైన్యం","హీనత్వం"],["దైన్యం","దీనత్వం"],["ఏడుగడ","రక్షణ"],["మేను","శరీరం"],["ఒరులు","ఇతరులు"],["ఉసురు","ప్రాణం"]],"gr":{"t":"భాషాంశాలు","p":["శ్చుత్వ సంధి: సకార, తవర్గాక్షరాలకు శకార, చవర్గాక్షరాలు పరమైతే శకార, చవర్గాక్షరాలే ఆదేశం – తపస్ + చర్య = తపశ్చర్య; సత్ + చిత్ = సచ్చిత్; జగత్ + జనని = జగజ్జనని; సత్ + జనులు = సజ్జనులు.","ముక్తపదగ్రస్త అలంకారం: ఒక పాదం/వాక్యం ఏ పదంతో ముగుస్తుందో తర్వాతి పాదం అదే పదంతో మొదలవడం – \"సుదతీ నూతన మదనా / మదనాగ తురంగ…/ సదనామయ గజరదనా / రదనాగేంద్ర…\".","జశ్త్వ సంధి: సత్ + గతి = సద్గతి. పుంప్వాదేశం: వైరాగ్యము + పద్ధతి = వైరాగ్యపు పద్ధతి. ద్విరుక్తటకారం: నడుమ + నడుమ = నట్టనడుమ.","ప్రకృతి–వికృతి: భక్తి–బత్తి, స్థిరం–తిరం, ప్రాణం–పానం, భాష–బాస, నిజం–నిక్కం, గుణం–గొనం."]},"qa":[["వాగ్గేయకారులు అంటే ఎవరు?","స్వయంగా గీతం రాసి, స్వరాలు కూర్చి, గానం చేసేవారు."],["మానవులకు సద్గతి ఎప్పుడు కలుగుతుంది?","పరనింద మాని, మనసు స్థిరంగా ఉంచుకొని, పరధనాపేక్ష, విరసవర్తనం విడిచినప్పుడు."],["ఏది జీవిత లక్ష్యం కావాలన్నాడు?","చదువులో, వేషంలో కాదు – నీతిని గ్రహించి, ఉన్నతంగా ఎదగడమే జీవిత లక్ష్యం."],["\"నిండార రాజు…\" కీర్తన సందేశం?","రాజు, బంటు, ధనికుడు, పేద – అందరూ భగవంతుడి సృష్టిలో సమానమే (సర్వసమానత్వం)."],["అరిషడ్వర్గాలను ఎలా జయించాలి?","ఆత్మనిగ్రహంతో, సాధనతో."],["\"నానాటి బతుకు నాటకము\" భావం?","పుట్టుక, చావు మాత్రమే నిజం; నడుమ జీవితమంతా నాటకం – కాలం వృథా చేయకూడదు."]],"act":"అన్నమయ్య సంకీర్తనలు (ఉదా: \"బ్రహ్మమొక్కటే\", \"నానాటి బతుకు నాటకము\") సేకరించి తరగతిలో రాగయుక్తంగా పాడి, వాటి భావాలు చర్చించండి.","kn":"పులి వేషం – వేట నృత్యం అనే జానపద కళారూపం. శ్రీవారి బ్రహ్మోత్సవాలు – తిరుమలలో 9 రోజులు (అంకురార్పణ, గరుడ ధ్వజారోహణ, వాహన సేవలు, చక్రస్నానం). అమృతమూర్తి అమ్మ – జిల్లెళ్ళమూడి అనసూయాదేవి (\"పిడికెడు బియ్యం\" పథకం, అన్నపూర్ణాలయం).","qz":[["\"సూక్తి సుధ\" పాఠ్య రచయిత?","ఎస్. గంగప్ప","సి. నారాయణ రెడ్డి","నేతల ప్రతాప్ కుమార్","గుర్రం జాషువా"],["ఈ పాఠం ప్రక్రియ?","వ్యాసం","శతకం","వచన కవిత","కథానిక"],["ఈ పాఠం ఏ గ్రంథం నుండి?","సాహిత్యానుశీలన","సాహిత్యసుధ","తెలుగులో పదకవిత","సమతా వసంత గానం"],["తెలుగులో పదకవితకు ఆద్యుడు?","అన్నమాచార్యుడు","త్యాగరాజు","క్షేత్రయ్య","రామదాసు"],["అన్నమయ్య బిరుదు?","పదకవితా పితామహుడు","ఆంధ్ర కవితా పితామహుడు","కవిత్రయం","అభినవ పోతన"],["అన్నమయ్య రాసిన కీర్తనలు సుమారు?","32 వేలు","3 వేలు","1 లక్ష","500"],["\"ధాతువు\" అంటే?","సంగీతం","సాహిత్యం","నృత్యం","చిత్రం"],["అరిషడ్వర్గాలలో లేనిది?","దయ","క్రోధం","లోభం","మాత్సర్యం"],["\"నానాటి బతుకు నాటకము\" – నిజమైనవి?","పుట్టుట, పోవుట","ధనం, పదవి","చదువు, శాస్త్రాలు","కులం, మతం"],["\"కులము కన్నా గుణము మిన్న\" అన్నది?","వేమన","సుమతీ శతకకారుడు","పోతన","తిక్కన"],["\"నిండార రాజు నిద్రించు నిద్రయు నొకటే\" – భావం?","అందరూ సమానమే","రాజు గొప్పవాడు","నిద్ర మంచిది","బంటు కష్టపడాలి"],["ఏడుగడలు (సప్త రక్షకాలు) లో లేనిది?","ధనం","గురువు","విద్య","దైవం"],["సత్ + జనులు = ?","సజ్జనులు (శ్చుత్వ సంధి)","సత్జనులు","సద్జనులు","సజనులు"],["సత్ + గతి = ?","సద్గతి (జశ్త్వ సంధి)","సత్గతి","సగ్గతి","సద్దతి"],["\"సుదతీ నూతన మదనా / మదనాగ…\" – అలంకారం?","ముక్తపదగ్రస్తం","అతిశయోక్తి","లాటానుప్రాసం","ఉపమ"],["ప్రాణం – వికృతి?","పానం","బత్తి","తిరం","బాస"]],"wb":{"mis":"శ్చుత్వ సంధిలో ఆదేశం శకార/చవర్గాక్షరం (సత్ + జనులు = సజ్జనులు); సత్ + గతి = సద్గతి జశ్త్వ సంధి – రెండూ కలపకండి. ముక్తపదగ్రస్తంలో పాదం చివరి పదమే తర్వాతి పాదం మొదట వస్తుంది.","qz":[["సంకీర్తనాచార్యుడు విడదీస్తే?","సంకీర్తన + ఆచార్యుడు (సవర్ణదీర్ఘ)","సంకీర్తనా + చార్యుడు","సంకీర్త + నాచార్యుడు","సంకీర్తన + అచార్యుడు (గుణ)"],["వైరాగ్యపు పద్ధతి విడదీస్తే?","వైరాగ్యము + పద్ధతి (పుంప్వాదేశ)","వైరాగ్య + పు పద్ధతి","వైరాగ్యపు + అద్ధతి","వైరాగ్యం + పద్ధతి (ఉకార)"],["పరధన + అపేక్ష = ?","పరధనాపేక్ష (సవర్ణదీర్ఘ)","పరధనోపేక్ష","పరధనేపేక్ష","పరధనపేక్ష"],["దోషాలు + ఉన్న = ?","దోషాలున్న (ఉకార)","దోషాలువున్న","దోషాలఉన్న","దోషలున్న"],["తపస్ + శక్తి = ?","తపశ్శక్తి (శ్చుత్వ)","తపస్శక్తి","తపోశక్తి","తపశక్తి"],["\"పరులసొమ్ము\" సమాసం?","షష్ఠీ తత్పురుష","ద్వంద్వ","ద్విగు","బహువ్రీహి"],["\"శక్తియును, సామర్థ్యమును\" – సమాస పదం?","శక్తిసామర్థ్యాలు (ద్వంద్వ)","శక్తిసామర్థ్యం (షష్ఠీ)","సామర్థ్యశక్తి (కర్మధారయ)","శక్తిపూర్ణం (ద్విగు)"],["\"వివేకం లేని వాడు\" – సమాస పదం?","అవివేకి (నఞ్ తత్పురుష)","వివేకి","వివేకహీన (ద్వంద్వ)","నిర్వివేకం (ద్విగు)"],["\"మతి\" నానార్థాలు (పుస్తక పట్టిక)?","ఎలుక, తెలివి, బుద్ధి","పాలు, అమృతం, సున్నం","వంశం, జాతి, ఇల్లు","స్వభావం, వింటినారి, బుద్ధి"],["\"మేను\" పర్యాయపదాలు?","శరీరం, దేహం","దిగులు, బెంగ","దివి, నాకం","వాంఛ, ఈప్సితం"]],"pg":"138–150","f":"books/10/Class10_Telugu_Textbook_Sem1.pdf","p":146,"lb":"పాఠ్యపుస్తకం","ws":["చదవండి – ఆలోచించి చెప్పండి (పుట 138)","ఆలోచించండి – చెప్పండి (పుట 140)","ఆలోచించండి – చెప్పండి (పుట 141)","అవగాహన – ప్రతిస్పందన: అ) ప్రశ్నలు, ఆ) గద్యం (పుట 143)","ఇ) కీర్తన, ఈ) అర్థసందర్భాలు, ఉ) ఏకవాక్య; వ్యక్తీకరణ (పుట 144)","వ్యాసరూప (మిగతా), సృజనాత్మకత, పదజాలం (పుట 145)","నానార్థాలు, ప్రకృతి–వికృతి, సంధులు (పుట 146)","శ్చుత్వ సంధి, సమాసాలు, ముక్తపదగ్రస్తం (పుట 147)","ప్రాజెక్టుపని (పుట 148)"]},"tg":[["చదవండి – ఆలోచించి చెప్పండి (పుట 138)",["1) తాళ్ళపాక అన్నమాచార్యుడు 2) స్వయంగా గీత రచన చేసి, స్వరాలు కూర్చి, గానం చేసేవారు 3) ఒకవైపు ఆధ్యాత్మిక దృష్టి, మరొకవైపు సామాజిక దృష్టి; పద్యకవుల రచనలతో సరితూగే పదాలు, జానపద బాణీల్లో ఆణిముత్యాల్లాంటి పాటలు"]],["ఆలోచించండి – చెప్పండి (పుట 140)",["1) మనసు చంచలమైనది – క్షణక్షణానికి మారుతుంది; చంచల బుద్ధి మానితేనే మేలు 2) పరనింద, పరధనాపేక్ష, విరసవర్తనం విడిచి, నీతిని గ్రహించి మసలుకొన్నప్పుడు మానవుడు ఉన్నతుడౌతాడు"]],["ఆలోచించండి – చెప్పండి (పుట 141)",["1) ఈర్ష్య, ద్వేషం, అసూయ, పరనింద, గేలిచేయడం, గర్వం, సోమరితనం, అరిషడ్వర్గాలు 2) పరనింద మాని, మనసు స్థిరంగా ఉంచుకొని, పరధనాన్ని ఆశించకుండా, నిందలకు చోటివ్వకుండా సరసంగా జీవించినప్పుడు సద్గతి కలుగుతుంది"]],["అవగాహన – ప్రతిస్పందన: అ) ప్రశ్నలు, ఆ) గద్యం (పుట 143)",["అ) 1) ఉదా: \"ఎంత చదివిన నేమి\" – ఎంత చదివినా, విన్నా పరనింద, చంచలబుద్ధి మానకపోతే సద్గతి కలగదు; \"నానాటి బతుకు నాటకము\" – పుట్టుక, చావు నిజం, నడుమ బతుకు నాటకం; \"నిండార రాజు\" – అందరూ సమానమే (రాగయుక్తంగా పాడి భావం చెప్పాలి)","2) విరసవర్తనం = కటువైన, ఇతరులకు బాధ కలిగించే చెడు ప్రవర్తన. ఇది తనకూ, తోటివారికీ దుఃఖం కలిగిస్తుంది; సరసజీవనమే మనుగడకు మంచిది కాబట్టి దాన్ని విడనాడాలి","3) ఎన్ని చదివినా, ఎన్ని వేషాలు వేసినా అందులోని నీతిని గ్రహించి మసలుకోవడం, ఉన్నతంగా ఎదగడమే జీవిత లక్ష్యం కావాలి","ఆ) 1) దేశీయులనే కాక విదేశీయులనూ పరవశింపజేసే మధురమైన కంఠం; కర్ణాటక సంగీత సాగరాన్ని మధించి అమృతం వంటి రాగఝరులు అందించారు 2) విష్ణుసహస్రనామాలు, సుప్రభాతాలు, భజనలు, త్యాగయ్య కృతులు, శంకరాచార్యుల శ్లోకాలు, ఆండాళ్ తిరుప్పావై, వాగ్గేయకారుల కీర్తనలు – సంస్కృతం, తెలుగు, తమిళం, కన్నడం, హిందీ భాషల్లో 3) బిరుదులు: సంగీతకళానిధి, సప్తగిరి సంగీత విద్వన్మణి; పురస్కారాలు: పద్మవిభూషణ్, భారతరత్న, రామన్ మెగసెసే 4) \"గాన కోకిల ఎం.ఎస్. సుబ్బులక్ష్మి\""]],["ఇ) కీర్తన, ఈ) అర్థసందర్భాలు, ఉ) ఏకవాక్య; వ్యక్తీకరణ (పుట 144)",["ఇ) 1) శాంతము లేకపోతే సౌఖ్యము (సుఖం) ఉండదు 2) శ్రీరాముని \"సారసదళనయన\" (తామరరేకుల వంటి కన్నులవాడా), \"సాధురక్షక\" అని సంబోధించాడు 3) దాంతునికైనా, వేదాంతునికైనా; భార్య, పిల్లలు, ధనధాన్యాలు, జపతప సంపద, యాగాది కర్మలు, ఆగమశాస్త్రాలు అన్నీ ఉన్నా శాంతం లేకపోతే సుఖం ఉండదు 4) ఉదా: ఈ కీర్తన ఎవరు రచించారు? (త్యాగరాజు)","ఈ) 1) \"నిండార రాజు నిద్రించు నిద్రయు నొకటే\" – అన్నమాచార్యుని సంకీర్తన, \"సూక్తి సుధ\" పాఠం (ఎస్. గంగప్ప, సాహిత్యానుశీలన). సందర్భం: భగవంతుని సృష్టిలో హెచ్చుతక్కువలు లేవని సర్వసమానత్వాన్ని చెప్పిన సందర్భం. భావం: రాజు నిద్రించే నిద్ర, సేవకుడి నిద్ర ఒకటే","2) \"పరధనముల యాస పాసినగాక\" – అన్నమాచార్యుని సంకీర్తన, సూక్తి సుధ. సందర్భం: పరధనాపేక్ష, నిందలు, విరసవర్తనం విడిస్తేనే మేలు అని చెప్పిన సందర్భం. భావం: ఇతరుల సొమ్ముపై ఆశ వదిలితేనే మోక్షం కలుగుతుంది","3) \"ఈ విశ్వంలో కులం, జాతి, మతాలకు ఏనాడూ ప్రాధాన్యం లేదు\" – ఎస్. గంగప్ప, సూక్తి సుధ. సందర్భం: స్వార్థపరులు కులమతాల భేదాలు కల్పిస్తారని, నిజం ఎరిగినవాడే మహాత్ముడని అన్నమయ్య భావాన్ని వివరించిన సందర్భం. భావం: మనుషుల్లో కుల, జాతి, మత భేదాలకు విలువ లేదు","ఉ) 1) పదకవితా పితామహుడు, సంకీర్తనాచార్యుడు 2) కష్టం లేకుండా, దోపిడీతో పరధనం సంపాదించాలనుకోవడం మంచిది కాదు 3) నిందలపాలు కాకుండా, విరసవర్తనం లేకుండా సరసంగా జీవించడమే ఉత్తమ జీవితం 4) గురువు, తల్లి, తండ్రి, పురుషుడు, విద్య, దైవం, దాత – ఏడుగడలు (సప్త రక్షకాలు)","అ) 1) కామ, క్రోధ, లోభ, మోహ, మద, మాత్సర్యాలనే అంతశ్శత్రువులు మనపై అధికారం వహించి వశపరచుకుంటాయి. శరీరమనే ఊరికి తొమ్మిది కంతలు; కాముడనే రాజు, కోపమనే ప్రధాని, ఇంద్రియాలనే కాపులు – అని రూపకంగా చెప్పాడు. బయటి శత్రువుల కంటే ముందు వీటిని ఆత్మనిగ్రహంతో, సాధనతో జయించాలన్నాడు","2) సోమరిపోతులను, పరుల సొమ్ము సొంతం చేసుకోవాలని ప్రయత్నించేవారిని, ఇతరుల సొమ్ముతో గొప్పవారం కావాలనుకునేవారిని (\"వెర్రులాల\") అసహ్యించుకున్నాడు – ఎందుకంటే సొంత శక్తితో సాధించడంలోనే ఆత్మవిశ్వాసం, నిజశక్తి ఉంటాయి","3) ఎన్ని చదువులు చదివినా పాపపంకిలంలో పడకుండా, పరనింద, చంచలబుద్ధి, పరధనాపేక్ష, విరసవర్తనం విడిచి, తప్పు అని తెలిసి మానుకొన్నప్పుడే మనిషి ఉన్నతుడవుతాడు","ఆ) 1) విలువలు: పరనింద చేయకూడదు; మనసు స్థిరంగా ఉంచుకోవాలి; ఇతరుల సొమ్ము ఆశించకూడదు; కష్టపడి సంపాదించాలి; కులమత భేదాలు పాటించకూడదు – అందరూ సమానమే; ఎవరి ముందూ యాచించకూడదు, ఆత్మగౌరవంతో బతకాలి; ఆత్మపరిశీలన చేసుకోవాలి; ఈర్ష్య, అసూయ, అరిషడ్వర్గాలను జయించాలి; సోమరితనం వదలాలి; కాలాన్ని వృథా చేయకూడదు"]],["వ్యాసరూప (మిగతా), సృజనాత్మకత, పదజాలం (పుట 145)",["ఆ) 2) పరనింద – ఇతరులను దూషించడం తప్పు, మనలోని దోషాలు చూసుకోవాలి; పరధనాపేక్ష – సులభ ధనం, దోపిడీ మంచిది కాదు; సేవ – పరులకు ఊడిగం చేయడం కంటే భగవంతుడికి దాసుడవడం మేలు, ఆత్మగౌరవం ముఖ్యం; కులమతాలు – వాటికి ప్రాధాన్యం లేదు, నిజం తెలిసినవాడే మహాత్ముడు; ఆత్మపరిశీలన – విజయం మనదని, ఓటమి ఇతరులదని అనుకోకుండా మన తప్పులు గుర్తించాలి","3) అన్నమయ్య ప్రజాకవి. ఆనాటి సమాజంలోని కులమత భేదాలను ఖండించి సర్వసమానత్వం చాటాడు (\"నిండార రాజు\", \"బ్రహ్మమొక్కటే\"); పరనింద, పరధనాపేక్ష, సోమరితనం, యాచన, బానిసత్వాన్ని గర్హించాడు; ఆత్మపరిశీలన, ఆత్మనిగ్రహం, సరసజీవనం బోధించాడు; తేటతెలుగు మాటల్లో, జానపద బాణీల్లో నీతిని సామాన్యులకు అందించి సమాజాన్ని సంస్కరించాలని ఆశించాడు","ఇ) 1) గోడపత్రిక: \"అన్నమయ్య జయంతి / వర్ధంతి ఉత్సవాలు\" – అన్నమయ్య జన్మస్థలం తాళ్ళపాక (కడప జిల్లా); తిరుమలలో సంకీర్తనా గానం, గోష్ఠిగానం; పోటీలు – కీర్తనల గానం, వ్యాసరచన; అతిథులు, తేదీ, స్థలం","2) ప్రశ్నావళి: మీకు కవిత్వం రాయాలనే ప్రేరణ ఎలా వచ్చింది? మీకు నచ్చిన ప్రాచీన కవి ఎవరు? ఎందుకు? నన్నయ, తిక్కన, ఎర్రన గురించి చెప్పండి? ఆధునిక కవుల్లో మిమ్మల్ని ప్రభావితం చేసింది ఎవరు? విద్యార్థులు మంచి కవిత రాయాలంటే ఏం చేయాలి?","అ) 1) ఆద్యుడు = మొదటివాడు – నన్నయ తెలుగు కవులలో మొదటివాడు 2) అపేక్ష = కోరిక – చదువుకోవాలనే కోరిక మంచిది 3) సద్గతి = మంచి గతి, మోక్షం – మంచి పనులు మంచి గతినిస్తాయి 4) వాగ్గేయకారుడు = స్వయంగా రాసి, స్వరపరచి పాడేవాడు – త్యాగరాజు గొప్ప వాగ్గేయకారుడు 5) ఆరడి = బాధ, వేధింపు – జంతువులను బాధపెట్టకూడదు","ఆ) 1) ప్రాణం = ఉసురు, జీవం 2) కోరిక = వాంఛ, ఈప్సితం 3) ఒరులు = పరులు, ఇతరులు 4) మేను = శరీరం, దేహం 5) చింత = దిగులు, బెంగ 6) స్వర్గం = దివి, నాకం"]],["నానార్థాలు, ప్రకృతి–వికృతి, సంధులు (పుట 146)",["ఇ) 1) మతి = ఎలుక, తెలివి, బుద్ధి (4) 2) కులం = వంశం, జాతి, ఇల్లు (2) 3) గుణం = స్వభావం, వింటినారి, బుద్ధి (3) 4) సుధ = పాలు, అమృతం, సున్నం (1)","ఈ) భక్తి – బత్తి; స్థిరం – తిరం; ప్రాణం – పానం; భాష – బాస; నిజం – నిక్కం; గుణం – గొనం","అ) 1) సంకీర్తనాచార్యుడు = సంకీర్తన + ఆచార్యుడు (సవర్ణదీర్ఘ సంధి) 2) వైరాగ్యపు పద్ధతి = వైరాగ్యము + పద్ధతి (పుంప్వాదేశ సంధి) 3) నట్టనడుమ = నడుమ + నడుమ (ద్విరుక్తటకార / ఆమ్రేడిత సంధి) 4) పరమాత్ముడు = పరమ + ఆత్ముడు (సవర్ణదీర్ఘ సంధి)","ఆ) 1) పరధనాపేక్ష (సవర్ణదీర్ఘ సంధి) 2) దోషాలున్న (ఉకార సంధి) 3) సద్గతి (జశ్త్వ సంధి) 4) మహాత్ముడు (సవర్ణదీర్ఘ సంధి) 5) దీపముండగ (ఉకార సంధి)"]],["శ్చుత్వ సంధి, సమాసాలు, ముక్తపదగ్రస్తం (పుట 147)",["శ్చుత్వ సంధి: 1) సజ్జనులు = సత్ + జనులు – తకారానికి జకారం పరమై జకారం ఆదేశం 2) తపశ్శక్తి = తపస్ + శక్తి – సకారానికి శకారం పరమై శకారం ఆదేశం","ఇ) 1) మధురభక్తి – మధురమైన భక్తి (విశేషణ పూర్వపద కర్మధారయ) 2) పరులసొమ్ము – పరుల యొక్క సొమ్ము (షష్ఠీ తత్పురుష) 3) అసహ్యం – సహ్యం కానిది (నఞ్ తత్పురుష) 4) మధురమంజులం – మధురమైనదియు, మంజులమైనదియు (విశేషణ ఉభయపద కర్మధారయ) 5) సరసవర్తనం – సరసమైన వర్తనం (విశేషణ పూర్వపద కర్మధారయ)","ఈ) 1) మానవప్రయత్నం (షష్ఠీ తత్పురుష) 2) శక్తిసామర్థ్యాలు (ద్వంద్వ) 3) అవివేకి (నఞ్ తత్పురుష) 4) ఉత్తమలక్షణం (విశేషణ పూర్వపద కర్మధారయ) 5) పరధనాపేక్ష (చతుర్థీ తత్పురుష)","ముక్తపదగ్రస్తం: పద్యంలో మొదటి పాదం చివర \"…నూతనమా\" → రెండో పాదం \"తన మానిని…\"; \"…దక్కితిననుమా\" → \"ననుమానక…\"; \"…దనరం\" → \"దనరంతులు…\" – పాదం చివరి పదమే తర్వాతి పాదం మొదట వచ్చింది"]],["ప్రాజెక్టుపని (పుట 148)",["అన్నమయ్య సంకీర్తనలు: \"బ్రహ్మమొక్కటే పరబ్రహ్మమొక్కటే\", \"నానాటి బతుకు నాటకము\", \"అదివో అల్లదివో శ్రీహరివాసము\", \"ఎంత మాత్రమున ఎవ్వరు దలచిన\", \"కొండలలో నెలకొన్న కోనేటి రాయడు\" – సేకరించి, భావం రాసి, తరగతిలో పాడి ప్రదర్శించాలి"]]]}];
